Ceviri.ekle("bn","olay",{
"OLAYLAR_EK10:1832-01-01:0":{"b": ["ইজদিন (লামিয়া) গ্রিসের সীমানার ভেতরে থাকলো — আর্তা-ভোলোস রেখা", "930f63b8"], "d": ["স্বাধীন গ্রিক রাষ্ট্রের উত্তর সীমানা 1832 সালে আর্তা উপসাগর থেকে ভোলোস উপসাগর পর্যন্ত রেখায় টানা হলো। অটোমান যুগে (1424-1832) ইউবোয়া সানজাকের অধীন কাজা কেন্দ্র ইজদিন এই রেখার দক্ষিণে পড়ায় গ্রিসে গেল; থেসালির বাকি অংশ (ইয়েনিশেহির, তিরহালা) 1881 সাল পর্যন্ত অটোমানদের থাকলো।", "577080e0"]},
"OLAYLAR_EK10:1877-04-24:0":{"b": ["রাশিয়ার যুদ্ধ ঘোষণা — তিরানব্বই যুদ্ধের শুরু", "ac548ab8"], "d": ["1876 সালের বুলগেরীয় বিদ্রোহ দমন ইউরোপীয় জনমতে বিশাল ক্ষোভ জাগিয়েছিল, রাশিয়া বাব-ই আলিকে একঘরে করতে এটিকে চূড়ান্ত পর্যন্ত কাজে লাগিয়েছিল। ইস্তানবুল (তেরসানে) সম্মেলনের বুলগেরিয়াকে দুটি স্বায়ত্তশাসিত প্রদেশে ভাগ করার প্রস্তাব এবং এরপর 31 মার্চ 1877 তারিখের লন্ডন প্রটোকল অটোমান রাষ্ট্র প্রত্যাখ্যান করলে রাশিয়া 24 এপ্রিল 1877 তারিখে যুদ্ধ ঘোষণা করলো এবং তার সেনাবাহিনী নিজের পক্ষে টেনে আনা রোমানিয়া প্রিন্সিপালিটির ভূখণ্ডে প্রবেশ করলো (মানচিত্র ওয়ালাচিয়া-বোগদানকে এই মুহূর্ত থেকে এদির্ন যুদ্ধবিরতি পর্যন্ত রুশ অগ্রগতির ডোরাকাটা আচ্ছাদনে দেখায়)। রুমি পঞ্জিকায় 1293 সালে পড়ায় যুদ্ধ তিরানব্বই যুদ্ধ নামে পরিচিত। অভিযান দানিউব ও পূর্ব আনাতোলিয়া দুই ফ্রন্টে চললো: দানিউবে 180,000 লোকের অটোমান সেনাবাহিনী নদীর বাম তীরকে প্রথম, বলকান পর্বতকে দ্বিতীয় প্রতিরক্ষা রেখা গণ্য করেছিল; পূর্বে আহমেদ মুখতার পাশার 55,000 সৈন্য আর্দাহান-দোগুবায়াজিতের মধ্যে অবস্থান নিয়েছিল। এই যুদ্ধ মানচিত্রে অটোমান রুমেলির পতনের সূচনাকারী ঘটনা — বুলগেরিয়া, সার্বিয়া, মন্টিনিগ্রো ও রোমানিয়ার বর্তমান সীমানার সবই এই পনেরো মাসের ফল।", "a71008f1"]},
"OLAYLAR_EK10:1877-05-21:0":{"b": ["রোমানিয়ার স্বাধীনতা ঘোষণা — ওয়ালাচিয়া-বোগদান করদত্বের অবসান", "bdd164b3"], "d": ["93 যুদ্ধ ঘোষণার দুই সপ্তাহ পর রোমানিয়া প্রিন্সিপালিটি স্বাধীনতা ঘোষণা করলো এবং রাশিয়ার পক্ষে যুদ্ধে নামলো; প্লেভেন অবরোধে তার ভূমিকা অটোমান পরাজয়ে নির্ণায়ক হলো। চারশ বছরের বেশি ওয়ালাচিয়া ও বোগদান করদত্ব এভাবে কার্যত শেষ হলো; স্বাধীনতা বার্লিন কংগ্রেসে (1878) আন্তর্জাতিক স্বীকৃতি পেল। মানচিত্র এই তারিখ থেকে রোমানিয়াকে করদ নয়, নিজস্ব রঙে স্বাধীন রাষ্ট্র হিসেবে দেখায়। স্বাধীনতা ঘোষণার ফলে ওয়ালাচিয়া ও বোগদানের সমগ্র অংশ (ইয়াশ, গালাতি, ইবরাইল, ইয়ের্গোগু, কালাফাত, বোতোশানি প্রভৃতি) স্বাধীন রোমানিয়া হলো।", "9e037d13"]},
"OLAYLAR_EK10:1877-06-27:0":{"b": ["রুশ সেনাবাহিনীর দানিউব পারাপার — জিশতোভি ও তারনোভোর পতন", "811367b1"], "d": ["যুদ্ধ শুরুর সঙ্গে রোমানিয়ার ভূখণ্ডে ঢুকে এই প্রিন্সিপালিটিকে নিজ পক্ষে টানা রুশরা, একটি দোবরুজা অন্যটি বুখারেস্টের দিকে, দুই বাহু ধরে অগ্রসর হলো। দানিউব রুসচুক ও নিগবোলুর মধ্য দিয়ে পার করা হলো এবং 27 জুন জিশতোভি, 1 জুলাই প্রাচীন বুলগেরীয় রাজধানী তারনোভো দখল হলো। খালি করার আদেশ থাকলেও এ বিষয়ে যত্ন না নেওয়ায় নিগবোলুও কিছুক্ষণ প্রতিরোধের পর আত্মসমর্পণ করলো। প্রথম প্রতিরক্ষা রেখা এক সপ্তাহের মধ্যে ভেঙে যাওয়া ইস্তানবুলে বড় আতঙ্ক সৃষ্টি করলো; সালতানাতের কেন্দ্র বুরসায় সরানো হবে এমন খবরও ছড়ালো এবং যুদ্ধ পরিচালনা রাজধানীতে গঠিত এক সামরিক পরিষদের হাতে গেল।", "f266b11c"]},
"OLAYLAR_EK10:1877-07-19:0":{"b": ["শিপকা গিরিপথ খালি — বলকান রেখা ভেঙে যাওয়া", "1f45e50a"], "d": ["বলকান পর্বত পেরোনো গিরিপথগুলোর মধ্যে সবচেয়ে কৌশলগত শিপকার অটোমান বাহিনী রুশ আক্রমণ তীব্রভাবে প্রতিহত করলো; তবে পরাজিত হবে বলে বিশ্বাস করে 19 জুলাই গোপনে গিরিপথ খালি করলো। এভাবে দ্বিতীয় প্রতিরক্ষা রেখাও খুলে গেল এবং জেনারেল গুর্কো 22 জুলাই এস্কি জাগরা দখল করলেন। মন্টিনিগ্রো দিক থেকে এসে পৌঁছানো সুলাইমান পাশা গুর্কোকে পরাজিত করে বলকানের দক্ষিণের দখলকৃত স্থানগুলো ফিরিয়ে নিলেও 21 আগস্ট থেকে মাসের পর মাস চলা আক্রমণ সত্ত্বেও শিপকা ফিরিয়ে নিতে পারলেন না। মানচিত্রে এটি বলকান পর্বতমালার উত্তর ও দক্ষিণের মধ্যকার প্রতিরক্ষা সংহতি আর কখনো গড়া না যাওয়া: দানিউব ফ্রন্টের লড়াই এরপর প্লেভেনে গিঁট পাকাবে।", "3463a17b"]},
"OLAYLAR_EK10:1877-08-23:0":{"b": ["লোভচা রুশ সেনাবাহিনীর দখলে", "70e54611"], "d": ["93 যুদ্ধে লোভচা 5 জুন 1877 তারিখে রুশদের দখলে এসেছিল, রিফাত পাশার নেতৃত্বাধীন অটোমান বাহিনী 15 জুন রুশদের হটিয়ে দিয়েছিল; শহর 23 আগস্ট অটোমানদের ত্যাগে আবার রুশ দখলে গেল। মানচিত্র লোভচাকে এই দিন থেকে বার্লিন চুক্তি পর্যন্ত রুশ দখলের অধীনে (ডোরাকাটা) দেখায়; আইনত অটোমান ভূখণ্ড থেকে যায়।", "45e61a80"]},
"OLAYLAR_EK10:1877-11-18:0":{"b": ["কার্সের পতন — পূর্ব ফ্রন্ট ভেঙে পড়া ও আজিজিয়ে দুর্গ", "53fc3bf5"], "d": ["পূর্ব আনাতোলিয়ায় কার্স, দোগুবায়াজিত ও আর্দাহানের দিকে তিন বাহুতে অগ্রসর রুশরা 30 এপ্রিল দোগুবায়াজিত নিয়েছিল, আর্দাহানে ঢুকেছিল, কিন্তু এরজুরুমের দিকে অগ্রসর হওয়ার সময় 15 জুলাই পরাজিত হয়ে সীমান্তের বাইরে বিতাড়িত হয়েছিল। আহমেদ মুখতার পাশাকে 'গাজি' উপাধি এনে দেওয়া এই সাফল্য আগস্টে জেনারেল লাজারোভের পুনরায় আক্রমণে উল্টে গেল এবং 18 নভেম্বর কার্স পতিত হলো। আরও উপযুক্ত প্রতিরক্ষার জন্য এরজুরুমে সরে যাওয়া অটোমান বাহিনী আজিজিয়ে দুর্গে, নেনে হাতুন জনগণকে উৎসাহ দেওয়ায়, বড় প্রতিরোধ দেখালো। কার্স, আর্দাহান ও বাতুম আট মাস পর বার্লিনে যুদ্ধক্ষতিপূরণের একাংশের বিনিময়ে রাশিয়াকে ছেড়ে দেওয়া হবে।", "07faf844"]},
"OLAYLAR_EK10:1912-10-08:0":{"b": ["প্রথম বলকান যুদ্ধের শুরু — মন্টিনিগ্রোর যুদ্ধ ঘোষণা", "c0c2697e"], "d": ["বলকান রাষ্ট্রগুলো ইত্তিহাদ ও তেরাক্কির 3 জুলাই 1911 তারিখের আইনে গির্জা সমস্যা সমাধানের পর নিজেদের মধ্যকার সবচেয়ে বড় বাধা সরিয়েছিল, রাশিয়ার উসকানিতে 1912 জুড়ে পরস্পরের সঙ্গে মৈত্রী চুক্তি স্বাক্ষর করেছিল (13 মার্চ সার্বিয়া-বুলগেরিয়া, 29 মে বুলগেরিয়া-গ্রিস, আগস্টে মন্টিনিগ্রো-বুলগেরিয়া, 6 অক্টোবর মন্টিনিগ্রো-সার্বিয়া)। বাব-ই আলি এটি টের পেল না; এমনকি রাশিয়ার নিশ্চয়তায় ভরসা করে রুমেলির 120 প্রশিক্ষিত ব্যাটালিয়ন ছুটি দিল। চার রাষ্ট্র 3 অক্টোবর যৌথ নোট দিয়ে মেসিডোনিয়া, আলবেনিয়া ও ক্রিটের জন্য স্বায়ত্তশাসন চাইলো; উত্তর না পেয়ে 8 অক্টোবর 1912 তারিখে মন্টিনিগ্রোর যুদ্ধ ঘোষণায় অভিযান শুরু হলো। 13 অক্টোবর সার্বিয়া ও বুলগেরিয়ার দূতদের পাসপোর্ট হাতে ধরিয়ে দেওয়া হলো, পরদিন এই দুই রাষ্ট্র, এরপর গ্রিস যুদ্ধ ঘোষণা করলো। যুদ্ধের সময় সেনাবাহিনীর ভেতরের রাজনৈতিক মতভেদ পরাজয়ে বড় ভূমিকা রাখলো।", "3a0fab7d"]},
"OLAYLAR_EK10:1912-10-20:0":{"b": ["রোডোপে কিরজালি দল ভেঙে পড়লো, কিরজালি পতিত", "8cf59b7f"], "d": ["বুলগেরীয় যুদ্ধ ঘোষণার পর রোডোপ থেকে নামা বুলগেরীয় বাহিনী মেহমেদ ইয়াভের পাশার কিরজালি দলকে পরাজিত করে কিরজালিতে প্রবেশ করলো। বিপর্যস্ত দল গুমুলজিনার দিকে সরে গেল; রোডোপের পূর্ব অংশ যুদ্ধের প্রথম সপ্তাহে হাতছাড়া হলো।", "c675e240"]},
"OLAYLAR_EK10:1912-10-23:0":{"b": ["প্রাচ্য সেনাবাহিনীর বিপর্যয় ও চাতালকা রেখায় পশ্চাদপসরণ — কুমানোভো ও সালোনিকা হারানো", "cf95591a"], "d": ["অটোমান প্রাচ্য সেনাবাহিনী 23 অক্টোবর 1912 তারিখে নিজেদের তিনগুণ বড় বুলগেরীয় বাহিনীর কাছে পরাজিত হয়ে ইস্তানবুলের ত্রিশ কিলোমিটার পশ্চিমের চাতালকা রেখা পর্যন্ত সরে গেল; রাজধানী যুদ্ধের প্রথম মাসেই সরাসরি হুমকির মুখে পড়লো। একই দিনগুলোতে পশ্চিম সেনাবাহিনী 23-24 অক্টোবর কুমানোভোয় সার্বদের কাছে পরাজিত হলো এবং তাহসিন পাশা 35,000 লোকের সেনাবাহিনী নিয়ে সালোনিকায় গ্রিকদের কাছে আত্মসমর্পণ করলেন। এই বিপর্যয়ে 29 অক্টোবর গাজি আহমেদ মুখতার পাশার মন্ত্রিসভা পদত্যাগ করলো; সালোনিকায় নির্বাসন জীবন কাটানো দ্বিতীয় আবদুলহামিদ 1 নভেম্বর ইস্তানবুলে স্থানান্তরিত হলেন। চাতালকা রেখা যুদ্ধের শেষ পর্যন্ত ধরে রাখা হলো — রুমেলির পাঁচশ বছরের অটোমান ভূগোল কয়েক সপ্তাহের মধ্যে এই সংকীর্ণ ফালিতে নেমে এলো।", "376c6d31"]},
"OLAYLAR_EK10:1912-10-23:1":{"b": ["ইয়েনিপাজার সানজাকের কেন্দ্রে প্রিন্স আলেকসান্দার প্রবেশ করলেন", "326d0616"], "d": ["সার্ব বাহিনী যুদ্ধের প্রথম সপ্তাহে ইয়েনিপাজার নিল এবং পশ্চিম থেকে আসা মন্টিনিগ্রো বাহিনীর সঙ্গে মিলিত হলো। সার্বিয়া ও মন্টিনিগ্রোকে একশ বছর আলাদা রাখা ইয়েনিপাজার সানজাক এভাবে দুই মিত্রের মধ্যে সেতুতে পরিণত হলো।", "afe8a034"]},
"OLAYLAR_EK10:1912-10-24:0":{"b": ["কিরকলিসে যুদ্ধের পর কিরকলারেলি হাতছাড়া", "eda4c759"], "d": ["পূর্ব থ্রেসে প্রাচ্য সেনাবাহিনী কিরকলিসে যুদ্ধে পরাজিত হওয়ায় কোলেমেন আবদুল্লাহ পাশার রক্ষা করা শহর বুলগেরীয় বাহিনীর হাতে ছেড়ে দেওয়া হলো। শহর নয় মাস স্থায়ী দখল থেকে কেবল দ্বিতীয় বলকান যুদ্ধে, 21 জুলাই 1913 তারিখে মুক্ত হলো।", "ee5cf8d2"]},
"OLAYLAR_EK10:1912-10-26:0":{"b": ["কসোভো প্রদেশের কেন্দ্র উস্কুপ প্রতিরোধ ছাড়াই ছেড়ে দেওয়া", "455d9b71"], "d": ["কুমানোভো বিপর্যয়ের (23-24 অক্টোবর) পর কসোভো প্রদেশের কেন্দ্র উস্কুপ অরক্ষিত থাকলো। জনগণ শহরের আশেপাশে লড়াই চাইছিল না বলে কনসালদের মাধ্যমে আমন্ত্রিত প্রিন্স আলেকসান্দারের নেতৃত্বাধীন সার্ব বাহিনী 26 অক্টোবর সন্ধ্যায় শহরে প্রতিরোধ ছাড়াই প্রবেশ করলো।", "3992a650"]},
"OLAYLAR_EK10:1912-10-28:0":{"b": ["ভারদার তীরে কোপরুলু (ভেলেস) হারানো", "73d20b7d"], "d": ["উস্কুপের পতনের দুই দিন পর ভারদার বরাবর দক্ষিণে নামা সার্ব সেনাবাহিনী কোপরুলু নিল। সালোনিকায় খোলা ভারদার উপত্যকার দরজা এভাবে সার্বদের হাতে গেল।", "e762a0e1"]},
"OLAYLAR_EK10:1912-10-29:0":{"b": ["ব্রেগালনিৎসা অববাহিকা: জেনারেল স্তেফানোভিচ ইশতিপে প্রবেশ করলেন", "70a84256"], "d": ["জেনারেল স্তেফানোভিচের নেতৃত্বাধীন সার্ব ইউনিট ইশতিপ প্রতিরোধের মুখোমুখি না হয়ে নিল; শহরে প্রথমে অনিয়মিত দল প্রবেশ করলো। কুমানোভোর পর পূর্ব মেসিডোনিয়ার ব্রেগালনিৎসা অববাহিকা সার্ব নিয়ন্ত্রণে গেল।", "3b2e609b"]},
"OLAYLAR_EK10:1912-10-29:1":{"b": ["সারান্তাপোরো গিরিপথের পর কারাফেরিয়া গ্রিক আধিপত্যে গেল", "02a68e02"], "d": ["থেসালি থেকে উত্তরে অগ্রসর গ্রিক সেনাবাহিনী সারান্তাপোরো (কিরকগেচিত) গিরিপথ পেরোনোর পর কারাফেরিয়ায় আধিপত্য নিল। শহরের মুসলিম জনসংখ্যার একাংশ এই সময়ে অঞ্চল ত্যাগ করলো।", "a76cea57"]},
"OLAYLAR_EK10:1912-10-31:0":{"b": ["সালোনিকা-মনাস্তির রেলপথের ভোদিনা হারানো", "fc15b917"], "d": ["সালোনিকা-মনাস্তির রেলপথের ভোদিনা গ্রিক সেনাবাহিনীর হাতে গেল। স্লাভ ও তুর্কি জনগোষ্ঠীর জোর করে বিচ্ছিন্ন হওয়ায় শহরের জনসংখ্যা অল্প সময়ে গুরুতরভাবে কমলো।", "e28f0a57"]},
"OLAYLAR_EK10:1912-11-02:0":{"b": ["ইয়েনিজে যুদ্ধ — ইয়েনিজে-ই ভারদার গ্রিকদের হাতে গেল", "8f6cb76e"], "d": ["হাসান তাহসিন পাশার 8ম মিশ্র কোর সালোনিকার পশ্চিমের ইয়েনিজেতে গ্রিক সেনাবাহিনীর কাছে পরাজিত হয়ে সালোনিকা অঞ্চলে সরে গেল। যুদ্ধের সময় শহরের বড় অংশ পুড়লো; সালোনিকার পথ গ্রিক সেনাবাহিনীর জন্য খুলে গেল।", "d0f12da4"]},
"OLAYLAR_EK10:1912-11-03:0":{"b": ["কসোভোর দক্ষিণ-পশ্চিমে প্রিজরেন আত্মসমর্পণ করলো", "bae6b1b9"], "d": ["কসোভোর দক্ষিণ-পশ্চিমের প্রিজরেন সার্ব বাহিনীর কাছে আত্মসমর্পণ করলো। শহরে ঢোকা ইউনিটগুলোর মুসলিম জনগণের প্রতি আচরণ কসোভোতে যুদ্ধের সবচেয়ে ভারী অধ্যায়গুলোর একটি হিসেবে নথিভুক্ত হলো।", "8cf0b7ae"]},
"OLAYLAR_EK10:1912-11-05:0":{"b": ["কর্নেল মিতভ উস্ত্রুমজায় সামরিক আইন ঘোষণা করলেন", "bcad75cc"], "d": ["বুলগেরীয় কর্নেল মিতভ উস্ত্রুমজায় প্রবেশ করে সামরিক আইন ঘোষণা করলেন; পরদিন চলে যাওয়ার সময় শহর একজন বুলগেরীয় কাইমাকাম ও একজন সার্ব অধিনায়কের হাতে ছেড়ে দিলেন। উস্ত্রুমজা যুদ্ধের সময় মিত্রদের মধ্যে হাতবদল হলো এবং 1913 সালে বুলগেরিয়ার সঙ্গে যুক্ত হলো।", "acfc04ac"]},
"OLAYLAR_EK10:1912-11-08:0":{"b": ["হাসান তাহসিন পাশা সালোনিকা গ্রিকদের ছেড়ে দিলেন", "1738933c"], "d": ["ইয়েনিজে পরাজয়ের পর সালোনিকায় সরে আসা হাসান তাহসিন পাশা বুলগেরীয় সেনাবাহিনী উত্তর থেকে এগিয়ে আসার সময় শহর গ্রিকদের ছেড়ে দিলেন; গ্রিক সেনাবাহিনী 8 নভেম্বর দুপুরের দিকে শহরে প্রবেশ করলো। অটোমান রুমেলির সবচেয়ে বড় বন্দর শহর এবং ইত্তিহাদ ও তেরাক্কির জন্মস্থান সালোনিকা এভাবে হাতছাড়া হলো।", "e65f92fc"]},
"OLAYLAR_EK10:1912-11-21:0":{"b": ["পশ্চিম থ্রেসের কেন্দ্র গুমুলজিনা বুলগেরীয়দের জন্য খুলে গেল", "96eec25f"], "d": ["কিরজালি থেকে সরে আসা ইয়াভের পাশার দলের ফেরেসের দিকে পিছু হটার ফলে গুমুলজিনা বুলগেরীয় বাহিনীর কাছে আত্মসমর্পণ করলো। পশ্চিম থ্রেসের কেন্দ্র যুদ্ধের শেষে বুলগেরিয়াকে ছেড়ে দেওয়া হবে এমন ভূখণ্ডের শীর্ষে ছিল।", "dab74d84"]},
"OLAYLAR_EK10:1912-11-28:0":{"b": ["এলবাসানে পৌঁছানো সার্বরা একই দিনে দেবরে প্রবেশ করলো", "16720246"], "d": ["মনাস্তির থেকে পশ্চিমে অগ্রসর সার্ব বাহিনী এলবাসানে পৌঁছানোর দিন দেবরেও প্রবেশ করলো এবং আদ্রিয়াটিকের দিকে নামলো। একই দিনে আভলোনায় আলবেনিয়ার স্বাধীনতা ঘোষিত হচ্ছিল।", "6e52cff7"]},
"OLAYLAR_EK11:1401-01-01:0":{"b": ["তৈমুর বাগদাদ দ্বিতীয়বার দখল করলেন — শহরের আব্বাসি মহল্লা ধ্বংস", "04b68a24"], "d": ["তৈমুর বাগদাদ আট বছরের ব্যবধানে দুবার নিলেন। 1393 সালের প্রথম দখলে শহরের বেশি ক্ষতি হয়নি; 1401 সালের দ্বিতীয়টি অবশ্য বাগদাদের সাংস্কৃতিক জীবনে দ্বিতীয় ভারী আঘাত গণ্য — জনগণকে তরবারির আঘাতে হত্যা করা হলো, আব্বাসি যুগের মহল্লা ও ভবনের অধিকাংশ ধ্বংস হলো। জালায়িরি শাসক আহমেদ 1405 সালে শহরে ফিরে ধ্বংস হওয়া প্রাচীর ও বাজার মেরামতের চেষ্টা করলেও সময় পেলেন না; বাগদাদ 1410 সালে কারাকোয়ুনলু তুর্কমেনদের হাতে গেল। এই দুই দখল আঙ্কারা যুদ্ধের পথে তৈমুর অটোমান ও মামলুক সীমান্তের কতটা কাছে এসেছিলেন তা দেখানো সবচেয়ে বাস্তব পদক্ষেপগুলোর একটি।", "b24ba76b"]},
"OLAYLAR_EK11:1422-01-01:0":{"b": ["জুনেইদ বে আয়দিন-ইলির প্রধান হয়ে ফিরলেন — আয়দিনোগুল্লারি আবার স্বাধীন", "63281658"], "d": ["চেলেবি মেহমেদ 1414-15 সালে ইজমির নিয়ে জুনেইদ বেকে নিগবোলু সানজাক বেইত্বে পাঠিয়ে আয়দিন-ইলিকে অটোমান প্রশাসনে বেঁধেছিলেন। চেলেবি মেহমেদের মৃত্যুর পর, বাইজান্টিয়াম যাঁকে সিংহাসনের দাবিদার হিসেবে সামনে এনেছিল সেই মুস্তাফা চেলেবির পাশে জুনেইদ আবার মঞ্চে এলেন এবং তাঁর উজিরও হলেন। দ্বিতীয় মুরাদ পুরনো বেগলিক ফিরিয়ে দেওয়ার প্রতিশ্রুতিতে তাঁকে এই মিত্রতা থেকে আলাদা করলেন; জুনেইদও ইজমিরে ফিরে আয়াসুলুক দখল করলেন এবং আয়দিনোগলু মুস্তাফা বেকে হত্যা করে বেগলিকের প্রধান হলেন। এভাবে আয়দিন-ইলি ভুয়া মুস্তাফা সংকটের ভেতর থেকে অটোমান শাসন থেকে বেরিয়ে জন্ম নিল।", "c5020860"]},
"OLAYLAR_EK11:1426-01-01:0":{"b": ["জুনেইদ বে ও পরিবারের মৃত্যুদণ্ড — আয়দিনোগুল্লারি বেগলিকের অবসান", "efa684ba"], "d": ["আয়দিন-ইলিতে আবার কর্তৃত্ব নেওয়া জুনেইদ বে আনাতোলীয় বেদের উসকানি দেওয়ায় ও ভেনিসের সঙ্গে যোগাযোগ খোঁজায় দ্বিতীয় মুরাদ আনাতোলিয়া বেইলারবেই হামজা বেকে তাঁর বিরুদ্ধে পাঠালেন। পুত্র কুর্দ হাসান আকহিসারের কাছে পরাজিত হয়ে বন্দি হলে জুনেইদ সামোস দ্বীপের বিপরীতে ইপসিলিতে সরে যান; কারামানোগলুর কাছ থেকে আশা করা সাহায্য না আসায় এবং অটোমানদের সঙ্গে একত্রে চলা জেনোয়াবাসীরা সমুদ্র থেকে অবরোধ করায় তিনি আত্মসমর্পণে বাধ্য হলেন; তাঁকে পুরো বংশসহ নিশ্চিহ্ন করা হলো। আয়দিনোগুল্লারি ভূখণ্ড এভাবে সম্পূর্ণ অটোমান শাসনে এলো।", "662b578c"]},
"OLAYLAR_EK11:1502-01-01:0":{"b": ["এরজুরুম ও ভান অববাহিকা সাফাভিদের হাতে গেল — আককোয়ুনলুর উত্তর বাহু ধসে পড়লো", "b418875f"], "d": ["শারুরে আলভেন্দ বেকে পরাজিত করে 1501 সালের গ্রীষ্মে তাবরিজে প্রবেশ করা শাহ ইসমাইল পরের বছর উত্তর-পশ্চিম দিকে অগ্রসর হয়ে এরজুরুম থেকে ভান হ্রদ অববাহিকা পর্যন্ত রেখা নিজের আধিপত্যে নিলেন। আককোয়ুনলু রাষ্ট্র উজুন হাসানের মৃত্যুর পর সিংহাসন কলহে ইতিমধ্যেই দুই ভাগে ভাঙা ছিল: আলভেন্দ বে আজারবাইজান ও দিয়ারবাকির, চাচাতো ভাই মুরাদ ইরাক-ই আজম ও ফারস ধরে রেখেছিলেন। এই বিভাজন সাফাভি অগ্রগতি সহজ করলো; অঞ্চল এক বছরের মধ্যে হাতবদল হলো। এরজুরুম এরপর ষোলো বছর সাফাভি হাতে থাকলো এবং অটোমান আধিপত্যে এলো কেবল চালদিরানের পর, 1518-19 সালে। এই বছরে (1502) আশকালে ও পাসিনলার (হাসানকালে) এরজুরুম অঞ্চলসহ আককোয়ুনলু থেকে সাফাভিদের হাতে গেল (দিন যাচাই করা যায়নি)।", "3a68635d"]},
"OLAYLAR_EK11:1503-01-01:0":{"b": ["মুরাদ বের হামাদান পরাজয়: ইরাক-ই আজম ও ফারস সাফাভিদের হাতে গেল", "8de07a31"], "d": ["আককোয়ুনলু সিংহাসনের দ্বিতীয় দাবিদার সুলতান মুরাদ শাহ ইসমাইলের বিরুদ্ধে হামাদানের কাছে হওয়া যুদ্ধে ভারী পরাজয় বরণ করে বাগদাদে পালালেন। এই একটি যুদ্ধেই ইরাক-ই আজম, ফারস ও কিরমান অঞ্চল সাফাভি শাসনে এলো; মানচিত্রে এই অঞ্চলগুলো একই সময়ে হাতবদল হয়। আককোয়ুনলু রাষ্ট্রের বিলুপ্তির সবচেয়ে বড় একক পদক্ষেপ এটি — তাবরিজ হারানো রাজবংশকে রাজধানীহীন করেছিল, হামাদান পরাজয় ভূখণ্ডহীন করলো।", "f9d2ba4d"]},
"OLAYLAR_EK11:1504-12-06:0":{"b": ["শাহ ইসমাইল ইয়াজদে প্রবেশ করলেন: আককোয়ুনলু অবশিষ্টাংশের মধ্য ইরানের শেষ দুর্গ পতিত", "6f9835df"], "d": ["1503 হামাদান পরাজয়ের পর ইরাক-ই আজম ও ফারস সাফাভিদের হাতে গেলেও ইয়াজদ আককোয়ুনলু রাজবংশের বায়িন্দিরলি মুরাদ বের হাতে আলাদা থেকে গিয়েছিল। শহর এক মাসের অবরোধে পতিত হলো এবং মধ্য ইরানের শেষ আককোয়ুনলু দ্বীপ বন্ধ হলো। TDV-এর নথি: \"শাহ ইসমাইল এক মাসের অবরোধের পর 28 জমাদিউস সানি 910 (6 ডিসেম্বর 1504) তারিখে শহরে প্রবেশ করেন।\"", "577a0ec7"]},
"OLAYLAR_EK11:1507-01-01:0":{"b": ["শাহ ইসমাইলের দিয়ারবাকির অভিযান: আককোয়ুনলুর শেষ কেন্দ্রগুলো পতিত", "b6d8504e"], "d": ["আজারবাইজান ও ইরান মালভূমি দখল করা শাহ ইসমাইল 1507 সালে পশ্চিমে, আককোয়ুনলু রাজবংশের জন্মস্থান দিয়ারবাকির অঞ্চলের দিকে এগোলেন। আমিদ থেকে মারদিন, উরফা থেকে হারপুত পর্যন্ত বিস্তৃত রেখা দুই ধাপে সাফাভি শাসনে এলো এবং আককোয়ুনলুরা কার্যত বিলুপ্ত হলো। এই অভিযান একই সঙ্গে সাফাভি সীমান্তকে প্রথমবার অটোমান ও মামলুক সীমান্তের গায়ে লাগালো; চালদিরানে যাওয়া উত্তেজনার ভৌগোলিক ভিত্তি এভাবে গড়া হলো।", "d0346bf4"]},
"OLAYLAR_EK11:1508-01-01:0":{"b": ["বাগদাদের সাফাভিদের হাতে যাওয়া — ইরাক-ই আরাব হাতবদল", "39730186"], "d": ["হামাদান পরাজয়ের পর বাগদাদে আশ্রয় নেওয়া আককোয়ুনলু সুলতান মুরাদের পেছনে শাহ ইসমাইল 1508 সালে ইরাক-ই আরাবে প্রবেশ করলেন এবং বাগদাদ নিলেন। কারবালা ও নাজাফের সমাধিস্থল সাফাভি শাসনে যাওয়া আন্দোলনের মাজহাবি দাবির দিক থেকে তাবরিজ দখলের মতো গুরুত্বপূর্ণ ছিল। মানচিত্রে ইরাক-ই আরাব একই দিনে হাতবদল হয়; এটি বিলুপ্তির শেষ ও সবচেয়ে বিস্তৃত ভৌগোলিক পদক্ষেপ। বাগদাদ 1534 সালে কানুনির ইরাকেইন অভিযান পর্যন্ত সাফাভি হাতে থাকলো।", "10e3e563"]},
"OLAYLAR_EK11:1510-12-02:0":{"b": ["মারভ যুদ্ধ: উজবেকরা ভারী পরাজয় বরণ করলো, মারভ ও হেরাত দখল", "f8e45aaf"], "d": ["পশ্চিমে আককোয়ুনলু উত্তরাধিকার সম্পূর্ণ করা শাহ ইসমাইল পূর্বে খোরাসানে অভিযান চালালেন এবং মারভের সামনে উজবেকদের ভারী পরাজয়ে ফেললেন; শেইবানি খান যুদ্ধক্ষেত্রে নিহত হলেন। মারভ ও হেরাত সাফাভি আধিপত্যে এলো এবং সাফাভি রাষ্ট্র ফোরাত থেকে আমু দরিয়া পর্যন্ত বিস্তৃত সীমানা পেল। এভাবে 1501 সালের গ্রীষ্মে তাবরিজ প্রবেশে শুরু হওয়া প্রক্রিয়া নয় বছরে সম্পূর্ণ হলো: আককোয়ুনলু উত্তরাধিকার পুরোপুরি সাফাভি শাসনে গেল এবং অটোমান রাষ্ট্র পূর্বে নিজের সমান বড় দ্বিতীয় রাষ্ট্রের প্রতিবেশী হলো।", "ae88b613"]},
"OLAYLAR_EK11:1539-02-24:0":{"b": ["জাবিদের অটোমান আধিপত্যে চূড়ান্ত অন্তর্ভুক্তি", "ddd971c7"], "d": ["দিউ অবরোধ 5 নভেম্বর 1538 তারিখে তুলে নেওয়া নৌবহর ফেরার পথে ইয়েমেন উপকূলে থামলো এবং জাবিদ চূড়ান্তভাবে অটোমান শাসনে যুক্ত হলো; হাদিম সুলাইমান পাশা 10 মার্চ 1539 তারিখে শহর ছেড়ে 1 এপ্রিল জেদ্দায় পৌঁছালেন। শহর 1517 সাল থেকে সাবেক মামলুক বেদের হাতে অটোমানদের নামে শাসিত হচ্ছিল; এই তারিখে সরাসরি প্রশাসনে গেল।", "5718f027"]},
"OLAYLAR_EK11:1581-04-16:0":{"b": ["ইবেরীয় ইউনিয়ন: পর্তুগিজ মুকুট স্পেনের রাজার হাতে গেল", "1cc6dfdc"], "d": ["কার্ডিনাল রাজা এনরিকের উত্তরাধিকারহীন মৃত্যুতে খোলা উত্তরাধিকার কলহ আলকান্তারা যুদ্ধে (25 আগস্ট 1580) স্পেনের পক্ষে শেষ হলো এবং তোমারে মিলিত পর্তুগিজ কোর্তেস 16 এপ্রিল 1581 তারিখে দ্বিতীয় ফিলিপকে পর্তুগালের রাজা হিসেবে স্বীকৃতি দিল। তোমার শর্ত অনুযায়ী পর্তুগাল নিজের প্রতিষ্ঠান, মুদ্রা ও ভাষা রক্ষা করবে, প্রশাসনে কেবল পর্তুগিজরা নিযুক্ত হবে, মাদ্রিদে আলাদা পর্তুগিজ পরিষদ থাকবে — অর্থাৎ একীভবন ছিল ব্যক্তিগত ইউনিয়ন, অন্তর্ভুক্তি নয়।", "40bd79df"]},
"OLAYLAR_EK11:1640-12-01:0":{"b": ["রেস্তাউরাসাও: পর্তুগাল স্বাধীনতা ফিরে পেল", "64ec0738"], "d": ["কাতালোনিয়া বিদ্রোহ স্পেনকে ব্যস্ত রাখা দিনগুলোতে লিসবনে একদল অভিজাত প্রাসাদে অতর্কিত হামলা চালিয়ে স্পেনীয় শাসন উৎখাত করলেন এবং ব্রাগাঁসার ডিউককে চতুর্থ জোয়াও নামে রাজা ঘোষণা করলেন। ষাট বছরের ইবেরীয় ইউনিয়ন এভাবে শেষ হলো; তবে সেউতা স্পেনে থাকা বেছে নিল এবং এটি 1668 সালের লিসবন চুক্তিতে স্বীকৃত হলো। পর্তুগাল হাবসবুর্গ যুদ্ধের সঙ্গে জুড়ে যাওয়া এই সময়পর্ব এশিয়ায় তার ক্ষতিরও কাঠামো: হরমুজ 1622 সালে, মালাক্কা 1641 সালে, কলম্বো 1656 সালে হাতছাড়া হলো; তাঙ্গিয়ের ও বোম্বে স্বাধীনতার মূল্য হিসেবে ইংল্যান্ডকে দেওয়া হলো। সূত্র: Britannica, History of Portugal — Restoration।", "bb04bea3"]},
"OLAYLAR_EK11:1662-01-30:0":{"b": ["তাঞ্জিয়ার ইংল্যান্ডের হাতে হস্তান্তর", "1f7cad6d"], "d": ["পর্তুগালের স্বাধীনতা যুদ্ধে ইংরেজ সমর্থন নিশ্চিত করতে সম্পাদিত বিবাহ চুক্তির (23 জুন 1661) দ্বিতীয় ধারায় তাঞ্জিয়ার ক্যাথরিন অব ব্রাগানজার যৌতুক হিসেবে ইংল্যান্ডকে ছেড়ে দেওয়া হয়। স্যান্ডউইচের আর্লের নৌবহর 29 জানুয়ারি 1662 তারিখে নোঙর ফেলে এবং পরদিন পিটারবরোর আর্লের উপস্থিতিতে আনুষ্ঠানিক হস্তান্তর সম্পন্ন হয়। ইংরেজরা 1684 সালে শহরটি ত্যাগ করবে।", "9328c723"]},
"OLAYLAR_EK11:1747-06-20:0":{"b": ["নাদির শাহের হত্যা — আফশার আধিপত্যের পতন", "19c218c0"], "d": ["সাফাভি সিংহাসনের অবসান ঘটিয়ে 1736 সালে নিজের নামে সুলতানি ঘোষণা করা, ভারত অভিযানে দিল্লি পর্যন্ত পৌঁছানো এবং অটোমানদের সঙ্গে তিনটি যুদ্ধ করে 1746 সালের কেরদান চুক্তিতে শান্তি স্থাপনকারী নাদির শাহ নিজের দেহরক্ষীদের হাতে তাঁবুতে নিহত হন। এরপর ইরান আর একক হাতে শাসিত হয়নি: খোরাসানে আফশার অবশিষ্টাংশ, দক্ষিণে জান্দ এবং উত্তরে উঠতি কাজার উনপঞ্চাশ বছর ধরে দেশটি ভাগ করে নেয়। এই বিশৃঙ্খলার কারণে অটোমান পূর্ব সীমান্ত দীর্ঘ সময় শান্ত ছিল। নাদির শাহ 20 জুন 1747 তারিখে নিহত হন; টিডিভির মতে ইরেভান খানাত একই বছর (1747) প্রতিষ্ঠিত হয় (দিন যাচাই করা যায়নি)।", "747f1012"]},
"OLAYLAR_EK11:1796-01-01:0":{"b": ["কাজার রাজবংশের ইরানে আধিপত্য প্রতিষ্ঠা", "744b48c5"], "d": ["কাজার গোত্রপ্রধান আগা মুহাম্মদ খান জান্দ শাসন উৎখাত করে এবং খোরাসানে আফশারদের শেষ প্রতিরোধ ভেঙে ইরানকে আবার এক হাতে একত্র করেন ও তেহরানকে রাজধানী করেন। এভাবে উনপঞ্চাশ বছরের বিভক্তির যুগ শেষ হয়; এরপর 1923 সাল পর্যন্ত অটোমানদের পূর্বের প্রতিবেশী ছিল কাজার ইরান। টিডিভি ইসলাম বিশ্বকোষ অনুসারে মাশহাদ 1796 সালে আগা মুহাম্মদ শাহের সামনে আফশার শাসক শাহরুখ কর্তৃক অভ্যর্থিত হয় এবং কাজার আধিপত্যের অধীনে আসে (সূত্রে দিন নেই)।", "755b544a"]},
"OLAYLAR_EK12:1527-09-23:0":{"b": ["ফের্দিনান্দ বুদিন দখল করলেন — জাপোলিয়াই রাজধানী থেকে বিতাড়িত", "99f77c29"], "d": ["মোহাচের পর হাঙ্গেরীয় সিংহাসনে দুজন রাজা দাঁড়ায়: অভিজাতদের একাংশ ইয়ানোশ জাপোলিয়াইকে, অন্যরা হাবসবুর্গ ফের্দিনান্দকে নির্বাচিত করেছিল। ফের্দিনান্দ 1527 সালে বুদিন দখল করে জাপোলিয়াইকে রাজধানী থেকে বিতাড়িত করেন; জাপোলিয়াই সুলতান সুলায়মানের সাহায্য চান। এ কারণেই 1529 সালের ভিয়েনা অভিযানের প্রথম লক্ষ্য ছিল বুদিন।", "e45db1f0"]},
"OLAYLAR_EK12:1537-01-01:0":{"b": ["বারবারোসার এজিয়ান দ্বীপ অভিযান — নাক্সোস ডাচি অটোমান নিয়ন্ত্রণে", "722b2fea"], "d": ["1207 সাল থেকে ভেনিসের আশ্রয়ে লাতিন ডিউকদের দ্বারা শাসিত নাক্সোস ডাচি বারবারোসা হায়রেদ্দিন পাশার দ্বীপ অভিযানের মাধ্যমে অটোমান নিয়ন্ত্রণে আসে। দ্বীপের মর্যাদায় হাত দেওয়া হয়নি; ডাচি অটোমানদের অধীন হিসেবে টিকে থাকে এবং 1540 সালের অটোমান-ভেনিস চুক্তিতে কর্তৃত্বের অধিকার আনুষ্ঠানিকভাবে অটোমানদের হাতে চলে যায়।", "e20e29f9"]},
"OLAYLAR_EK12:1560-03-12:0":{"b": ["ক্রুসেডার নৌবহর জারবা দখল করল — তুরগুত পাশার ঘাঁটি হাতছাড়া", "f41b3f2a"], "d": ["স্পেন, পোপতন্ত্র, মাল্টা, জেনোয়া ও ফ্লোরেন্সের জাহাজে গঠিত ক্রুসেডার নৌবহর তুরগুত রেইস 1551 সাল থেকে অভিযান-ঘাঁটি হিসেবে ব্যবহৃত জারবাকে লক্ষ্যবস্তু করে। ঝড় ও মহামারির কারণে দ্বীপের সামনে তারা কেবল 1560 সালের শুরুতে পৌঁছাতে পারে; 12 মার্চ 1560 তারিখে দ্বীপটি দখল করে একটি দুর্গ নির্মাণ করে। খবর পেয়ে পিয়ালে পাশা 28 মার্চ 120টি গ্যালির নৌবহর নিয়ে ইস্তানবুল থেকে রওনা হন। দখল দীর্ঘস্থায়ী হয়নি: অটোমান নৌবহর মে মাসে জারবার সামনে মিত্রদের পরাজিত করে এবং দুর্গ জুলাইয়ের শেষে পুনরুদ্ধার হয়। এই অভিযান প্রেভেজার পর ভূমধ্যসাগরে অটোমান আধিপত্য সুদৃঢ়কারী দ্বিতীয় বৃহৎ নৌ-অভিযানের সূচনা।", "a420585e"]},
"OLAYLAR_EK12:1560-07-30:0":{"b": ["জারবা দুর্গের পতন — দ্বীপ অটোমান শাসনে", "f1efc0df"], "d": ["পিয়ালে পাশার 14 মে 1560 তারিখের নৌ-বিজয়ের পর ক্রুসেডার বাহিনী দ্বীপে নির্মিত দুর্গে আশ্রয় নেয়; ত্রিপোলির বেইলারবেই তুরগুত পাশার বাহিনী স্থলপথে অবরোধ করে। দুই মাসব্যাপী অবরোধ 30 জুলাই 1560 তারিখে দুর্গের পতনের মাধ্যমে শেষ হয় এবং দ্বীপটি ত্রিপোলি বেইলারবেইয়ের সঙ্গে যুক্ত হয়। নৌ-বিজয় ও দুর্গ জয়ের মধ্যে সাতাত্তর দিনের ব্যবধান; দ্বীপ 14 মে নয়, 30 জুলাই কার্যত হাত বদলেছে।", "50b148da"]},
"OLAYLAR_EK12:1814-02-04:0":{"b": ["দানজিগে রুশ-প্রুশীয় দ্বৈত শাসনের অবসান — নেপোলিয়নের মুক্ত শহর প্রুশিয়ায় ফিরল", "1ccda4d2"], "d": ["টিলসিটের শান্তির (9 জুলাই 1807) মাধ্যমে প্রুশিয়া থেকে বিচ্ছিন্ন হয়ে ফরাসি আশ্রয়ে মুক্ত শহর করা দানজিগকে নেপোলিয়নের বাহিনী 1813 সালের অবরোধের পর ত্যাগ করে। 2 জানুয়ারি – 4 ফেব্রুয়ারি 1814 পর্যন্ত শহরে রুশ-প্রুশীয় দ্বৈত শাসন চলে; জার আলেকজান্ডার দানজিগ ও ভিস্টুলা মোহনা নেওয়ার পরিকল্পনা ত্যাগ করলে শহর প্রুশীয় শাসনে যায়।", "8d215059"]},
"OLAYLAR_EK12:1815-05-03:0":{"b": ["ভিয়েনায় ক্রাকাউ স্বাধীন, মুক্ত ও নিরপেক্ষ শহর ঘোষিত", "19eea839"], "d": ["ভিয়েনা কংগ্রেসে রাশিয়া, অস্ট্রিয়া ও প্রুশিয়া ক্রাকাউ শহরকে তার পারিপার্শ্বিক অঞ্চলসহ তিন রাষ্ট্রের সুরক্ষাধীন একটি মুক্ত রাষ্ট্রে পরিণত করে; ভিয়েনা চূড়ান্ত দলিল এই ব্যবস্থাকে স্বীকৃতি দেয়।", "21a6fe2b"]},
"OLAYLAR_EK12:1893-01-01:0":{"b": ["বোর্নু রাবিহ ইবনে জুবায়েরের কর্তৃত্বে এল", "8be4ca96"], "d": ["বাগিরমি ও ওয়াদাইকে নাড়িয়ে দেওয়া সুদানি যুদ্ধনায়ক রাবিহ ইবনে জুবায়ের বোর্নু দখল করেন; 1896 সালের মধ্যে গোটা দেশ হস্তগত করে দিকোয়াকে কেন্দ্র করেন।", "466276f3"]},
"OLAYLAR_EK12:1900-04-22:0":{"b": ["রাবিহ ইবনে জুবায়ের ফরাসিদের কাছে পরাজিত ও নিহত — বোর্নুতে তাঁর কর্তৃত্বের অবসান", "fb5a3ace"], "d": ["ফরাসি ঔপনিবেশিক বাহিনীর কাছে পরাজিত রাবিহ নিহত হন; তাঁর পুত্র কর্তৃত্ব ধরে রাখতে চাইলেও টিকতে পারেননি এবং বোর্নু 1902 সালে ফ্রান্স, ইংল্যান্ড ও জার্মানির মধ্যে ভাগ হয়ে যায়।", "15789829"]},
"OLAYLAR_EK12:1913-08-31:0":{"b": ["গুমুলজিনা কেন্দ্রিক পশ্চিম থ্রেস অস্থায়ী সরকার ঘোষিত", "974b2e28"], "d": ["বুখারেস্ট চুক্তি (10 আগস্ট 1913) পশ্চিম থ্রেসকে বুলগেরিয়ার হাতে ছেড়ে দিলে অঞ্চলের তুর্কি জনগণ গুমুলজিনা কেন্দ্রিক একটি অস্থায়ী সরকার ঘোষণা করে; দেদেআগাচ দখলের পর সরকার ‘পশ্চিম থ্রেস স্বাধীন সরকার’ নামে স্বাধীনতা ঘোষণা করে। বৃহৎ শক্তিগুলোর হস্তক্ষেপে অটোমান সরকার একে সমর্থন করেনি; 29 সেপ্টেম্বর 1913 সালের ইস্তানবুল চুক্তি পশ্চিম থ্রেসকে বুলগেরিয়ার হাতে ছেড়ে দেয় এবং সরকারটি 25 অক্টোবর 1913 পর্যন্ত মাত্র সাতান্ন দিন টিকে ছিল।", "86d3bfee"]},
"OLAYLAR_EK13:1362-03-01:0":{"b": ["ওরহান গাজীর মৃত্যু — বেলিক থেকে রাষ্ট্রে উত্তরণের চল্লিশ বছরের সমাপ্তি", "62c59cfd"], "d": ["1324 সালে ওসমান গাজীর মৃত্যুর পর বেলিকের নেতৃত্বে আসা ওরহান গাজী আটত্রিশ বছরের শাসনে অটোমানদের একটি সীমান্ত বেলিক থেকে মারমারার দুই তীরে প্রতিষ্ঠিত রাষ্ট্রে রূপান্তরিত করেন: বুর্সা (1326), ইজনিক (1331) ও ইজমিত (1337) দখল হয়, কারেসি বেলিক সংযুক্ত হয়, প্রথম আকচা মুদ্রা প্রচলিত হয় (1327), প্রথম মাদ্রাসা ইজনিকে স্থাপিত হয় (1331) এবং রুমেলিতে উত্তরণ চিম্পে (1352) ও গেলিবোলু (1354) হয়ে স্থায়ী হয়। রুমেলি বিজয়ে নেতৃত্বদানকারী জ্যেষ্ঠ পুত্র সুলায়মান পাশাকে তিনি 1357 সালে শিকার দুর্ঘটনায় হারান; নিজে 1362 সালের মার্চে বুর্সায় মারা যান এবং তাঁর স্থলে পুত্র প্রথম মুরাদ অধিষ্ঠিত হন।", "9208e381"]},
"OLAYLAR_EK13:1417-01-01:0":{"b": ["বাহরাইন দ্বীপপুঞ্জ জাবরিদের হাতে যাওয়া", "6a242b16"], "d": ["টিডিভির বাহরাইন নিবন্ধে উল্লেখ আছে, দ্বীপ “ক্রমান্বয়ে উয়ুনি, সালগুরি, তাবি ও জাবরিদের শাসনে ছিল এবং জাবরি আমলে সংখ্যাগরিষ্ঠ শিয়া থেকে সুন্নিতে রূপান্তরিত হয়”; কোনোটির তারিখ দেওয়া নেই। সাধারণ সাহিত্যে জাবরি রাজবংশ পঞ্চদশ শতকের শুরুতে কাতিফের শেষ জারওয়ানি শাসককে উৎখাত করে প্রতিষ্ঠিত হয় এবং চরম উৎকর্ষের সময়ে (আজওয়াদ ইবনে যামিল, মৃ. 1496) পারস্য উপসাগরের সমগ্র আরব উপকূল, লাহসা, কাতিফ ও বাহরাইন দ্বীপপুঞ্জ নিয়ন্ত্রণ করে। আজওয়াদের পর দ্বীপপুঞ্জ মুকরিন ইবনে যামিলের হাতে যায় — 1521 সালে পর্তুগিজদের কাছে পরাজিত হবেন এই শাসকই।", "0c4cdac7"]},
"OLAYLAR_EK13:1471-08-24:0":{"b": ["পর্তুগালের আরজিলা দখল — মরক্কোর উপকূলে দ্বিতীয় ঘাঁটি", "83444a11"], "d": ["পঞ্চম আফোনসো 30,000 জনের বাহিনী ও 400 জাহাজের নৌবহর নিয়ে নিজে মরক্কোর উপকূলে অবতরণ করেন এবং ওয়াত্তাসি শাসনাধীন আরজিলা 24 আগস্ট 1471 তারিখে দখল করেন। শহরের পতন তাঞ্জিয়ারের প্রতিরোধ ভেঙে দেয়; তাঞ্জিয়ার চার দিন পরে, 28 আগস্ট বিনা যুদ্ধে আত্মসমর্পণ করে। পর্তুগাল এভাবে সেউটা (1415) ও আলকাসের-সেগের (1458) পর মরক্কোর আটলান্টিক উপকূলে তৃতীয় ও চতুর্থ ঘাঁটি স্থাপন করে; রাজা এই অভিযানের পর নিজের উপাধিতে “আফ্রিকার প্রভু” যুক্ত করান।", "ec8d27f5"]},
"OLAYLAR_EK13:1488-01-01:0":{"b": ["সাফির পর্তুগিজ প্রভাবাধীন হওয়া", "765e703e"], "d": ["আটলান্টিক উপকূলের সবচেয়ে ব্যস্ত শস্য ও মৎস্য বন্দর সাফি 1488 সালে পর্তুগিজ প্রভাবাধীন হয়; শহর কিছুকাল স্থানীয় শাসকদের হাতে পর্তুগিজ আশ্রয়ে শাসিত হয় এবং 1508 সালে সরাসরি দখল হয়। সূত্রগুলো এই দুই পর্যায়কে ভিন্নভাবে গুরুত্ব দেয় বলে সূচনার তারিখ 1488 ও 1508-এর মধ্যে ওঠানামা করে; দুটিই একই প্রক্রিয়ার দুই প্রান্ত। সাফি তিপ্পান্ন বছর পর্তুগিজ হাতে ছিল এবং 1541 সালে আগাদিরের পতনের পর পরিত্যক্ত হয়।", "51aa6746"]},
"OLAYLAR_EK13:1505-01-01:0":{"b": ["সান্তা ক্রুজ দো কাবো দে গুয়ের প্রতিষ্ঠা — আগাদিরে পর্তুগিজ দুর্গ", "cc22c433"], "d": ["সুস উপকূলে, তখন পর্যন্ত পর্তুগালের পৌঁছানো হয়নি এমন স্থানে বেসরকারি উদ্যোগে নির্মিত সান্তা ক্রুজ দো কাবো দে গুয়ে দুর্গ 1505 সালে গড়া হয় এবং 1513 সালে পর্তুগিজ রাজমুকুটের হাতে হস্তান্তরিত হয়। দুর্গটি সুস উপত্যকার চিনি ও স্বর্ণ বাণিজ্য নিয়ন্ত্রণ করে মারাকেশের দক্ষিণ-পশ্চিম নির্গমন পথ বন্ধ করে রেখেছিল; তাই সাদি আন্দোলনের প্রথম বড় লক্ষ্য হয়। 1533 সালের অবরোধ প্রতিহত হয়, 1541 সালেরটি সফল হয় এবং মরক্কোতে পর্তুগালের পতন শুরু করে।", "6d42d1d3"]},
"OLAYLAR_EK13:1513-09-03:0":{"b": ["আজেমমুর দখল — উম্মুররাবির মোহনার নিয়ন্ত্রণ", "232acd4b"], "d": ["ব্রাগানজার ডিউক জাইমের নেতৃত্বাধীন পর্তুগিজ বাহিনী উম্মুররাবি নদীর মোহনার আজেমমুরে 3 সেপ্টেম্বর 1513 তারিখে প্রতিরোধ ছাড়াই প্রবেশ করে। শহর দখলের ফলে নদীমুখ ও অভ্যন্তরের শস্য পথ উভয়ের নিয়ন্ত্রণ আসে এবং পরের বছর 12 কিমি দক্ষিণ-পশ্চিমে মাজাগান দুর্গ নির্মাণের পথ খোলে। আজেমমুর আটাশ বছর পর্তুগিজ হাতে ছিল।", "8ac983da"]},
"OLAYLAR_EK13:1514-01-01:0":{"b": ["মাজাগান দুর্গ প্রতিষ্ঠা — মরক্কোয় সবচেয়ে দীর্ঘস্থায়ী পর্তুগিজ ঘাঁটি", "786cdb40"], "d": ["আজেমমুর দখলের পরের বছর, 1514 সালের গ্রীষ্মে উপকূলে মাজাগান দুর্গ নির্মিত হয়। 1541 সালের সাধারণ পতনের পর পর্তুগাল মরক্কোর সব ঘাঁটি ছাড়লেও মাজাগান ছাড়েনি; বরং দুর্গটি ইতালীয় ধাঁচের বুরুজে নতুন করে গড়ায় এবং শহর দুইশত পঞ্চান্ন বছর ধরে রাখা হয়। 1562 সালের বড় অবরোধও প্রতিহত হয়। মাজাগান মরক্কোয় পর্তুগালের শেষ ঘাঁটি হিসেবে 1769 সালে খালি করা হবে।", "fe42a1e2"]},
"OLAYLAR_EK13:1517-05-01:0":{"b": ["মারদিন দুর্গের আত্মসমর্পণ — দিয়ারবাকিরের দক্ষিণে সাফাভি প্রতিরোধের অবসান", "e6226de5"], "d": ["চালদিরানের পর দিয়ারবাকির অঞ্চলের দিকে অগ্রসর বিয়িকলি মেহমেদ পাশা মারদিন অবরোধ করলে সাফাভি বাহিনী 1515 সালের অক্টোবরে দুর্গে আশ্রয় নেয়; শহর অটোমান হাতে গেলেও দুর্গ প্রতিরোধ চালায়। সাফাভি গভর্নর কারা খানের শক্তিবৃদ্ধি নিয়ে পাল্টা আক্রমণ 1516 সালের মে মাসে কোচহিসার (কিজিলতেপে) যুদ্ধে পরিণত হয় — দেদে গারকিন প্রান্তরে সারাদিন চলা লড়াইয়ে কারা খানের শিরশ্ছেদ হয় এবং তাঁর সেনা ছত্রভঙ্গ হয়। দুর্গ টিডিভির ভাষায় “মাত্র নয় মাস পর” আত্মসমর্পণ করে।", "791d1c1c"]},
"OLAYLAR_EK13:1521-01-01:0":{"b": ["পর্তুগালের বাহরাইন দখল — জাবরি কর্তৃত্বের অবসান", "315a435a"], "d": ["জাবরি শাসক মুকরিন ইবনে যামিল হরমুজকে কর দিতে অস্বীকার করলে পর্তুগিজ নৌবহর ও পর্তুগালের অধীন হরমুজ রাজ্যের বাহিনী দ্বীপে অবতরণ করে; মুকরিন যুদ্ধে পরাজিত হন এবং বাহরাইন 1521 সালে পর্তুগিজ শাসনে আসে। এরপর আশি বছর দ্বীপ হরমুজের মাধ্যমে, অধিকাংশ সময় সুন্নি ইরানি গভর্নরদের হাতে শাসিত হয়। বাহরাইনের মুক্তা ও কৌশলগত অবস্থান দ্বীপটিকে উপসাগরে অটোমান-পর্তুগিজ প্রতিদ্বন্দ্বিতার প্রত্যক্ষ লক্ষ্যে পরিণত করবে।", "34a37f50"]},
"OLAYLAR_EK13:1541-03-12:0":{"b": ["আগাদিরের পতন — সাদিদের মরক্কো থেকে পর্তুগিজ উচ্ছেদ শুরু", "bb1568f6"], "d": ["সাদি সুলতান মুহাম্মদ আশ-শেখ 16 ফেব্রুয়ারি 1541 তারিখে সান্তা ক্রুজ দুর্গ অবরোধ করেন এবং 12 মার্চ তা দখল করেন; গভর্নর গুতেরে দে মনরয়সহ প্রায় ছয়শত পর্তুগিজ বন্দি হয়।", "af3555a6"]},
"OLAYLAR_EK13:1541-10-01:0":{"b": ["সাফি ও আজেমমুর খালি করা — পর্তুগাল আটলান্টিক উপকূল থেকে সরে যাচ্ছে", "4cb6099a"], "d": ["1541 সালের 12 মার্চ আগাদিরের পতন এবং মরক্কোর সুলতানের সঙ্গে প্রত্যাশিত মিত্রতা না হওয়ায় তৃতীয় জোয়াও আটলান্টিক উপকূলের দুটি বড় ঘাঁটি খালি করার আদেশ দেন; সাফি ও আজেমমুরের সরে যাওয়া 1541 সালের শরতে, সেপ্টেম্বর-অক্টোবরে সম্পন্ন হয়। এভাবে এক বছরে তিনটি ঘাঁটি হাতছাড়া হয় এবং মরক্কো উপকূলে পর্তুগালের পঞ্চাশ বছরের বিস্তার উল্টে যায়; অবশিষ্ট থাকে সেউটা, তাঞ্জিয়ার, আরজিলা, আলকাসের-সেগের ও নতুন সুরক্ষিত মাজাগান।", "e6d4728d"]},
"OLAYLAR_EK13:1549-01-01:0":{"b": ["আরজিলা খালি করা — পর্তুগাল উত্তর উপকূলে সংকুচিত", "b5d18373"], "d": ["আর্থিক সংকট ও সাদি চাপের সম্মিলনে তৃতীয় জোয়াও 1471 সাল থেকে ধরে রাখা আরজিলা খালি করেন। মরক্কোয় পর্তুগালের উপস্থিতি এভাবে সেউটা, তাঞ্জিয়ার ও মাজাগানে নেমে আসে। আরজিলা 1577 সালে অল্প সময়ের জন্য আবার দখল হবে, 1589 সালে চূড়ান্তভাবে পরিত্যক্ত হবে।", "36c1d8e6"]},
"OLAYLAR_EK13:1559-01-01:0":{"b": ["অটোমানদের বাহরাইন অভিযান — উপসাগরে পর্তুগালের বিরুদ্ধে শেষ বড় পদক্ষেপ", "14501df3"], "d": ["1546 সালে বসরা সংযুক্তি এবং লাহসা প্রদেশ প্রতিষ্ঠার মাধ্যমে উপসাগরের আরব উপকূলে অবস্থান নেওয়া অটোমান রাষ্ট্র দ্বীপের মুক্তা বাণিজ্য ও পর্তুগালের হরমুজ পথকে লক্ষ্য করে লাহসার বেইলারবেই মুস্তাফা পাশার নেতৃত্বে বাহরাইনের দিকে অগ্রসর হয়। অভিযানের ফল সূত্রে ভিন্ন: টিডিভি ইসলাম বিশ্বকোষ লেখে অটোমানরা “1559 সালে বাহরাইন দখল করে সেখানে একটি ঘাঁটি” গড়ে, দ্বীপপুঞ্জ “পরে আবার পর্তুগিজদের শাসনে” যায়; পশ্চিমা সাহিত্য বলে অবরোধ ব্যর্থ হয়, হরমুজ থেকে সমুদ্রপথে আসা পর্তুগিজ সাহায্য অটোমান বাহিনীকে হটিয়ে দেয় এবং উভয় পক্ষকে ভেঙে দেওয়া এক মহামারির পর অটোমানরা আত্মসমর্পণের শর্ত চায়। দুই বর্ণনা ফলাফলেই ভিন্ন; অভিন্ন বিষয় হলো, বাহরাইন অটোমানদের হাতে স্থায়ী হয়নি।", "b35d131f"]},
"OLAYLAR_EK13:1569-01-01:0":{"b": ["উলুচ আলি পাশার তিউনিস দখল — হাফসি-স্পেনীয় ব্যবস্থার অবসান", "d4498698"], "d": ["পঞ্চম চার্লস 1535 সালে তিউনিস দখল করলে নিজে শহর শাসন করেননি, হাফসি সুলতান মাওলায় হাসানকে সিংহাসনে ফিরিয়ে বসান; টিডিভির ভাষায় তিউনিস শহর “1569 সালে অটোমানদের দ্বিতীয় হস্তক্ষেপ পর্যন্ত স্পেনীয়দের আশ্রয়ে এবং তৃতীয় মাওলায় আহমদের শাসনে” ছিল। 27 জুন 1568 তারিখে আলজিয়ার্সের বেইলারবেই নিযুক্ত উলুচ আলি স্থলপথে তিউনিসের দিকে অগ্রসর হন, বেজায় হাফসি সুলতানকে পরাজিত করে শহরে প্রবেশ করেন; মাওলায় আহমদ স্পেনীয় দুর্গ হালকুলওয়াদিতে আশ্রয় নেন। এভাবে উপসাগর দুই ভাগ হয় — শহর অটোমান, বন্দর-দুর্গ স্পেনীয় — এবং এই বিভাজন চার বছর স্থায়ী হয়।", "47e86f74"]},
"OLAYLAR_EK13:1573-10-10:0":{"b": ["দন হুয়ান দে অস্ট্রিয়ার তিউনিস পুনরুদ্ধার — লেপান্তোর স্থলে একমাত্র প্রতিফল", "a6f044ee"], "d": ["লেপান্তোর (1571) পর পবিত্র লিগ ভেঙে গেলেও স্পেন একাই উত্তর আফ্রিকায় অগ্রসর হয়: টিডিভির ভাষায় “10 অক্টোবর 1573 তারিখে স্পেনীয়রা তিউনিসের নিয়ন্ত্রণ নিতে নতুন অভিযানে নামে। তিউনিস দখল করে সেখানে 8000 সৈন্য রেখে যায়।” দন হুয়ান দে অস্ট্রিয়ার নেতৃত্বে এই অভিযানই লেপান্তো বিজয়ের স্থলে একমাত্র প্রতিফল; তবে তা স্থায়ী হয়নি এবং শহর এগারো মাস পরে পুনরুদ্ধার হয়। দখলের ফলে যা উৎখাত হয় তা ছিল প্রতিষ্ঠিত একটি অটোমান প্রশাসন: 2 জিলহজ্জ 980 তারিখে (5 এপ্রিল 1573) তিউনিসের অধিনায়ক ছিলেন কিলিচ আলি পাশা, কায়মাকাম রামাজান পাশা, বেইলারবেই হায়দার পাশা।", "f7f9ab56"]},
"OLAYLAR_EK13:1602-01-01:0":{"b": ["সাফাভিদের পর্তুগালের কাছ থেকে বাহরাইন গ্রহণ", "c37d982c"], "d": ["শাহ প্রথম আব্বাসের পাঠানো বাহিনী দ্বীপের বিদ্রোহীদের সঙ্গে মিলে পর্তুগিজ গ্যারিসনকে দুর্গ থেকে বের করে দেয়; টিডিভির ভাষায় দ্বীপপুঞ্জ “1602 সালে ইরানের অধীন বাহিনীর দ্বারা” পর্তুগিজদের হাত থেকে নেওয়া হয়। বাহরাইন এভাবে একাশি বছরের পর্তুগিজ শাসন থেকে বেরিয়ে সাফাভি আধিপত্যে আসে এবং একশত পনেরো বছর ইরানের অধীন থাকে। এটি উপসাগরে পর্তুগালের পতনের প্রথম ধাপ; বিশ বছর পর হরমুজও ইংরেজ-ইরানি যৌথ অভিযানে পতিত হবে।", "19e58d88"]},
"OLAYLAR_EK13:1717-01-01:0":{"b": ["ওমানিদের বাহরাইন আক্রমণ — সাফাভি কর্তৃত্বের অবসান", "c9be5820"], "d": ["সাফাভি রাষ্ট্রের শেষ বছরগুলোর বিপর্যয়ের সময় ইয়ারুবি রাজবংশের অধীন ওমানি নৌবহর দ্বীপ আক্রমণ করে এবং সাফাভি কর্তৃত্ব শেষ হয়। এর পরের পঁয়ত্রিশ বছর উপসাগরের সবচেয়ে বিশৃঙ্খল সময়: দ্বীপ ওমান, ইরান ও স্থানীয় আরব শক্তির মধ্যে কয়েকবার হাত বদলায়।", "b0c7f671"]},
"OLAYLAR_EK13:1753-01-01:0":{"b": ["বাহরাইনের বুশেহরের আল-ই মেজকুর শাসনে যাওয়া", "610e2f9d"], "d": ["মূলত ওমান থেকে এসে বুশেহরে বসতি গড়া এবং হুওয়ালা হিসেবে গণ্য আল-ই মেজকুর পরিবার 1753 সালে বুশেহরের ঘাঁটি থেকে বাহরাইনকে নিজেদের শাসনে নেয়। পরিবারটি ইরানের উপসাগরীয় উপকূলের আরব সম্প্রদায়গুলোর নেতৃত্ব দিত এবং ইরানের পক্ষে দ্বীপ শাসন করত; শেষ প্রতিনিধি নাসর আল-ই মেজকুর জান্দ প্রশাসন কর্তৃক বাহরাইনের গভর্নর নিযুক্ত হন। এটিই আল-ই খলিফার আগে দ্বীপের শেষ শাসন।", "7cc5fed2"]},
"OLAYLAR_EK13:1769-03-11:0":{"b": ["মাজাগান খালি করা — মরক্কোয় পর্তুগালের শেষ ঘাঁটির পতন", "f9e9749d"], "d": ["আলাওয়ি সুলতান তৃতীয় মুহাম্মদ ইবনে আবদুল্লাহ 1769 সালের শুরুতে যে অবরোধ শুরু করেন তার মুখে 592 জনের গ্যারিসন টিকতে পারেনি; লিসবন থেকে 1 ফেব্রুয়ারি রওনা হওয়া উদ্ধার নৌবহর 11 মার্চ 1769 তারিখে শেষ সৈন্যদের জাহাজে তোলে এবং সর্বশেষ গভর্নর দিনিস গ্রেগোরিও শহর ত্যাগ করেন। এভাবে 1415 সালে সেউটা দখলের মাধ্যমে শুরু হওয়া মরক্কোয় পর্তুগালের উপস্থিতি সাড়ে তিন শতক পর শেষ হয়। মাজাগান ছিল 1541 সালের সাধারণ পতনের পর ধরে রাখা একমাত্র আটলান্টিক উপকূলীয় ঘাঁটি এবং দুইশত পঞ্চান্ন বছর নিয়ে মরক্কোয় পর্তুগালের সবচেয়ে দীর্ঘ ধরে রাখা স্থান।", "c0ad57bc"]},
"OLAYLAR_EK13:1783-01-01:0":{"b": ["আল-ই খলিফার বাহরাইন বিজয় — আজও টিকে থাকা রাজবংশের প্রতিষ্ঠা", "8773b011"], "d": ["জান্দ প্রশাসনের বাহরাইন গভর্নর নাসর আল-ই মেজকুর কাতার উপদ্বীপের জুবারা অবরোধ করেন; আহমদ ইবনে মুহাম্মদ ইবনে খলিফার নেতৃত্বাধীন উতুব বাহিনী অবরোধ ভেঙে পাল্টা আক্রমণে গিয়ে একই বছর বাহরাইন দখল করে। টিডিভির বিবরণ সংক্ষিপ্ত: “বাহরাইন 1783 সালে উতুব গোত্রের আল-ই খলিফার কর্তৃত্বে আসে।” আহমদ ইবনে মুহাম্মদ এই বিজয়ের পর “আল-ফাতিহ” উপাধিতে পরিচিত হন এবং তাঁর প্রতিষ্ঠিত রাজবংশ আজও দ্বীপে শাসন করছে।", "470bd22f"]},
"OLAYLAR_EK13:1861-05-21:0":{"b": ["ইংল্যান্ডের সঙ্গে বাহরাইনের চুক্তি — উপসাগরে আশ্রিত ব্যবস্থায় প্রবেশ", "576796b2"], "d": ["টিডিভির বিবরণ অনুযায়ী “21 মে 1861 তারিখে ইংল্যান্ড এবং বাহরাইনের প্রতিনিধি শেখ মুহাম্মদের ভাই আলি অঞ্চলে দাস বাণিজ্য ও জলদস্যুতা নিষিদ্ধকারী একটি চুক্তি স্বাক্ষর করেন”; ইংরেজ দলিলে একই চুক্তি (Perpetual Truce of Friendship and Peace) 31 মে 1861 তারিখ বহন করে। চুক্তিটি বাহরাইনের পররাষ্ট্র সম্পর্ক ইংল্যান্ডের সঙ্গে বেঁধে দেওয়া আশ্রিত ব্যবস্থার প্রথম ধাপ এবং অটোমানরা 1871 সালে লাহসা ও কাতিফে পুনরায় নিজেদের প্রতিষ্ঠিত করার পরও দ্বীপ এই ব্যবস্থার বাইরে থাকে।", "773e5fd1"]},
"OLAYLAR_EK14:1281-01-01:0":{"b": ["আহি এভরান — আহি সংগঠনের প্রতিষ্ঠাতা পির", "3392e100"], "d": ["আহি এভরান আনাতোলিয়ায় আহি সংগঠনের প্রতিষ্ঠাতাদের একজন এবং দাব্বাগদের (চর্মকার) পির বলে গণ্য। কির্শেহিরে তাঁর জাভিয়ে অটোমান যুগে কারিগর/গিল্ড সংগঠনের আধ্যাত্মিক কেন্দ্র হিসেবে বিংশ শতকের শুরু পর্যন্ত টিকে ছিল; রাষ্ট্র এই অবস্থান 1780, 1782, 1822-23 ও 1842 সালে আনুষ্ঠানিকভাবে নিশ্চিত করেছে।", "caa063df"]},
"OLAYLAR_EK14:1326-01-01:0":{"b": ["শেখ এদেবালি — আহি সংগঠন ও অটোমান রাজবংশের মধ্যে প্রতিষ্ঠার সংযোগ", "c1186059"], "d": ["বিলেজিকে জাভিয়ে স্থাপন করা এবং আহি সংগঠনেরও একজন শেখ হিসেবে অবস্থানকারী এদেবালি জনশ্রুতি অনুসারে ওসমান গাজীর বিখ্যাত স্বপ্নের ব্যাখ্যা দেন; এরপর ওসমান গাজী এদেবালির কন্যা মালহুন খাতুনকে বিয়ে করেন। এদেবালি একই সঙ্গে প্রথম অটোমান কাজি ও মুফতি বলে গণ্য।", "60c970e5"]},
"OLAYLAR_EK14:1330-06-01:0":{"b": ["বুর্সা বিজয়ের পর ওরহান গাজীর জিরিত খেলার জন্য জমি ওয়াকফ", "da1becbd"], "d": ["টিডিভির জিরিত নিবন্ধ অনুসারে ওরহান গাজী বুর্সা বিজয়ের পর আশপাশের একটি এলাকা ঘোড়দৌড় ও জিরিত খেলার জন্য ওয়াকফ করেন — অটোমানদের মধ্যে জিরিত খেলার প্রাতিষ্ঠানিক রূপ পাওয়া প্রথম লিপিবদ্ধ দৃষ্টান্তগুলোর একটি।", "f099d0d8"]},
"OLAYLAR_EK14:1357-06-01:0":{"b": ["কিরকপিনার কুস্তির কথিত সূচনা", "2d93fa65"], "d": ["জনশ্রুতি অনুসারে কিরকপিনার কুস্তি ঐতিহ্য রুমেলি বিজেতা সুলায়মান পাশার সঙ্গে পার হওয়া চল্লিশ গাজীর মধ্যকার কুস্তি প্রতিযোগিতা থেকে শুরু। টিডিভির কুস্তি ও কিরকপিনার নিবন্ধ এই জনশ্রুতি উল্লেখ করে কিন্তু নির্দিষ্ট প্রতিষ্ঠার তারিখ দেয় না।", "a7dedab7"]},
"OLAYLAR_EK14:1362-06-01:0":{"b": ["জ্যানিসারি বাহিনীর প্রতিষ্ঠা", "f4206dce"], "d": ["চান্দারলি কারা খলিল ও মোল্লা রুস্তেমের নির্দেশনায়, পেনচিক আইন অনুযায়ী যুদ্ধবন্দিদের মধ্য থেকে নেওয়া অমুসলিম তরুণদের প্রশিক্ষণের মাধ্যমে শুরু হওয়া ব্যবস্থা গেলিবোলুতে প্রতিষ্ঠিত আজেমি ওজাকের মাধ্যমে প্রথম মুরাদের সময় প্রাতিষ্ঠানিক রূপ পায়।", "4842eade"]},
"OLAYLAR_EK14:1402-01-01:0":{"b": ["এদির্নে এস্কি মসজিদের (উলু মসজিদ) নির্মাণ শুরু", "da7a22ac"], "d": ["জনসাধারণের মধ্যে উলুজামি (জামি-ই আতিক) নামেও পরিচিত এস্কিজামির নির্মাণ আমির সুলায়মান চেলেবি 1402-1403 সালে শুরু করেন।", "0f5a6b9d"]},
"OLAYLAR_EK14:1414-01-01:0":{"b": ["বুর্সা ইয়েশিল মসজিদ কমপ্লেক্সের নির্মাণ শুরু", "280b8a21"], "d": ["ফেত্রেত যুগের পর সিংহাসন পুনরায় একত্রকারী প্রথম মেহমেদ 1414 সালে কমপ্লেক্সের নির্মাণ শুরু করেন এবং একে বুর্সার কেন্দ্রীয় স্থানে, দাদা ও পিতার কমপ্লেক্স থেকে আলাদা করে চেনা যায় এমনভাবে স্থাপন করেন। প্রধান স্থপতি হাজি ইভাজ পাশা।", "b820a0dd"]},
"OLAYLAR_EK14:1419-12-01:0":{"b": ["বুর্সা ইয়েশিল মসজিদ কমপ্লেক্স সমাপ্ত", "bc82821f"], "d": ["তাবরিজের কারিগরদেরও অবদান রাখা টাইল ও অলংকরণ কর্মসূচির জন্য পরিচিত ইয়েশিল মসজিদ কমপ্লেক্স 1419 সালের ডিসেম্বরে সমাপ্ত হয়। কমপ্লেক্স মসজিদ, সমাধিসৌধ (ইয়েশিল সমাধি), মাদ্রাসা, ইমারেত ও হাম্মামখানায় গঠিত; আদি অটোমান স্থাপত্যের সবচেয়ে সমৃদ্ধ নিদর্শনগুলোর একটি।", "b3e76f7c"]},
"OLAYLAR_EK14:1421-06-01:0":{"b": ["দেভশিরমে ব্যবস্থার কার্যত প্রয়োগ শুরু", "fa835172"], "d": ["আগের ইসলামি রাষ্ট্রগুলোতে দেখা যায়নি এমন দেভশিরমে পদ্ধতি প্রথমে পেনচিক আইন অনুযায়ী অমুসলিম যুদ্ধবন্দি তরুণদের কাজে লাগানোর রূপে শুরু হয়। টিডিভি (TDV)-র মতে, ‘চেলেবি মেহমেদের সময়ে প্রয়োগ করা হলেও তাঁর পুত্র দ্বিতীয় মুরাদের আমলে আইনে পরিণত হয়েছে বলে বোঝা যায়।’", "be8c415b"]},
"OLAYLAR_EK14:1425-01-01:0":{"b": ["শেখুল ইসলাম পদের সূচনা — মোল্লা ফেনারির বুরসার মুফতি পদ", "2a8ee2b9"], "d": ["দীর্ঘ বছর বুরসার কাজি থাকা আলিম মোল্লা ফেনারির 1425 সালে বুরসার মুফতি পদে নিয়োগকে টিডিভি (TDV)-র ভাষায় ‘অটোমানদের মধ্যে মুফতিত্ব ও শেখুল ইসলামি পদের সূচনা’ গণ্য করা হয়। তবে টিডিভি উল্লেখ করে যে এটি ষোড়শ শতকে সমগ্র ইলমিয়া সংগঠনের প্রতিনিধিত্বকারী পূর্ণ প্রাতিষ্ঠানিক শেখুল ইসলাম পদের সঙ্গে অভিন্ন নয়।", "3c8f9c61"]},
"OLAYLAR_EK14:1432-06-01:0":{"b": ["তিমার ব্যবস্থার প্রাতিষ্ঠানিকীকরণ", "dc267780"], "d": ["নথিভিত্তিক প্রথম তিমার উল্লেখ ওরহান বেগের আমল পর্যন্ত পাওয়া যায়; তবে পদ্ধতিগত আইনিকরণ ঘটে দ্বিতীয় মুরাদের আমলে। এ সময়ে প্রস্তুত তিমার ইজমাল দফতরগুলো দেখায় যে ব্যবস্থার সব মৌলিক নীতি গড়ে উঠেছিল; 1432 সালের কাছাকাছি সময়ের নথিপত্র প্রমাণ করে যে আইনগুলো পূর্ণ কার্যকর ছিল।", "6494e2c1"]},
"OLAYLAR_EK14:1447-01-01:0":{"b": ["উচ শেরেফেলি মসজিদ ও কমপ্লেক্স সমাপ্ত", "cde6993e"], "d": ["দ্বিতীয় মুরাদ কর্তৃক মুসলিহুদ্দিন ও শিহাবুদ্দিন নামের কারিগরদের দিয়ে দশ বছরে (1437-1447) নির্মিত উচ শেরেফেলি মসজিদ অটোমান স্থাপত্যে কেন্দ্রীয় নকশার মসজিদের প্রথম নিদর্শন বলে গণ্য এবং ধ্রুপদী যুগের পূর্ববর্তী উত্তরণ স্থাপত্যের অন্যতম মোড় পরিবর্তনকারী কাজ।", "daf1585b"]},
"OLAYLAR_EK14:1451-06-01:0":{"b": ["ফাতিহের আইনে দিওয়ান-ই হুমায়ুনের প্রাতিষ্ঠানিকীকরণ", "e8443e77"], "d": ["দ্বিতীয় মুরাদের আমলে এদির্নেতে দিওয়ান নিয়মিত বিধিতে বাঁধা পড়ে ‘দিওয়ান-ই হুমায়ুন’ পরিচয় অর্জন করতে শুরু করে। প্রকৃত রূপান্তর আসে সুলতান ফাতিহ মেহমেদের আইনে: সবচেয়ে বড় নতুনত্ব ছিল সুলতানের দিওয়ান-সভাপতিত্ব পুরোপুরি তুলে দিয়ে তা প্রধান উজিরের হাতে অর্পণ।", "e776b01d"]},
"OLAYLAR_EK14:1453-06-01:0":{"b": ["ফাতিহ সুলতান মেহমেদের ওকমেইদানি তীরন্দাজদের জন্য বরাদ্দ", "342a9fd5"], "d": ["ইস্তানবুল বিজয়ের সময় কাসিমপাশার ঢালে শিবির স্থাপনকারী ফাতিহ সুলতান মেহমেদ জায়গাটি একই সঙ্গে তীরন্দাজদের প্রশিক্ষণ-মাঠ হিসেবে ব্যবহার করেছিলেন; শহর দখলের পর এলাকাটি স্থায়ীভাবে তীরন্দাজদের জন্য বরাদ্দ করেন। এই বরাদ্দ ওকমেইদানির শতাব্দীব্যাপী অটোমান তীরন্দাজি ঐতিহ্যের কেন্দ্র হওয়ার সূচনা।", "0c85baff"]},
"OLAYLAR_EK14:1502-06-01:0":{"b": ["ইরানি রেশম বাণিজ্যে বুরসার শীর্ষে ওঠা", "f1324cdf"], "d": ["তাব্রিজ থেকে আসা কাফেলাগুলো গিলান, আস্তারাবাদ ও সারির রেশম বুরসায় বয়ে আনত, আর এখানে জেনোয়া, ভেনিস, ফ্লোরেন্স ও ইহুদি ব্যবসায়ীরা প্রতিযোগিতা করে তা কিনত। 1479 সালে ইরান থেকে আমদানি করা রেশমের মূল্য 150,000 ভেনিসীয় স্বর্ণমুদ্রায় পৌঁছায়; 1502 সালে শহরে 1000-এরও বেশি তাঁত চলছিল।", "0f47c417"]},
"OLAYLAR_EK14:1504-01-01:0":{"b": ["দ্বিতীয় বায়েজিদের কিরকপিনার কুস্তিগিরদের বড় পুরস্কার প্রদান", "d745b882"], "d": ["টিডিভির কুস্তি নিবন্ধ অনুসারে দ্বিতীয় বায়েজিদ 1504 সালে কুস্তিগিরদের 3,000 ও 1,500 কুরুশের পুরস্কার দেন; কুস্তি খেলার প্রতি অটোমান রাজদরবারের পৃষ্ঠপোষকতার লিপিবদ্ধ আদি দৃষ্টান্তগুলোর একটি।", "cc00554e"]},
"OLAYLAR_EK14:1505-10-13:0":{"b": ["বায়েজিদ মসজিদ ও কমপ্লেক্স সমাপ্ত", "eb9ab65b"], "d": ["দ্বিতীয় বায়েজিদের জন্য নির্মিত বায়েজিদ মসজিদ ও কমপ্লেক্সের নির্মাণ একটি আর্কাইভ দলিল অনুসারে 906 হিজরিতে (1500) শুরু হয় এবং 14 জমাদিউল আউয়াল 911-এ (13 অক্টোবর 1505) সমাপ্ত হয়। স্থপতি নিয়ে বিতর্ক আছে: আইভানসারাইয়ির বিবরণের ভিত্তিতে দীর্ঘকাল স্থপতি হায়রেদ্দিনের কাজ ধরা হতো, পরে কেমালেদ্দিনের বলে গণ্য হয়, কারও মতে দুজন একসঙ্গে কাজ করেছেন; একই দলিল অবশ্য কারিগর হিসেবে ইয়াকুব শাহ ইবনে সুলতান শাহকে দেখায়। মসজিদটি ধ্রুপদী-পূর্ব অটোমান স্থাপত্য থেকে ধ্রুপদী যুগে উত্তরণের গুরুত্বপূর্ণ স্মৃতিস্তম্ভগুলোর একটি।", "9b7591c4"]},
"OLAYLAR_EK14:1515-01-01:0":{"b": ["তের্সানে-ই আমিরের ইস্তানবুলে (কাসিমপাশা/গোল্ডেন হর্ন) স্থানান্তর", "f36e3675"], "d": ["সুলতান প্রথম সেলিমের আমলে গালাতা প্রাচীরের পশ্চিমের উপসাগরে নির্মাণ শুরু হওয়া নতুন নৌ-কারখানা 1515 সালে 160টি জাহাজ-ছাউনি নিয়ে সম্পন্ন হয়; এভাবে গেলিবোলুকেন্দ্রিক নৌ-কারখানার কার্যক্রম ইস্তানবুলে সরে আসে। প্রতিষ্ঠানটি পরে বারবারোস হাইরেদ্দিন পাশার আমলে আনুষ্ঠানিকভাবে ‘তের্সানে-ই আমিরে’ নাম পায়।", "baedf596"]},
"OLAYLAR_EK14:1520-01-01:0":{"b": ["শেখ হামদুল্লাহর মৃত্যু ও হস্তলিপি ঘরানার উত্তরাধিকার", "f5ed4d09"], "d": ["আমাসিয়ার শেখ হামদুল্লাহ দ্বিতীয় বায়েজিদের লিপিশিক্ষক হিসেবে আকলাম-ই সিত্তে (ছয় লিপিশৈলী) ঘরানাকে পরিপক্বতায় পৌঁছে দিয়ে সমগ্র ইসলামি বিশ্বে প্রভাব বিস্তারকারী এক অটোমান লিপিশৈলীর প্রতিষ্ঠাতা হন। 1520 সালে মারা গেলে তিনি পেছনে বিস্তৃত শিষ্যবৃত্ত রেখে যান।", "26c5c5fc"]},
"OLAYLAR_EK14:1521-01-01:0":{"b": ["পিরি রেইসের কিতাব-ই বাহরিয়ের প্রথম সংস্করণ সমাপ্ত", "fd6cc1ff"], "d": ["ভূমধ্যসাগরের উপকূল, বন্দর ও নৌচালনা তথ্য সংকলনকারী কিতাব-ই বাহরিয়ের প্রথম (গদ্য) সংস্করণ পিরি রেইস 1521 সালে সমাপ্ত করেন। এই প্রথম সংস্করণ তখনো সুলতানকে উপস্থাপন করা হয়নি, পরবর্তী বছরগুলোতে সম্প্রসারিত হওয়া একটি খসড়া ছিল।", "72e9151d"]},
"OLAYLAR_EK14:1526-01-01:0":{"b": ["পিরি রেইসের কিতাব-ই বাহরিয়ে সম্প্রসারণ করে আইনদাতা সুলতান সুলায়মানকে উপহার", "d4abf0b7"], "d": ["পিরি রেইস কিতাব-ই বাহরিয়েকে আংশিক পদ্যে সম্প্রসারিত করে 1526 সালে আইনদাতা সুলতান সুলায়মানকে উপস্থাপন করেন। এই রূপে গ্রন্থটি অটোমান নৌবিদ্যার সবচেয়ে ব্যাপক নৌচালনা নির্দেশিকা হিসেবে ছড়িয়ে পড়ে।", "7209606f"]},
"OLAYLAR_EK14:1534-01-01:0":{"b": ["মাত্রাকচি নাসুহের বেয়ান-ই মেনাজিলে ইরাকেইন অভিযানের পথ চিত্রণ", "aa012278"], "d": ["আইনদাতা সুলতান সুলায়মানের 1534 সালে যাত্রা করা প্রথম ইরান (ইরাকেইন) অভিযানে অংশ নেওয়া মাত্রাকচি নাসুহ ইস্তানবুল থেকে তাবরিজ, সেখান থেকে বাগদাদ পর্যন্ত সেনাবাহিনীর পথের প্রতিটি বিরতিস্থল ক্ষুদ্রচিত্র-মানচিত্র কৌশলে এঁকেছিলেন। এই কাজ বেয়ান-ই মেনাজিল-ই সেফের-ই ইরাকেইন নামের গ্রন্থে সংকলিত হয় এবং অটোমানদের মধ্যে মেনজিলনামা ধারার সবচেয়ে মৌলিক নিদর্শন।", "9ea08eae"]},
"OLAYLAR_EK14:1534-12-04:0":{"b": ["বাগদাদ বিজয়ের পর ফুজুলির আইনদাতাকে কাসিদা উপহার", "1ef0653f"], "d": ["আইনদাতা সুলতান সুলায়মান 1534 সালে বাগদাদ জয় করার পর ফুজুলি অটোমান সুলতানকে “গেলদি বুর্জ-ই এভলিয়ায়ে পাদিশাহ-ই নামদার” চরণে শুরু হওয়া বিখ্যাত কাসিদাসহ পাঁচটি কাসিদা উপহার দেন; এভাবে সাফাভি আশ্রয় ছেড়ে অটোমান রাষ্ট্রনায়কদের পৃষ্ঠপোষকতা খোঁজেন।", "b8e9e300"]},
"OLAYLAR_EK14:1535-01-01:0":{"b": ["ফুজুলির লাইলা ও মজনু মাসনাভি সমাপ্ত", "e3ef4085"], "d": ["ধ্রুপদী তুর্কি সাহিত্যের সবচেয়ে সুন্দর মাসনাভিগুলোর একটি বলে গণ্য লাইলা ও মজনু ফুজুলি 1535 সালে, আইনদাতার বাগদাদ অভিযানে অংশ নেওয়া ইস্তানবুলের কবিদের অনুরোধে রচনা করে সমাপ্ত করেন।", "bdb0a098"]},
"OLAYLAR_EK14:1538-01-01:0":{"b": ["স্থপতি সিনানের রাজকীয় প্রধান স্থপতি পদে নিয়োগ", "7a753f0e"], "d": ["টিডিভি ইসলাম বিশ্বকোষের সিনান নিবন্ধ অনুসারে, রাজকীয় প্রধান স্থপতি আজেম আলির 1537 সালে মৃত্যুর পর বোগদান অভিযানে প্রুত নদীর ওপর নির্মিত সেতুর জন্য মনোযোগ আকর্ষণকারী সিনান প্রধান উজির লুৎফি পাশার সুপারিশে এই দায়িত্বে নিযুক্ত হন। এভাবে সিনানের পঞ্চাশ বছরের বেশি স্থায়ী প্রধান স্থপতির যুগ শুরু হয়।", "e99864c8"]},
"OLAYLAR_EK14:1543-06-01:0":{"b": ["শেহজাদে মসজিদ ও কমপ্লেক্সের নির্মাণ শুরু", "1a70ddfd"], "d": ["আইনদাতা সুলতান সুলায়মান 1543 সালে মহামারিতে হারানো পুত্র শেহজাদে মেহমেদের নামে কমপ্লেক্স নির্মাণের আদেশ দেন; নির্মাণ 1543 সালের জুনে শুরু হয়, প্রথমে সমাধিসৌধ শেষ করে পরে মসজিদ নির্মাণে যাওয়া হয়। এটি স্থপতি সিনানের নিজের ভাষায় “শিক্ষানবিশির কাজ”।", "3f3d7e67"]},
"OLAYLAR_EK14:1547-01-01:0":{"b": ["উসকুদার ইস্কেলে (মিহরিমাহ সুলতান) কমপ্লেক্স সমাপ্ত", "3769007f"], "d": ["উসকুদার ইস্কেলে চত্বরের কমপ্লেক্সের নির্মাণ 1540-এর দশকের প্রথম বছরগুলোতে শুরু হয়ে 1547 সালে সমাপ্ত হয়। মিহরিমাহ সুলতান স্থপতি সিনানকে দিয়ে যে দুটি বড় মসজিদ নির্মাণ করান তার মধ্যে কালানুক্রমে প্রথমটি; দ্বিতীয়টি (এদির্নেকাপি) প্রায় বিশ বছর পর সমাপ্ত হবে।", "01e5c0ad"]},
"OLAYLAR_EK14:1548-06-01:0":{"b": ["আলেপ্পোয় ভেনিসের কনসুলেট স্থাপন", "3aad8b9e"], "d": ["ষোড়শ শতকে ইউরোপীয়দের বাণিজ্যিক ভারকেন্দ্র দামেস্ক থেকে আলেপ্পোয় সরে যায়। এ পরিবর্তনের বাস্তব নিদর্শন হিসেবে ভেনিস 1548 সালে আলেপ্পোয় কনসুলেট খোলে; এরপর 1557 সালে ফ্রান্স ও 1586 সালে ইংল্যান্ড তা অনুসরণ করে। শহরটি ইউরোপের পশমি কাপড় ও রুপার সঙ্গে ভারতীয় মসলা এবং শতকের শেষে ইরানি রেশম বিনিময়ের প্রধান বাজারে পরিণত হয়।", "1c077dea"]},
"OLAYLAR_EK14:1548-08-01:0":{"b": ["শেহজাদে মসজিদ উপাসনার জন্য খুলে দেওয়া", "2bb3f4b2"], "d": ["প্রায় পাঁচ বছরের নির্মাণের পর শেহজাদে মসজিদ 1548 সালের আগস্টে উপাসনার জন্য খুলে দেওয়া হয়। জোড়া মিনার ও কেন্দ্রীয় গম্বুজের নকশায় এটি স্থপতি সিনানের পরবর্তী বড় কাজগুলোর পূর্বাভাস বলে গণ্য; কমপ্লেক্স মসজিদ, সমাধিসৌধ, মাদ্রাসা, ইমারেত, তাবহানে ও কাফেলা-সরাইয়ে গঠিত।", "591f4ecf"]},
"OLAYLAR_EK14:1554-01-01:0":{"b": ["কিরকচেশমে জলপ্রণালী নির্মাণ শুরু", "14124b59"], "d": ["স্থপতি সিনান আইনদাতার আদেশে বেলগ্রেড বনভূমি থেকে ইস্তানবুলে পানি আনার সম্ভাব্যতা পরীক্ষা করে তা সম্ভব বলে জানান; বিশাল জলপ্রকল্পের নির্মাণ 1554 সালে শুরু হয়ে 1563 সালের আগে সমাপ্ত হয়। টিডিভি এটিকে সিনানের “প্রকৌশলের দিক থেকে সবচেয়ে গুরুত্বপূর্ণ, আয়তনের দিক থেকেও সবচেয়ে বড় কাজ” বলে বর্ণনা করে।", "dc29aa04"]},
"OLAYLAR_EK14:1554-06-01:0":{"b": ["ইস্তানবুলে প্রথম কফিহাউস খোলা", "85c12f9f"], "d": ["অটোমান নগরজীবনে কফির প্রবেশ শুরু হয় তাখতাকালেতে আলেপ্পোর ব্যবসায়ী হাকেম ও দামেস্কের শামস নামের এক ব্যক্তির খোলা কফিহাউসগুলো দিয়ে। অল্প সময়ে সমাজের সব স্তরের মানুষ একত্র হওয়ার এক নতুন গণপরিসর গড়ে ওঠে; কানুনির শেষ দিকে ইস্তানবুলে পঞ্চাশটি কফিহাউস ছিল।", "e1289ca2"]},
"OLAYLAR_EK14:1555-06-01:0":{"b": ["এবুসসুউদ এফেন্দির গেদিক (কারিগরি একচেটিয়া অধিকার) প্রশ্ন আইনগতভাবে পরীক্ষা", "5d4e2930"], "d": ["কারিগরি পেশায় নির্দিষ্ট সংখ্যক ব্যক্তিকে দেওয়া একচেটিয়া ও বিশেষাধিকার ‘গেদিক’-এর প্রশ্ন কানুনির আমলে আবার আলোচনায় আসে; শেখুল ইসলাম এবুসসুউদ এফেন্দি 1555-56 সালে বিষয়টি গভীরভাবে পরীক্ষা করে প্রথাটির বৈধতা সুলতানের কাছে উপস্থাপন করেন।", "a4bf6dee"]},
"OLAYLAR_EK14:1557-01-01:0":{"b": ["সেইদি আলি রেইসের মিরআতুল মামালিক ইস্তানবুলে সমাপ্ত", "ee8640e1"], "d": ["বাগদাদ থেকে শুরু করে ফেরার যাত্রাজুড়ে লেখা মিরআতুল মামালিক নামের ভ্রমণগ্রন্থ সেইদি আলি রেইস 1557 সালের জানুয়ারিতে ইস্তানবুলে সমাপ্ত করেন। গ্রন্থটি এক অটোমান নাবিকের ভারত মহাসাগর থেকে মধ্য এশিয়া হয়ে স্থলপথে স্বদেশে ফেরার প্রত্যক্ষ সূত্র।", "3affe91e"]},
"OLAYLAR_EK14:1561-01-01:0":{"b": ["রুস্তেম পাশা কমপ্লেক্সের (মসজিদ) নির্মাণ", "02e30725"], "d": ["আইনদাতার জামাতা ও প্রধান উজির রুস্তেম পাশা স্থপতি সিনানকে দিয়ে যে কমপ্লেক্স নির্মাণ করান তা 1555-1561 সালের মধ্যে গড়া হয়। স্থাপনাটি নিচে খিলানযুক্ত দোকানসহ উঁচু প্ল্যাটফর্মের ওপর নির্মিত অনন্য স্থাপত্য এবং সমৃদ্ধ ইজনিক টাইলের জন্য পরিচিত।", "3a9a7e0b"]},
"OLAYLAR_EK14:1566-01-01:0":{"b": ["মোস্তার সেতু সমাপ্ত", "e7f434af"], "d": ["নেরেতভা নদীর ওপর বিখ্যাত মোস্তার সেতু 1566-67 সাল নাগাদ স্থপতি হায়রেদ্দিন নির্মাণ করেন; 1568 সালের একটি সরকারি দলিলে সেতুর উল্লেখ থাকা এর সমাপ্ত হওয়া নিশ্চিত করে। স্থাপনাটি এক খিলানবিশিষ্ট সূচালো খিলানের ধ্রুপদী অটোমান সেতু স্থাপত্যের সবচেয়ে পরিচিত নিদর্শনগুলোর একটি।", "62de5c2a"]},
"OLAYLAR_EK14:1566-01-01:1":{"b": ["এদির্নেকাপি (মিহরিমাহ সুলতান) মসজিদ সমাপ্ত", "f2d21a82"], "d": ["আইনদাতার কন্যা মিহরিমাহ সুলতানের জন্য 1563 সালে নিশ্চিত হওয়া নির্মাণ অনুমতির পর শুরু হওয়া মসজিদ নির্মাণ 1566 সালে সমাপ্ত হয়; কমপ্লেক্সের ওয়াকফনামা 1570-71 সালে প্রণীত হয়। স্থাপনাটি স্থপতি সিনানের ইস্তানবুলের প্রাচীরের সবচেয়ে কাছের বড় কাজগুলোর একটি।", "0f9e5ecd"]},
"OLAYLAR_EK14:1566-09-08:0":{"b": ["বাকির আইনদাতা সুলতান সুলায়মানের জন্য শোকগাথা রচনা", "7aa6665f"], "d": ["আইনদাতা সুলতান সুলায়মানের জিগেতভারে মৃত্যুর খবর এলে সে যুগের “সুলতানুশ শুআরা” বাকি অটোমান সাহিত্যের সবচেয়ে বিখ্যাত শোকগাথাগুলোর একটি রচনা করেন।", "1328fbfd"]},
"OLAYLAR_EK14:1566-09-30:0":{"b": ["বাকির দ্বিতীয় সেলিমকে সিংহাসন আরোহণের কবিতা উপহার", "6027f034"], "d": ["দ্বিতীয় সেলিমের সিংহাসনে আরোহণের পরপরই বাকি নতুন সুলতানকে একটি “জুলুসিয়ে” (সিংহাসন আরোহণের কবিতা) উপহার দেন — টিডিভি অনুসারে আইনদাতার মৃত্যুতে রচিত শোকগাথার ঠিক পরে।", "1417fae7"]},
"OLAYLAR_EK14:1567-01-01:0":{"b": ["বুয়ুকচেকমেজে সেতু সমাপ্ত", "5f49b3c5"], "d": ["আইনদাতা সুলতান সুলায়মানের আদেশে শুরু হওয়া সেতু সুলতানের জিগেতভার অভিযানকালে মৃত্যুর পর পুত্র দ্বিতীয় সেলিম 1567-68 সালে সম্পন্ন করান। স্থপতি সিনান বুয়ুকচেকমেজে হ্রদ সাগরে মেশার স্থানে নির্মিত সেতুর বন্যায় ক্ষতিগ্রস্ত অংশগুলোও নিজে মেরামত করেন।", "4478b56a"]},
"OLAYLAR_EK14:1568-01-01:0":{"b": ["সেলিমিয়ে মসজিদের (এদির্নে) নির্মাণ শুরু", "07e18c9e"], "d": ["স্থপতি সিনান যাকে “আমার ওস্তাদির কাজ” বলেছেন সেই সেলিমিয়ের নির্মাণ দ্বিতীয় সেলিমের নামে 1568 সালে শুরু হয়ে ছয় বছর চলে 1574 সালে সমাপ্ত হয়। আরাস্তার পশ্চিম দোকান ও শিশুবিদ্যালয় অবশ্য দ্বিতীয় সেলিমের মৃত্যুর পর তৃতীয় মুরাদের সময় দাউদ আগা সম্পন্ন করেন।", "44912c1a"]},
"OLAYLAR_EK14:1572-01-22:0":{"b": ["কিনালিজাদে আলি চেলেবির মৃত্যু — অটোমান নীতিদর্শনের ক্লাসিক গ্রন্থ আখলাক-ই আলাইয়ের লেখক", "dd921873"], "d": ["অটোমান নীতিদর্শনের সবচেয়ে পরিচিত ক্লাসিক গ্রন্থ আখলাক-ই আলাইয়ের লেখক কিনালিজাদে আলি চেলেবি আনাতোলিয়ার কাজিআসকার থাকা অবস্থায় 22 জানুয়ারি 1572 তারিখে মারা যান। তাঁর গ্রন্থের সত্তরটিরও বেশি পাণ্ডুলিপি ইস্তানবুলের গ্রন্থাগারগুলোতে রয়েছে।", "8aa682b5"]},
"OLAYLAR_EK14:1573-01-01:0":{"b": ["পিয়ালে পাশা কমপ্লেক্স নির্মাণ", "75411278"], "d": ["দ্বিতীয় সেলিমের জামাতাদের একজন, নৌ-প্রধান পিয়ালে পাশা কমপ্লেক্সের জমি 1573 সালে কিনে স্থপতি সিনানকে দিয়ে নির্মাণ করান। কমপ্লেক্স মসজিদ, মাদ্রাসা, তেক্কে, সমাধিসৌধ, কবরস্থান, শিশুবিদ্যালয়, ঝরনা, বাজার ও হাম্মামখানায় গঠিত বিস্তৃত স্থাপনা হিসেবে নকশা করা হয়।", "91e37e16"]},
"OLAYLAR_EK14:1577-01-01:0":{"b": ["দ্রিনা (সোকোল্লু মেহমেদ পাশা) সেতু সমাপ্ত", "1d668c73"], "d": ["প্রধান উজির সোকোল্লু মেহমেদ পাশার পৃষ্ঠপোষকতায় স্থপতি সিনান নির্মিত সেতু শিলালিপির তারিখ অনুসারে 1577-78 সালে সমাপ্ত হয়; কিছু গবেষক নির্মাণ 1571-72 সালে শুরু হয়েছিল বলে মনে করেন। সেতুটি সোকোল্লুর জন্মস্থান ভিশেগ্রাদের প্রতি তাঁর অনুরাগের প্রতীক।", "cbbd4b7e"]},
"OLAYLAR_EK14:1577-01-01:1":{"b": ["আজাপকাপি (সোকোল্লু মেহমেদ পাশা) মসজিদ নির্মাণ", "f7b57feb"], "d": ["উনকাপানি সেতুর শিশহানে প্রান্তের খুঁটির পাশে অবস্থিত মসজিদটি প্রধান উজির সোকোল্লু মেহমেদ পাশা স্থপতি সিনানকে দিয়ে নির্মাণ করান। এটি সোকোল্লুর নামে নির্মিত সিনানের দুটি মসজিদের একটি (অন্যটি কাদিরগার মসজিদ)।", "badb6241"]},
"OLAYLAR_EK14:1578-01-02:0":{"b": ["তৃতীয় মুরাদের হুনারনামে রচনার ফরমান", "b125710d"], "d": ["তৃতীয় মুরাদ 2 জানুয়ারি 1578 তারিখের ফরমানে সেইয়িদ লোকমানকে ওসমান গাজী থেকে নিজের সময় পর্যন্ত সুলতানদের জীবন নিয়ে হুনারনামে রচনার আদেশ দেন; গ্রন্থের ক্ষুদ্রচিত্র নাক্কাশ ওসমান ও তাঁর দল প্রস্তুত করে।", "5b7078bd"]},
"OLAYLAR_EK14:1580-01-01:0":{"b": ["জাল মাহমুদ পাশা মসজিদ সমাপ্ত", "732f75bc"], "d": ["জাল মাহমুদ পাশা ও শাহ সুলতানের 1574 সালের বিয়ের পর শুরু হওয়া কমপ্লেক্স নির্মাণে মসজিদের কাজ 1580 সালে সমাপ্ত হয়; মাদ্রাসাগুলো 1582 এবং ঝরনা 1590 পর্যন্ত চলে। কমপ্লেক্সটি আইয়ুপের ঢালে দুটি প্রতিসম মিনারসহ অনন্য নকশার জন্য দৃষ্টি আকর্ষণ করে।", "9cf44e2d"]},
"OLAYLAR_EK14:1588-01-01:0":{"b": ["হুনারনামের দ্বিতীয় খণ্ড সমাপ্ত", "70a1e741"], "d": ["হুনারনামের দ্বিতীয় খণ্ড 1588 সালের জানুয়ারিতে সমাপ্ত হয়; 65টি ক্ষুদ্রচিত্র নিয়ে এটি অটোমান ইতিহাসচর্চার তথ্যগত দিক থেকে সবচেয়ে মূল্যবান গ্রন্থগুলোর একটি হয়ে ওঠে। উভয় খণ্ডই নাক্কাশ ওসমানের কর্মশালায় চিত্রিত।", "148989eb"]},
"OLAYLAR_EK14:1592-01-01:0":{"b": ["দাউদ আগার রাজকীয় প্রধান স্থপতি হওয়া", "8cdc7f53"], "d": ["স্থপতি সিনানের 1588 সালে মৃত্যুর পরের স্বল্প বিরতি থেকে শুরু করে দাউদ আগা 1592 সাল থেকে সরকারি দলিলে রাজকীয় প্রধান স্থপতি হিসেবে উল্লিখিত হতে থাকেন। সেলিমিয়ে কমপ্লেক্সের কিছু সম্পূরক অংশ এবং ইয়েনি মসজিদের প্রথম নির্মাণ হাতে নেওয়া দাউদ আগা সে যুগের অন্যতম গুরুত্বপূর্ণ স্থপতি।", "cca50071"]},
"OLAYLAR_EK14:1598-04-09:0":{"b": ["ইয়েনি মসজিদের (এমিনোনু) ভিত্তি স্থাপন", "d3cddc01"], "d": ["তৃতীয় মেহমেদের মা সাফিয়ে সুলতানের পৃষ্ঠপোষকতায় মসজিদের ভিত্তি, মাটি খুঁটি দিয়ে মজবুত করে পাথরের খণ্ড দিয়ে স্থাপিত হয়। টিডিভির দুটি আলাদা নিবন্ধ এই ঘটনার জন্য ভিন্ন তারিখ দেয় (ইয়েনিজামি কমপ্লেক্স নিবন্ধে 9 এপ্রিল 1598, দাউদ আগা নিবন্ধে 23 আগস্ট 1597); এখানে ভবনের নিজস্ব বিশেষ নিবন্ধের তারিখ ভিত্তি হিসেবে নেওয়া হয়েছে।", "744933c0"]},
"OLAYLAR_EK14:1598-09-01:0":{"b": ["দাউদ আগার মহামারিতে মৃত্যু ও ইয়েনি মসজিদের নির্মাণ অসমাপ্ত থাকা", "81f2cd04"], "d": ["ইয়েনি মসজিদ মাটি থেকে মাত্র এক জিরা উঁচু করার পর 1598 সালের সেপ্টেম্বরে মহামারিতে মারা যাওয়া দাউদ আগার স্থলে দালগিচ আহমেদ চাভুশ প্রধান স্থপতি নিযুক্ত হন। টিডিভি জানায়, মৃত্যুর তারিখ একটি তারিখ-কবিতার ওপর ভিত্তি করা বিকল্প বর্ণনায় 1599-1600 হিসেবেও এসেছে, নিশ্চিত তারিখ নির্ধারণ করা যায়নি।", "02ee24e4"]},
"OLAYLAR_EK14:1599-06-01:0":{"b": ["আঙ্কারার সফ কাপড়ের ইউরোপে ব্যাপক রপ্তানি", "3f37018d"], "d": ["আঙ্কারায় বোনা সফ ও শালি কাপড় ইস্তানবুল, বুরসা, দামেস্ক, আলেপ্পোর মতো অভ্যন্তরীণ বাজারের পাশাপাশি ভেনিস, পোল্যান্ড, ইংল্যান্ড ও ফ্রান্সে রপ্তানি হতো। টিডিভি (TDV)-র দেওয়া উদাহরণে, 1599 সালে আঠারো জন ব্যবসায়ী 5,700,000 আকচে মূল্যের 162 বোঝা সফ কিনে আলেপ্পো ও ভেনিসে পাঠান।", "966119b2"]},
"OLAYLAR_EK14:1603-12-20:0":{"b": ["তৃতীয় মেহমেদের মৃত্যুতে ইয়েনি মসজিদের নির্মাণ থেমে যাওয়া", "5acef053"], "d": ["পৃষ্ঠপোষক সাফিয়ে সুলতানের পুত্র তৃতীয় মেহমেদের 1603 সালে মৃত্যুর পর সাফিয়ে সুলতানকে পুরোনো প্রাসাদে পাঠানো হয় এবং ইয়েনি মসজিদের নির্মাণ অসমাপ্ত থাকে; স্থাপনাটি এই অবস্থায় প্রায় ষাট বছর সমাপ্ত না হয়ে অপেক্ষা করে।", "6d8a4c2b"]},
"OLAYLAR_EK14:1633-01-01:0":{"b": ["কাতিব চেলেবির কাশফুজ জুনুনের জন্য আলেপ্পোয় গবেষণা শুরু", "094e6870"], "d": ["কাতিব চেলেবি পরবর্তীকালে গ্রন্থপঞ্জির মহাকীর্তি হতে চলা কাশফুজ জুনুনের উপকরণ সংগ্রহ 1633 সালে আলেপ্পোয় শুরু করেন। বিশ বছর স্থায়ী এই কাজে তিনি যেসব শহরে গেছেন সেগুলোর গ্রন্থাগার ও বইয়ের দোকান একে একে খুঁজে দেখেছেন।", "92278c89"]},
"OLAYLAR_EK14:1635-01-01:0":{"b": ["ব্যঙ্গকবিতার কারণে নেফির মৃত্যুদণ্ড", "5e459c60"], "d": ["ব্যঙ্গকবিতার জন্য পরিচিত দিওয়ান কবি নেফি সিহাম-ই কাজা নামের ব্যঙ্গসংকলনের কারণে 1635 সালে চতুর্থ মুরাদের আদেশে মৃত্যুদণ্ড পান। প্রধান উজির বায়রাম পাশা তাঁকে সমর্পণ করেন; নেফিকে প্রাসাদের কাঠঘরে শ্বাসরোধ করে হত্যা করে লাশ সাগরে ফেলা হয়।", "e3b52153"]},
"OLAYLAR_EK14:1640-06-01:0":{"b": ["ব্যাপক নার্খ (মূল্যতালিকা) দফতর প্রণয়ন", "6c1e231b"], "d": ["নার্খ (মূল্যের সর্বোচ্চ সীমা) প্রথা অটোমানদের মধ্যে অনেক পুরোনো হলেও আজ পর্যন্ত টিকে থাকা সবচেয়ে ব্যাপক নার্খ দফতরটি 1640 সালের; খাদ্য, পোশাক, সেবা, মান ও স্বাস্থ্যবিধি শর্ত অন্তর্ভুক্ত করা এ দফতর টিডিভি (TDV)-র ভাষায় ‘পূর্ণাঙ্গ বাজার নিয়ন্ত্রণ আইনের মতো কাজ করেছে।’", "3f704851"]},
"OLAYLAR_EK14:1648-01-01:0":{"b": ["কাতিব চেলেবির প্রথমবার জিহাননুমা লেখা শুরু", "554c6734"], "d": ["কাতিব চেলেবি পশ্চিমের ভৌগোলিক আবিষ্কারের মুখে অটোমান ভূগোলজ্ঞানের শূন্যতা পূরণের উদ্দেশ্যে 1648 সালে জিহাননুমার প্রথম রচনা শুরু করেন। কিছু ইউরোপীয় দেশ সম্পর্কে পর্যাপ্ত সূত্র না পাওয়ায় এই প্রথম সংস্করণ অসমাপ্ত থাকে।", "aa7d5e31"]},
"OLAYLAR_EK14:1650-01-01:0":{"b": ["সামরিক শ্রেণির একচেটিয়া দখলে এসে ইলতিজাম ব্যবস্থার পরিণত রূপ", "2c587934"], "d": ["ইলতিজাম পদ্ধতি (কর আদায় মূল্যের বিনিময়ে ব্যক্তিবিশেষকে ইজারা দেওয়া) পঞ্চদশ শতকের দ্বিতীয়ার্ধ থেকে প্রচলিত ছিল, কিন্তু ষোড়শ শতকের শুরু থেকে দ্রুত ছড়িয়ে পড়ছিল। টিডিভি (TDV)-র মতে, এ খাত পুরোপুরি সামরিক শ্রেণির সদস্যদের একচেটিয়া দখলে যাওয়ার প্রক্রিয়া 1650 সালে সম্পন্ন হয়; ইলতিজাম এভাবে তিমার ব্যবস্থার স্থলাভিষিক্ত প্রধান রাজস্ব পদ্ধতিতে পরিণত হয়।", "d50f2237"]},
"OLAYLAR_EK14:1654-12-01:0":{"b": ["কাতিব চেলেবির জিহাননুমা নতুন করে লেখা শুরু", "e9c68110"], "d": ["প্রথম রচনা অসমাপ্ত রাখা কাতিব চেলেবি 1654 সালের শেষে জিহাননুমা নতুন করে লিখতে শুরু করেন। এই দ্বিতীয় সংস্করণও সমাপ্ত হয়নি; গ্রন্থ ভান পর্যন্ত পৌঁছালে 1657 সালে লেখকের মৃত্যুতে তা অসমাপ্ত থাকে এবং কেবল 1732 সালে ইব্রাহিম মুতেফেররিকা এই অবস্থায় ছাপান।", "5a96db0a"]},
"OLAYLAR_EK14:1665-10-30:0":{"b": ["ইয়েনি মসজিদ সমাপ্ত হয়ে উপাসনার জন্য খোলা", "d6d86c82"], "d": ["ষাট বছরের বেশি অসমাপ্ত থাকা ইয়েনি মসজিদের নির্মাণ হাতিজে তুরহান ভালিদে সুলতানের 1661 সালে নিযুক্ত প্রধান স্থপতি মেরেমেতচি মুস্তাফা আগার পরিচালনায় সমাপ্ত হয় এবং 30 অক্টোবর 1665 তারিখে আদায় করা জুমার নামাজের মাধ্যমে উপাসনার জন্য খুলে দেওয়া হয়।", "0ec54cd6"]},
"OLAYLAR_EK14:1675-01-01:0":{"b": ["চতুর্থ মেহমেদের এদির্নেতে খতনা উৎসবে দিনের পর দিন জিরিত খেলানো", "3638a5b6"], "d": ["চতুর্থ মেহমেদ 1675 সালে এদির্নেতে আয়োজিত শাহজাদাদের খতনা উৎসবে দিনের পর দিন চলা জিরিত প্রতিযোগিতার আয়োজন করেন; অটোমান রাজদরবারের জিরিত খেলায় সমর্থনের সবচেয়ে জাঁকালো দৃষ্টান্ত হিসেবে টিডিভির জিরিত নিবন্ধে বিশেষভাবে উল্লিখিত।", "57c8c183"]},
"OLAYLAR_EK14:1679-01-01:0":{"b": ["হাফিজ ওসমানের নিজস্ব লিপিশৈলী বিকাশ", "93081cb3"], "d": ["শেখ হামদুল্লাহর ধারার হাফিজ ওসমান 1679 সালে আকলাম-ই সিত্তে নিজস্ব, পরে “হাফিজ ওসমান ঘরানা” নামে পরিচিত নতুন শৈলী গড়ে তোলেন। এই শৈলী দুই আলাদা শাখায় আজ পর্যন্ত চলে এসেছে।", "8d00a956"]},
"OLAYLAR_EK14:1695-01-01:0":{"b": ["হাফিজ ওসমানের দ্বিতীয় মুস্তাফার লিপিশিক্ষক নিযুক্ত হওয়া", "d976cda4"], "d": ["সে যুগের সবচেয়ে দক্ষ লিপিকার বলে গণ্য হাফিজ ওসমান 1695 সালে সদ্য সিংহাসনে বসা দ্বিতীয় মুস্তাফার লিপিশিক্ষক নিযুক্ত হন। জীবদ্দশায় তিনি প্রায় পঞ্চাশজন লিপিকার তৈরি করেন এবং 25টি কোরআন শরিফ অনুলিপি করেন।", "c70668d5"]},
"OLAYLAR_EK14:1711-01-01:0":{"b": ["ইত্রির মৃত্যু", "62750526"], "d": ["তুর্কি সংগীতের সর্বশ্রেষ্ঠ সুরকারদের একজন বুহুরিজাদে মুস্তাফা ইত্রি এফেন্দি সমসাময়িক সূত্র অনুসারে 1711 সালে মারা যান। সেগাহ তাকবির ও রাস নাত প্রভৃতি রচনায় তিনি মসজিদ ও তেক্কে সংগীতের মহৎ কীর্তিগুলো রেখে যান।", "a2ccc3ba"]},
"OLAYLAR_EK14:1718-01-01:0":{"b": ["নেদিমের তুলিপ যুগের কবিতার অগ্রদূত হিসেবে আত্মপ্রকাশ", "d3c40dbb"], "d": ["1718-1730 সালের তুলিপ যুগজুড়ে নেদিম প্রকাশের নিখুঁততা, সরলতার সন্ধান ও রসিক ভঙ্গিতে স্বতন্ত্র নতুন কাব্যশৈলী গড়ে তোলেন। নেভশেহিরলি দামাত ইব্রাহিম পাশার পরিমণ্ডলে বিকশিত এই শৈলী দিওয়ান কবিতায় দেশজকরণ ধারার সবচেয়ে বড় প্রতিনিধি বলে গণ্য।", "0521666a"]},
"OLAYLAR_EK14:1720-01-01:0":{"b": ["লেভনির সুরনামে-ই ভেহবি চিত্রণ", "8c127866"], "d": ["রাজদরবারের নাক্কাশ লেভনি তৃতীয় আহমেদের শাহজাদাদের 1720 সালের খতনা উৎসব বর্ণনাকারী সুরনামে-ই ভেহবিকে 137টি ক্ষুদ্রচিত্রে চিত্রিত করেন। আগের নিদর্শনের বিপরীতে উৎসবকে কেবল আতমেইদানে বন্দি না রেখে শহরের বিভিন্ন কোণে চিত্রিত করে তিনি অটোমান ক্ষুদ্রচিত্রকলায় নতুন ধারণার সূচনা করেন।", "bd655b91"]},
"OLAYLAR_EK14:1727-06-01:0":{"b": ["একচেটিয়া-ভিত্তিক কারিগর ব্যবস্থা হিসেবে গেদিক ব্যবস্থার আনুষ্ঠানিক প্রতিষ্ঠা", "cd0f79a7"], "d": ["টিডিভি (TDV)-র মতে, গেদিক অধিকার ‘একচেটিয়া, বিশেষাধিকার ও এক ধরনের পেটেন্ট’ অর্থ পাওয়ার পদ্ধতিগত রূপান্তর 1727 থেকে লক্ষ করা যায়; কারিগরি পেশায় নির্দিষ্ট সংখ্যক ব্যক্তিকে কাজের অধিকার দেওয়া এ ব্যবস্থা প্রধানত ওয়াকফ সম্পত্তির দোকানগুলোতে ‘গেদিক অধিকার’ নামে স্থিতি লাভ করে।", "18446662"]},
"OLAYLAR_EK14:1730-09-25:0":{"b": ["পাত্রোনা খলিল বিদ্রোহে সাদাবাদ ধ্বংস", "8a30f9a0"], "d": ["25 সেপ্টেম্বর 1730 তারিখে ফেটে পড়া পাত্রোনা খলিল বিদ্রোহের সময় সাদাবাদের শত শত প্রাসাদ ও স্থাপনা ধ্বংস হয়; তুলিপ যুগের প্রতীক এই কমপ্লেক্স আর আগের জৌলুস ফিরে পায়নি।", "a26b72e6"]},
"OLAYLAR_EK14:1730-10-28:0":{"b": ["পাত্রোনা খলিল বিদ্রোহের সময় নেদিমের মৃত্যু", "06bf909e"], "d": ["পাত্রোনা খলিল বিদ্রোহ ফেটে পড়ার সময় সেকবান আলি পাশা মাদ্রাসার অধ্যাপক ছিলেন নেদিম; বিদ্রোহ-পরবর্তী দিনগুলোতে তিনি মারা যান। মৃত্যুর দিন জানা নেই; তবে তাঁর পরিত্যক্ত সম্পত্তির কাস্সাম হুজ্জাত 15 রবিউল আখির 1143-এ (28 অক্টোবর 1730) প্রণীত হওয়ায় এর আগেই তিনি মারা গেছেন। মৃত্যুর কারণ নিয়ে নানা বর্ণনা আছে: কিছু সূত্র তাঁর ভয়জনিত রোগে (ইল্লেত-ই ওয়েহিমে) কিংবা মদ ও আফিমজনিত কম্পনরোগে মারা যাওয়ার কথা লেখে, মুস্তাকিমজাদে লেখেন বিদ্রোহের সময় ভয়ে ঘরের ছাদে উঠে সেখান থেকে পড়ে মারা গেছেন। তাঁর মৃত্যুতে তুলিপ যুগের সাংস্কৃতিক ঔজ্জ্বল্যও কার্যত শেষ হয়।", "49085a6c"]},
"OLAYLAR_EK14:1732-01-01:0":{"b": ["লেভনির মৃত্যু", "dd48b56e"], "d": ["অটোমান ক্ষুদ্রচিত্রকলার শেষ বড় প্রতিনিধি বলে গণ্য লেভনি 1732 সালে মারা যান। তাঁর কাজের বড় অংশ আজ তোপকাপি প্রাসাদ জাদুঘরে রয়েছে।", "25f589a6"]},
"OLAYLAR_EK14:1749-01-19:0":{"b": ["নুরুওসমানিয়ে মসজিদ ও কমপ্লেক্সের ভিত্তি স্থাপন", "397ec798"], "d": ["নুরুওসমানিয়ে কমপ্লেক্সের ভিত্তি প্রথম মাহমুদ 19 জানুয়ারি 1749 তারিখে স্থাপন করেন। এই স্থাপনা অটোমান স্থাপত্যে ইউরোপীয় বারোক শৈলীর প্রথম বড় প্রয়োগ বলে গণ্য এবং ধ্রুপদী কমপ্লেক্স নকশা থেকে স্পষ্টভাবে আলাদা।", "c1e0698f"]},
"OLAYLAR_EK14:1755-12-05:0":{"b": ["নুরুওসমানিয়ে মসজিদ ও কমপ্লেক্সের উদ্বোধন", "15d83731"], "d": ["প্রথম মাহমুদের শুরু করা কিন্তু সমাপ্তি দেখে যেতে না পারা কমপ্লেক্সের উদ্বোধন তাঁর ভাই তৃতীয় ওসমানের সময় 5 ডিসেম্বর 1755 তারিখে হয়। উদ্বোধনকারী তৃতীয় ওসমানের উদ্দেশে মসজিদ “ওসমানের নুর” অর্থে নাম পায়।", "4722cd6a"]},
"OLAYLAR_EK14:1775-04-29:0":{"b": ["মুহেন্দিসহানে-ই বাহরি-ই হুমায়ুনের উদ্বোধন", "a2fab1cd"], "d": ["অটোমানদের প্রথম আধুনিক নৌ প্রকৌশল বিদ্যালয় মুহেন্দিসহানে-ই বাহরি-ই হুমায়ুন ফরাসি আর্কাইভ দলিল অনুসারে 29 এপ্রিল 1775 তারিখে প্রথম আবদুলহামিদের সময়, প্রধান উজির দেরভিশ মেহমেদ পাশার শাসনকালে চালু হয়।", "cafb2bf9"]},
"OLAYLAR_EK14:1775-06-01:0":{"b": ["এসহাম ব্যবস্থার প্রবর্তন", "eabd8ece"], "d": ["কুচুক কায়নারজা চুক্তির আরোপিত 7.5 মিলিয়ন কুরুশের ক্ষতিপূরণের বোঝার মুখে 1775 সালে এসহাম ব্যবস্থা চালু হয়। মালিকানার (মালিকানে) সীমা ছাড়িয়ে যাওয়ার জন্য নকশা করা এ পদ্ধতিতে মুকাতা আয় অংশে ভাগ করা হতো, এবং মালিকানে থেকে ভিন্নভাবে নারী, অমুসলিম ও সাধারণ মানুষও অংশীদার হতে পারত।", "01a12eaa"]},
"OLAYLAR_EK14:1778-01-09:0":{"b": ["হাম্মামিজাদে ইসমাইল দেদে এফেন্দির জন্ম", "c033f039"], "d": ["তুর্কি সংগীতের সবচেয়ে সৃজনশীল সুরকারদের একজন হাম্মামিজাদে ইসমাইল দেদে এফেন্দি 9 জানুয়ারি 1778 তারিখে ইস্তানবুলের শেহজাদেবাশি এলাকায় জন্মগ্রহণ করেন। জীবনে তিনি 500-এর বেশি রচনা সুরারোপ করেন; এর মধ্যে প্রায় 294টি আজ পর্যন্ত টিকে আছে।", "0b7fc673"]},
"OLAYLAR_EK14:1793-07-14:0":{"b": ["মুহেন্দিসহানে-ই বেররি-ই হুমায়ুনের নির্মাণ শুরু", "4f5d521a"], "d": ["তৃতীয় সেলিমের নিজাম-ই জেদিদ সংস্কারের সবচেয়ে গুরুত্বপূর্ণ প্রতিষ্ঠানগুলোর একটি মুহেন্দিসহানে-ই বেররি-ই হুমায়ুনের নির্মাণ 14 জুলাই 1793 তারিখে শুরু হয়। ভবন 1795 সালের সেপ্টেম্বরে সমাপ্ত হয়ে শিক্ষার জন্য খুলে দেওয়া হয়; প্রতিষ্ঠানটি ইউরোপের সামরিক একাডেমি অনুসরণে গড়া অটোমানদের দ্বিতীয় সামরিক প্রকৌশল বিদ্যালয়।", "79c0131c"]},
"OLAYLAR_EK14:1794-06-01:0":{"b": ["তৃতীয় সেলিমের কিছু কারিগর সংঘের একচেটিয়া অধিকার বিলোপ শুরু", "008f4a7d"], "d": ["টিডিভি (TDV)-র ‘এসনাফ’ (কারিগর) নিবন্ধ অনুযায়ী, প্রতিষ্ঠার সময় থেকে আখি সংগঠনের সঙ্গে জড়িত অটোমান সংঘব্যবস্থায় ‘আখি বাবা’ ও ‘শেখ’-এর মতো কর্মকর্তারা উনবিংশ শতকের শুরু পর্যন্ত সংঘের নেতৃত্ব দিয়েছেন; অষ্টাদশ শতকে সংঘগুলোর একচেটিয়া অধিকারের ফলে দাম নার্খের (মূল্যসীমা) ওপরে উঠে অর্থনৈতিক চাপ সৃষ্টি হলে তৃতীয় সেলিম 1794 থেকে মৌলিক খাদ্য সংঘগুলোর একচেটিয়া অধিকার তুলে দিতে শুরু করেন।", "35d33c12"]},
"OLAYLAR_EK14:1812-01-01:0":{"b": ["দেদে এফেন্দির মুসাহিব-ই শেহরিয়ারি হিসেবে প্রাসাদে গ্রহণ", "0cb99ac3"], "d": ["তৃতীয় সেলিমের সময় একটি বুসেলিক সুরের মাধ্যমে সুলতানের মনোযোগ আকর্ষণ করা দেদে এফেন্দি 1812 সালে দ্বিতীয় মাহমুদ কর্তৃক “মুসাহিব-ই শেহরিয়ারি” (সুলতানের বিশেষ সভাসদ) পদে গৃহীত হন এবং অল্প সময় পরে মুয়াজ্জিনবাশি পদে উন্নীত হন।", "15b3c49d"]},
"OLAYLAR_EK14:1830-12-01:0":{"b": ["অটোমান সাম্রাজ্যে প্রথম নিয়মিত আদমশুমারি", "4f004c6c"], "d": ["দ্বিতীয় মাহমুদ সেনাবাহিনীতে নেওয়ার মতো জনসংখ্যা নির্ণয়ের উদ্দেশ্যে প্রথমবার 1830 সালের শেষ দিকে নিয়মিত গণনা করান; শুধু পুরুষ জনসংখ্যা নথিভুক্ত হয় এবং আনাতোলিয়া-রুমেলিতে প্রায় 7.5 মিলিয়ন মানুষ নির্ণীত হয়। এরজুরুম ও ভানের মতো কিছু অঞ্চলে গণনা কেবল 1836 সালে শেষ করা সম্ভব হয়।", "af4a7bcf"]},
"OLAYLAR_EK14:1833-06-01:0":{"b": ["ফেসহানে-ই আমিরের প্রতিষ্ঠা", "971ab85a"], "d": ["1826 সালে জ্যানিসারি বাহিনী বিলুপ্ত হওয়ার পর গঠিত আসাকির-ই মানসুরে-ই মুহাম্মদিয়ে বাহিনীর ফেজ টুপির চাহিদা মেটাতে 1.5 মিলিয়ন কুরুশ পুঁজি নিয়ে 1833 সালে কাদিরগার জুন্দি ময়দানে ফেজ উৎপাদন শুরু হয়। স্থাপনাগুলো 1839 সালে আইয়ুপের হাতিজে সুলতান প্রাসাদে স্থানান্তরিত হয়; ফেসহানে অটোমান বস্ত্রশিল্পের ভিত্তি গড়ে তোলে।", "c8481f41"]},
"OLAYLAR_EK14:1839-05-14:0":{"b": ["চিকিৎসা বিদ্যালয়ের মেকতেব-ই তিব্বিয়ে-ই আদলিয়ে-ই শাহানে নাম গ্রহণ", "187d60f3"], "d": ["গালাতাসারায়ের এন্দেরুন আগাদের বিদ্যালয় ভবনে স্থানান্তরিত চিকিৎসা বিদ্যালয় 14 মে 1839 তারিখে দ্বিতীয় মাহমুদের সফরের মাধ্যমে “মেকতেব-ই তিব্বিয়ে-ই আদলিয়ে-ই শাহানে” নাম পায়; প্রতিষ্ঠান এভাবে সামরিক-প্রশাসনিক বিদ্যালয়ের পরিচয়ে আনুষ্ঠানিক স্বীকৃতি পায়।", "6a65292b"]},
"OLAYLAR_EK14:1846-11-29:0":{"b": ["দেদে এফেন্দির হজ্জের সময় মিনায় মৃত্যু", "c3e613a2"], "d": ["হজ্জ ফরজ আদায়ে গিয়ে মিনায় কলেরায় আক্রান্ত হাম্মামিজাদে ইসমাইল দেদে এফেন্দি 29 নভেম্বর 1846 তারিখে মারা যান। 1824-1839 সালের মধ্যে সাতটি আলাদা মেভলেভি আয়িন সুরারোপ করা এই শিল্পীর মৃত্যুতে ধ্রুপদী অটোমান সংগীতের একটি যুগ শেষ হয়।", "fea95526"]},
"OLAYLAR_EK14:1850-06-01:0":{"b": ["1850 সালের বাণিজ্য আইনবিধি গ্রহণ", "8ac085fd"], "d": ["তানজিমাত যুগের আইনি সংস্কারের অংশ হিসেবে পশ্চিমা রাষ্ট্রগুলো থেকে অনুবাদ ও গ্রহণের মাধ্যমে নতুন আইন নেওয়া হয়: দণ্ডবিধি 1840 সালে, বাণিজ্য আইন 1850 সালে, ভূমি আইন 1857 সালে কার্যকর হয়। বাণিজ্য আইনবিধি ছিল অটোমান বাণিজ্য আইনের প্রথম আধুনিক সংহিতাকরণ।", "2f7aeb1b"]},
"OLAYLAR_EK14:1859-06-01:0":{"b": ["ক্রিমিয়ান তাতার ও ককেশীয় জনগোষ্ঠীর অটোমান ভূমিতে ব্যাপক অভিবাসন-স্রোতের সূচনা", "8832c06d"], "d": ["1859 সালে শেখ শামিল রুশদের হাতে বন্দি হওয়ার পর ক্রিমিয়ান তাতারদের সঙ্গে ককেশাস থেকে বহু সার্কাসীয় ও নোগাই মুহাজির অটোমান ভূমিতে আসতে শুরু করে। এ অভিবাসন-স্রোত 1877-78 সালের অটোমান-রুশ যুদ্ধের পর পর্যন্ত বিভিন্ন তীব্রতায় চলতে থাকে।", "580ce507"]},
"OLAYLAR_EK14:1860-01-16:0":{"b": ["মুহাজিরিন কমিশন গঠন", "9717e77e"], "d": ["ককেশাস থেকে বাড়তে থাকা অভিবাসন-স্রোত পরিচালনার জন্য অটোমান সরকার 16 জানুয়ারি 1860 তারিখে মুহাজিরিন কমিশন গঠন করে। কমিশন আনাতোলিয়া, বলকান ও সিরিয়ার বসতি স্থাপন কার্যক্রম সমন্বয় করে এবং 1875 সাল পর্যন্ত কাজ চালায়।", "404d989d"]},
"OLAYLAR_EK14:1863-06-01:0":{"b": ["ব্যাংক-ই ওসমানির ব্যাংক-ই ওসমানি-ই শাহানে (অটোমান ব্যাংক) রূপে পুনর্গঠন", "c3530456"], "d": ["1856 সালে ক্রিমিয়ান যুদ্ধের পর বৈদেশিক ঋণ পরিশোধ পরিচালনার জন্য লন্ডনকেন্দ্রিক, ব্রিটিশ পুঁজির ব্যাংক-ই ওসমানি প্রতিষ্ঠিত হয়েছিল। 1863 সালে ফরাসি-ব্রিটিশ যৌথ গোষ্ঠীকে ব্যাংক-ই ওসমানি-ই শাহানে (অটোমান ব্যাংক) নামে নতুন ব্যাংক গঠনের অনুমতি দেওয়া হয়; প্রতিষ্ঠানটি পরে ব্যাংকনোট ছাপার ক্ষমতাও পায়।", "72227299"]},
"OLAYLAR_EK14:1864-03-30:0":{"b": ["জেমইয়েত-ই তেদরিসিয়ে-ই ইসলামিয়ের প্রতিষ্ঠা", "77ad553a"], "d": ["দরিদ্র মুসলিম শিক্ষানবিশদের শিক্ষার দায়িত্ব নেওয়ার উদ্দেশ্যে 30 মার্চ 1864 তারিখে জেমইয়েত-ই তেদরিসিয়ে-ই ইসলামিয়ে প্রতিষ্ঠিত হয়; এ বেসামরিক সমিতি-উদ্যোগ দাতব্য প্রতিষ্ঠানের ঐতিহ্য আধুনিক বিদ্যালয় প্রকল্পে রূপান্তরের এক অগ্রণী দৃষ্টান্ত। সমিতি নয় বছর পর দারুশশাফাকা খুলবে।", "2ea443d2"]},
"OLAYLAR_EK14:1864-06-01:0":{"b": ["1864 সালের ভিলায়েত বিধিমালায় মুখতার ও প্রবীণ পরিষদ ব্যবস্থার বিন্যাস", "1a2e8cf2"], "d": ["1864 সালের ভিলায়েত বিধিমালায় গ্রাম প্রশাসন নতুন করে সাজানো হয়; মুসলিম ও অমুসলিমরা একসঙ্গে বসবাসকারী গ্রামে প্রতিটি সম্প্রদায়ের নিজ মুখতার ও প্রবীণ পরিষদ (ইহতিয়ার মজলিস) নির্বাচনের বিধান গৃহীত হয়। প্রবীণ পরিষদ এভাবে প্রথমবার গ্রাম/মহল্লা প্রশাসনে আনুষ্ঠানিক স্থান পায়।", "eee4df7d"]},
"OLAYLAR_EK14:1864-07-01:0":{"b": ["মহান সার্কাসীয় বহিষ্কারের চূড়ান্ত পর্ব", "b2ab1874"], "d": ["1858-1878 সালের মধ্যে, সবচেয়ে তীব্রভাবে 1861-1864 সালে রাশিয়ার ককেশাস দখলের ফলে 1.2-1.5 মিলিয়ন সার্কাসীয়কে জোরপূর্বক অটোমান ভূমিতে অভিবাসনে বাধ্য করা হয়। টিডিভি (TDV)-র মতে বহু গবেষক এ ঘটনাকে ‘আধুনিক ইতিহাসের প্রথম জাতিগত নির্মূল অভিযান’ বলে অভিহিত করেন।", "d1bb6d70"]},
"OLAYLAR_EK14:1869-09-01:0":{"b": ["1869 সালের মাআরিফ-ই উমুমিয়ে বিধিমালা প্রকাশ", "787f6022"], "d": ["1 সেপ্টেম্বর 1869 তারিখে প্রকাশিত মাআরিফ-ই উমুমিয়ে বিধিমালা প্রদেশ ও কেন্দ্রে সাধারণ শিক্ষা নিয়ন্ত্রণকারী প্রথম ব্যাপক দলিল হয়। বিধিমালা দ্বারা মজলিস-ই কেবির-ই মাআরিফ গঠিত হয়; সিবইয়ান মক্তবগুলোকে নিছক ধর্মীয় শিক্ষার পর্যায় থেকে বের করে লেখাপড়া শেখানোর দিকে পুনর্গঠনের কাজ এ ব্যবস্থায় শুরু হয়।", "51087b3c"]},
"OLAYLAR_EK14:1873-06-28:0":{"b": ["দারুশশাফাকা বিদ্যালয়ের শিক্ষাদান শুরু", "525c457c"], "d": ["জেমইয়েত-ই তেদরিসিয়ে-ই ইসলামিয়ের প্রতিষ্ঠিত দারুশশাফাকা 28 জুন 1873 তারিখে এতিম ও দরিদ্র মুসলিম শিশুদের বিনামূল্যে আবাসিকভাবে শিক্ষাদানের লক্ষ্যে কার্যত পাঠদান শুরু করে; ভর্তির সর্বোচ্চ বয়স দশ নির্ধারিত হয়।", "c4f863b5"]},
"OLAYLAR_EK14:1894-07-10:0":{"b": ["1894 সালের ইস্তানবুল ভূমিকম্প", "7ae7f648"], "d": ["10 জুলাই 1894 তারিখে ইজমিত উপসাগরের উপকূলের কাছে ঘটা ভূমিকম্প ইস্তানবুলকে মারাত্মকভাবে আঘাত করে; ইস্তানবুলের প্রাচীর সহ বহু মসজিদ ও ঐতিহাসিক স্থাপনা ক্ষতিগ্রস্ত হয়। টিডিভি (TDV)-র ‘জেলজেলে’ (ভূমিকম্প) নিবন্ধ এ ভূমিকম্পকে 1509, 1719 ও 1766 সালের ভূমিকম্পের সঙ্গে মারমারা অঞ্চলে ব্যাপক প্রাণ ও সম্পদহানি ঘটানো ভূমিকম্পগুলোর মধ্যে গণ্য করে।", "61236a0f"]},
"OLAYLAR_EK14:1896-02-02:0":{"b": ["দারুলআজেজের উদ্বোধন", "a30baf31"], "d": ["দ্বিতীয় আবদুলহামিদের 1890 থেকে দেওয়া নির্দেশে প্রস্তুত দারুলআজেজে 2 ফেব্রুয়ারি 1896 তারিখে প্রধান উজির হালিল রিফাত পাশা উদ্বোধন করেন। অভিভাবকহীন শিশু, বৃদ্ধ ও অভাবীদের আশ্রয়দানকারী এ প্রতিষ্ঠান 200 শয্যার হাসপাতাল, কারখানা এবং মসজিদ-গির্জা-সিনাগগের মতো আলাদা উপাসনালয় নিয়ে তার সময়ের বৃহত্তম সামাজিক সহায়তা কমপ্লেক্স ছিল।", "9cf12efa"]},
"OLAYLAR_EK14:1900-08-31:0":{"b": ["দারুলফুনুন-ই শাহানের স্থায়ী প্রতিষ্ঠান হিসেবে পুনঃপ্রতিষ্ঠা", "7d6d8fc4"], "d": ["দারুলফুনুন আগের দুটি ব্যর্থ প্রচেষ্টার (1863 ও 1870) পর 31 আগস্ট 1900 তারিখে দারুলফুনুন-ই শাহানে নামে স্থায়ী প্রতিষ্ঠান হিসেবে পুনঃপ্রতিষ্ঠিত হয়; টিডিভি এই তারিখকে বর্তমান তুর্কি বিশ্ববিদ্যালয় ব্যবস্থার প্রত্যক্ষ ভিত্তি বলে বর্ণনা করে।", "7d7fd7ca"]},
"OLAYLAR_EK15:1337-09-09:0":{"b": ["সারবেদাররা সাবজেভার দখল করল — খোরাসানে ইলখানি-পরবর্তী প্রথম রাষ্ট্র", "af997fec"], "d": ["আবু সাইদের মৃত্যুতে (30 নভেম্বর 1335) ইলখানি কেন্দ্রীয় কর্তৃত্ব ভেঙে পড়লে খোরাসানে কর আদায়কারীদের বিরুদ্ধে জমে থাকা ক্ষোভ বাশতিনে বিস্ফোরিত হয়: আবদুর রাজ্জাক 13 মার্চ 1337 তারিখে বিদ্রোহ করেন, 9 সেপ্টেম্বর 1337 তারিখে (12 সফর 738) সাবজেভার দখল করেন। ‘সারবেদার’ — ‘মাথা ফাঁসিকাষ্ঠে’ — নামটি তাদের নিজেদেরই কথা, যা বোঝায় পরাজিত হলে ফাঁসি মেনে নেওয়ার সাহস তাদের ছিল।", "c0abed9c"]},
"OLAYLAR_EK15:1359-01-01:0":{"b": ["মারআশি সৈয়দরা আমুল দখল করল — মাজেন্দারানে সৈয়দ কর্তৃত্ব", "c0e03266"], "d": ["সৈয়দ কিওয়ামুদ্দিন মারআশি, সারবেদারদের খোরাসানে খোলা পথ ধরে 760 (1359) সালে আমুল দখল করেন এবং কাস্পিয়ান সাগরের দক্ষিণ উপকূলে একটি সৈয়দ রাষ্ট্র গড়েন। রাজবংশ সারি, বারফুরুশ ও আশপাশে ছড়িয়ে পড়ে; তৈমুরের অভিযানে নড়বড়ে হয় এবং সাফাভি প্রথম শাহ আব্বাসের আমলে বিলুপ্ত হয়।", "d93ea1fd"]},
"OLAYLAR_EK15:1371-01-01:0":{"b": ["কারকিয়া রাজবংশ গিলানে প্রতিষ্ঠিত — কাস্পিয়ান উপকূলের শেষ স্বাধীন শাসক", "6e5f9db7"], "d": ["আলি কিয়া পরিবারসহ গিলানে ফিরে 773 (1371-72) সালে লাহিজান-কেন্দ্রিক কারকিয়া কর্তৃত্ব প্রতিষ্ঠা করেন; রাজবংশ কাস্পিয়ানের দক্ষিণ-পশ্চিম উপকূল দুই শতকেরও বেশি সময় নিজ হাতে রাখে এবং সাফাভি প্রথম শাহ আব্বাসের 1592 সালে অঞ্চলটি সংযুক্তি পর্যন্ত টিকে থাকে।", "670fc7fd"]},
"OLAYLAR_EK15:1400-01-01:0":{"b": ["দারফুরে দাজু কর্তৃত্ব তুনজুরদের হাতে যাওয়া", "6eb22a2a"], "d": ["টিডিভি ইসলাম বিশ্বকোষের দারফুর নিবন্ধ অনুযায়ী অঞ্চলে প্রথম বসতি স্থাপনকারী ও প্রথম রাষ্ট্র গড়া হলো দাজু গোত্র; ত্রয়োদশ ও চতুর্দশ শতক জুড়ে এখানে কর্তৃত্ব করা দাজুরা বাণিজ্যিক আধিপত্য তুনজুরদের হাতে হারায়, পঞ্চদশ শতকে বিশেষত মধ্যাঞ্চলের পরিস্থিতি পুরোপুরি তুনজুরদের পক্ষে ঘুরে যায়।", "2709880c"]},
"OLAYLAR_EK15:1564-01-01:0":{"b": ["স্পেন কর্তৃক বাদিস (পেনিওন দে ভেলেস) শৈলদুর্গ পুনর্দখল", "0dc52728"], "d": ["টিডিভি (TDV)-র সাদি রাজবংশ নিবন্ধ উল্লেখ করে যে স্পেনীয়দের বাদিস দখল মাগরিবের নৌ-কার্যক্রমে ভারী আঘাত ছিল (1564)। উত্তর মরক্কো উপকূলের এ শৈলঘাঁটি পশ্চিম ভূমধ্যসাগরে জলদস্যুতা ও অটোমান-স্পেনীয় প্রতিদ্বন্দ্বিতার ভিত্তি ছিল।", "110ee39e"]},
"OLAYLAR_EK15:1610-01-01:0":{"b": ["আল-আরাইশের (লারাশ) স্পেনের হাতে ছেড়ে দেওয়া", "7b8f6e27"], "d": ["সাদি রাজবংশ খণ্ডবিখণ্ড হওয়া গৃহযুদ্ধের বছরগুলোতে আটলান্টিক উপকূলের আল-আরাইশ বন্দর স্পেনের হাতে ছেড়ে দেওয়া হয়। টিডিভি (TDV)-র সাদি রাজবংশ নিবন্ধ এ সময়ে দেশ মারাকেশ (দক্ষিণ) ও ফেজ (উত্তর) আমিরাতে দ্বিধাবিভক্ত হওয়া এবং সিংহাসন-দ্বন্দ্বের পক্ষগুলোর বাইরে সাহায্য খোঁজার কথা উল্লেখ করে। বন্দরটি আশি বছরের কাছাকাছি স্পেনীয় হাতে থাকবে, 1689 সালে মওলায় ইসমাইল পুনর্দখল করবেন।", "597cc620"]},
"OLAYLAR_EK15:1614-01-01:0":{"b": ["মামুরার (মেহদিয়া) স্পেনীয়দের হাতে যাওয়া", "c8fd494e"], "d": ["সেবু নদীর মোহনার মামুরা (মামুরে / মেহদিয়া) বন্দর 1614 সালে স্পেনীয়দের হাতে যায় এবং সান মিগুয়েল দে উলট্রামার নামে সুরক্ষিত করা হয়। টিডিভি (TDV)-র মওলায় ইসমাইল নিবন্ধ উল্লেখ করে যে বন্দরটি 1092 (1681) সালে আকস্মিক হামলায় স্পেনীয়দের হাত থেকে পুনরুদ্ধার করা হয় — অর্থাৎ স্পেনীয় কর্তৃত্ব সাতষট্টি বছর স্থায়ী হয়েছিল।", "3f87063c"]},
"OLAYLAR_EK15:1659-01-01:0":{"b": ["সাদি রাজবংশের অবসান — মরক্কোয় আলাউই (ফিলালি) যুগের সূচনা", "b1afa579"], "d": ["টিডিভি ইসলাম বিশ্বকোষ সাদি রাজবংশ নিবন্ধে এদের সংজ্ঞায়িত করে ‘মরক্কোয় শাসনকারী এক ইসলামি রাজবংশ (1511-1659)’ বলে। 1549 সালে ওয়াত্তাসি কর্তৃত্বের অবসান ঘটিয়ে সমগ্র মরক্কো একত্র করা, 1578 সালে ওয়াদি আল-মাখাজিনে পর্তুগিজ বাহিনী ধ্বংস করা এবং কোনো সময়ই অটোমানদের অধীন না হওয়া এ রাজবংশ দীর্ঘ সিংহাসন-দ্বন্দ্বের পর 1659 সালে শেষ হয়। তাদের স্থান নেন তাফিলালত থেকে আসা আলাউই (ফিলালি) শরিফরা; মওলায় রশিদ 1666 সালে ফেজ শহরে প্রবেশ করে নতুন রাজবংশ সুদৃঢ় করেন এবং তাঁর ভাই মওলায় ইসমাইল আটলান্টিক উপকূলের ইউরোপীয় ঘাঁটিগুলো পরিষ্কার করেন।", "5569a65c"]},
"OLAYLAR_EK15:1673-01-01:0":{"b": ["স্পেনের আল-হোসেইমা (আলহুসেমাস) দ্বীপপুঞ্জ দখল", "954ca998"], "d": ["ভূমধ্যসাগরীয় উপকূলের আল-হোসেইমা দ্বীপপুঞ্জ ১৬৭৩ সালে স্পেনীয়দের হাতে যায়। বাদিস ও সেউতার সঙ্গে এগুলো মরক্কোর উত্তর উপকূলে স্পেনের ধরে রাখা অবস্থানগুলোর অন্তর্ভুক্ত। প্রায় একই সময়ে মাওলায় ইসমাইল তাঁর ভ্রাতুষ্পুত্র আহমাদ ইবনে মুহরিজের বাহিনীকে পরাজিত করে মারাকেশে প্রবেশ করেছিলেন এবং আনুগত্যের শপথ গ্রহণ করেছিলেন; সিংহাসনের লড়াই চলছিল।", "88bb5d19"]},
"OLAYLAR_EK15:1689-01-01:0":{"b": ["মওলায় ইসমাইল কর্তৃক আল-আরাইশ স্পেনীয়দের থেকে পুনরুদ্ধার", "a54bc6ee"], "d": ["টিডিভি (TDV)-র মওলায় ইসমাইল নিবন্ধ স্পষ্ট: ‘1100 সালে (1689) আরাইশ স্পেনীয়দের থেকে পুনরুদ্ধার করে 200 কামান হস্তগত করলেন, দুই বছর পর আসিলাও ফিরিয়ে নিলেন।’ এটি ফিলালি সুলতানের উপকূল-পরিষ্কার শৃঙ্খলের একটি কড়া — তাঞ্জা 1678 সালে ইংরেজদের থেকে, মামুরা 1681 সালে, আল-আরাইশ 1689 সালে, আসিলা 1691 সালে পুনরুদ্ধার হয়। আশি বছর আগে সাদি গৃহযুদ্ধে ছেড়ে দেওয়া বন্দর এভাবে মরক্কোয় ফিরে আসে।", "cd2b390d"]},
"OLAYLAR_EK15:1695-01-01:0":{"b": ["দারফুর সুলতানাতের প্রতিষ্ঠা — কেইরা রাজবংশ ও সুলায়মান সোলোঞ্জ", "0fc1c112"], "d": ["টিডিভি (TDV)-র মতে দারফুর সুলতানাতের প্রতিষ্ঠা সপ্তদশ শতকের শেষ দিকে বুমু আল-কাসিরের অঞ্চল আক্রমণের পর সৃষ্ট বিশৃঙ্খলার পরে ঘটে। ফুররা সুলায়মান সোলোঞ্জের নেতৃত্বাধীন কিরা (কেইরা) বংশের অগ্রনায়কত্বে দাজু ও তুনজুরদের হাত থেকে কর্তৃত্ব নিয়ে সুদৃঢ় শাসন গড়ে তোলে। সুলায়মান সোলোঞ্জ 1695-1715 সালে শাসন করেন। দারফুরের সুলতানরা পরবর্তী শতকগুলোতে বাবে আলির সঙ্গে পত্রবিনিময় করতেন; আবদুলমেজিদ ও আবদুলআজিজ তাঁদের শাসন অনুমোদন করেন।", "58155fc4"]},
"OLAYLAR_EK15:1792-09-22:0":{"b": ["ফ্রান্সে প্রথম প্রজাতন্ত্র ঘোষণা — রাজতন্ত্রের অবসান", "d53d49b0"], "d": ["জাতীয় কনভেনশনের প্রথম অধিবেশনে রাজতন্ত্র বিলুপ্ত হয় এবং পরদিন প্রথম প্রজাতন্ত্র ঘোষিত হয়; নতুন পঞ্জিকার প্রথম বছর এ দিন থেকে গণনা শুরু হয়। অটোমানদের দিক থেকে সামনের পক্ষ বদলায়নি, কিন্তু পক্ষের চরিত্র বদলে যায়: তৃতীয় সেলিমের নিজাম-ই জেদিদ বছরগুলোতে ফ্রান্স আর কোনো রাজবংশ নয়, একটি শাসনব্যবস্থা ছিল, এবং 1798 সালে মিসরে অবতরণকারী ছিল সেই ব্যবস্থারই সেনাবাহিনী।", "a16f5b39"]},
"OLAYLAR_EK15:1857-07-11:0":{"b": ["মহান কাবিলিয়ার পতন — লালা ফাতমা এন’সুমেরের বন্দিত্ব", "0f61ff08"], "d": ["টিডিভি (TDV)-র ‘আলজেরিয়া’ নিবন্ধ উল্লেখ করে যে পার্বত্য কাবিলিয়া (বিলাদুল কাবাইল) অঞ্চল 1853, 1854 ও 1857 সালের অভিযানের শেষে দখল হওয়ায় ফ্রান্সের আলজেরিয়া দখল অভিযান মূলত সম্পন্ন হয়। 1857 সালের অভিযান তিজি উজু ও আকবু সারি ভেঙে দেয়; প্রতিরোধের প্রতীক লালা ফাতমা এন’সুমের বন্দি হন। আমির আবদুলকাদিরের 1847 সালের আত্মসমর্পণের পর টিকে থাকা শেষ বড় প্রতিরোধকেন্দ্র এভাবে নিভে যায়।", "6d14160e"]},
"OLAYLAR_EK15:1899-12-29:0":{"b": ["আইন সালিহ (তিদিকেল্ট) ফরাসিদের দখলে", "1e28d1d0"], "d": ["সাহারার মাঝখানে তিদিকেল্ট মরূদ্যান-গুচ্ছের কেন্দ্র আইন সালিহ 29 ডিসেম্বর 1899 তারিখে ফরাসি বাহিনীর দখলে যায়। এটি আলজেরীয় উপকূল থেকে দক্ষিণে নামা ফরাসি বিস্তারের মরুভূমিতে পৌঁছানো প্রথম বড় পদক্ষেপ; দুই বছরের মধ্যে তুওয়াত ও গুরারাও একই পথ ধরবে।", "99e7ecb6"]},
"OLAYLAR_EK15:1901-02-21:0":{"b": ["তুওয়াত · গুরারা · তিদিকেল্ট মরূদ্যানের ফ্রান্সের সঙ্গে সংযুক্তি", "d412838b"], "d": ["আলজেরিয়ার দক্ষিণ-পশ্চিমের তুওয়াত, গুরারা ও তিদিকেল্ট মরূদ্যান-বলয় 21 ফেব্রুয়ারি 1901 তারিখে আনুষ্ঠানিকভাবে ফ্রান্সের সঙ্গে যুক্ত হয়। মরক্কোর সুলতান নামমাত্র দাবি করা এ কাফেলাপথের সংযোগস্থল — আদরার, তিমিমুন, রেগ্গান ও বেনি আব্বাস সহ — এভাবে আলজেরিয়ার অংশ হয়; মরক্কো ও ফরাসি আলজেরিয়ার মধ্যে সীমান্ত বিরোধের সূচনা এটিই।", "c50f9569"]},
"OLAYLAR_EK15:1903-11-11:0":{"b": ["বেশ্শারে (কোলোঁ-বেশার) ফরাসি ঘাঁটি স্থাপন", "4d44d252"], "d": ["মরক্কো সীমান্তের বেশ্শার মরূদ্যান 11 নভেম্বর 1903 তারিখে ফরাসি বাহিনীর দখলে যায় এবং কোলোঁ-বেশার নামে অগ্রবর্তী ঘাঁটিতে পরিণত হয়। তুওয়াত বলয় সংযুক্তির দুই বছর পরের এ পদক্ষেপ আলজেরিয়া থেকে মরক্কোর দিকে ফ্রান্সের অগ্রগতির শেষ কড়াগুলোর একটি; 1912 সালে মরক্কোকে আশ্রিত রাষ্ট্র করার পথ খুলে দেয়।", "bd1a7ae2"]},
"OLAYLAR_EK16:1283-01-01:0":{"b": ["মস্কো প্রিন্সিপালিটির প্রতিষ্ঠা — প্রথম দানিল", "49549309"], "d": ["আলেক্সান্দর নেভস্কির কনিষ্ঠ পুত্র দানিল মস্কোকে স্বাধীন প্রিন্সিপালিটি হিসেবে শাসন করতে শুরু করেন। সেই সময় মস্কো ভ্লাদিমির-সুজদাল ভূমির একটি ছোট ও গুরুত্বহীন কেন্দ্র ছিল; রুশ ইতিহাসচর্চা এই তারিখকে পরবর্তী উত্থানের সূচনাবিন্দু ধরে।", "10cf92d1"]},
"OLAYLAR_EK16:1297-01-01:0":{"b": ["কারেসি ও হামিদোগুল্লারি বেইলিকের প্রতিষ্ঠা", "3905da93"], "d": ["টিডিভি (TDV)-র কারেসিওগুল্লারি নিবন্ধ অনুযায়ী কারেসি বেগ, পিতা কালেম বেগের মৃত্যুতে ভেঙে পড়া সেলজুক সীমান্ত সংগঠনে স্বাধীনতা ঘোষণা করে 696 (1296-97) থেকে বালিকেসিরকে কেন্দ্র করেন এবং অল্প সময়ে এরদেক, বিগা, এদরেমিত, বের্গামা সহ মাইসিয়ার সবটুকু বাইজেন্টাইনদের থেকে নেন। একই বছর (1297) হামিদ বেগ উলুবোরলুকে সরকারকেন্দ্র করে হামিদোগুল্লারি বেইলিক প্রতিষ্ঠা করেন; ইস্পার্তা, বুরদুর, এইরদির ও ইয়ালভাচ ভেঙে পড়া সেলজুক সীমান্তাঞ্চল থেকে বেইলিকের প্রথম সীমানায় যুক্ত হয়। দুই বেইলিকই পশ্চিম আনাতোলিয়ায় একই পতনের — সেলজুক কেন্দ্রীয় কর্তৃত্ব ভেঙে পড়ার — ফল।", "7d297343"]},
"OLAYLAR_EK16:1301-01-01:0":{"b": ["মস্কোর প্রিন্স দানিল কলোমনা ও সেরপুখভ মস্কোর সঙ্গে যুক্ত করলেন", "6d82dccd"], "d": ["দানিল রিয়াজান প্রিন্সিপালিটির কাছ থেকে কলোমনা (বন্দী রিয়াজান রাজকুমার মুক্তির জন্য দুর্গটি ছেড়ে দেন) ও সেরপুখভ নেন; মস্কো ওকা নদীতে পৌঁছায় এবং এটি মস্কো প্রিন্সিপালিটির প্রথম ভূমি সম্প্রসারণ ছিল।", "f6b7a96c"]},
"OLAYLAR_EK16:1304-01-01:0":{"b": ["মোজাইস্ক স্মোলেনস্ক প্রিন্সিপালিটির কাছ থেকে নিয়ে মস্কোর সঙ্গে যুক্ত হলো", "462055a0"], "d": ["মস্কো প্রিন্সিপালিটি মস্কো নদীর উচ্চ অববাহিকার মোজাইস্ক স্মোলেনস্কের কাছ থেকে নিয়ে পশ্চিম সীমান্ত লিথুয়ানিয়ার কাছাকাছি নিয়ে যায়।", "3002aa5d"]},
"OLAYLAR_EK16:1307-01-01:0":{"b": ["পোলোৎস্ক প্রিন্সিপালিটি লিথুয়ানিয়ার গ্র্যান্ড ডাচিতে গেল", "04a26a6f"], "d": ["পোলোৎস্ক, ভিতেবস্ক ও আশপাশের অঞ্চল 1307 সাল পর্যন্ত রুশ প্রিন্সিপালিটি রাজবংশের মধ্যে ছিল; গেদিমিনাসের পূর্বে লিথুয়ানিয়ার পূর্বদিকে বিস্তার এই হস্তান্তরের মাধ্যমে স্পষ্ট হয় (এখানে 1307 কে ভিত্তি ধরা হয়েছে; ভিতেবস্কের প্রকৃত হস্তান্তর ≈1320 বিতর্কিত)।", "d5bcf63e"]},
"OLAYLAR_EK16:1308-01-01:0":{"b": ["আয়দিনোগুল্লারি বেইলিকের প্রতিষ্ঠা — ইজমির, আয়াসুলুক, তিরে দখল", "69a021ae"], "d": ["টিডিভি (TDV)-র আয়দিনোগুল্লারি নিবন্ধ অনুযায়ী মুবারিজুদ্দিন গাজি মেহমেদ বেগ, গেরমিয়ানোগুল্লারি সীমান্ত বেগ সাসা বেগের কাছ থেকে এ অঞ্চল নিয়ে 1308 সালে আয়দিন-ইলিতে কর্তৃত্ব স্থাপন করেন; ইজমিরের মুসলিম অংশ, আয়াসুলুক (সেলচুক), তিরে ও বোদেমিয়ার সঙ্গে, জয় করেন। আয়াসুলুককে নৌঘাঁটি করেন এবং দখলকৃত ভূমি পাঁচ পুত্রের মধ্যে ভাগ করে দেন — বেইলিক পরবর্তী দশকগুলোতে, বিশেষত পুত্র উমুর বেগের আমলে, এজিয়ান নৌ-কর্মকাণ্ডে নির্ধারক শক্তি হবে।", "9c871e7d"]},
"OLAYLAR_EK16:1308-01-01:1":{"b": ["আনাতোলীয় সেলজুক রাষ্ট্রের কার্যত অবসান — ইলখানির সরাসরি শাসন", "00f85ecb"], "d": ["টিডিভি (TDV)-র দ্বিতীয় মাসউদ নিবন্ধ অনুযায়ী দীর্ঘ অসুস্থতার পর 708 (1308) সালে কায়সেরিতে মারা যাওয়া দ্বিতীয় গিয়াসুদ্দিন মাসউদ সর্বসম্মত মতে আনাতোলীয় সেলজুক রাষ্ট্রের শেষ শাসক — তাঁর মৃত্যুর পর সিংহাসনে বসানো প্রার্থীরা না অভ্যন্তরীণ কর্তৃপক্ষের, না ইলখানির স্বীকৃতি পেতে পেরেছিল। মাসউদের সুলতানাত জুড়েই অঞ্চলটি কার্যত ইলখানি কর্মকর্তাদের শাসনে ছিল; তাঁর মৃত্যুতে এ সরাসরি শাসন কনিয়া, নিগদে ও আকসারায়ের মতো কেন্দ্রে আনুষ্ঠানিক আবরণও হারায়।", "80f4e444"]},
"OLAYLAR_EK16:1309-01-01:0":{"b": ["জান্দারোগুল্লারি বেইলিকের কাস্তামনু-চানকিরি-বার্তিন-সাফরানবোলুতে বিস্তার", "64e39ad0"], "d": ["টিডিভি (TDV)-র জান্দারোগুল্লারি নিবন্ধ অনুযায়ী বেইলিকটি চতুর্দশ শতকের শুরুতে কাস্তামনু-সিনোপ অঞ্চলে শামসুদ্দিন ইয়ামান জান্দার প্রতিষ্ঠা করেন, যাঁকে ইলখানি শাসক গেইখাতু এফলানি ও আশপাশ ইকতা হিসেবে দিয়েছিলেন; উৎসের অপ্রতুলতার কারণে প্রতিষ্ঠার সঠিক তারিখ জানা নেই। জান্দারের উত্তরসূরি সুলায়মান বেগ চোবানোগুল্লারি বেইলিকের স্থলাভিষিক্ত শাসক হিসেবে উল্লিখিত — অর্থাৎ কাস্তামনু ও চানকিরি অঞ্চল চোবানোগুল্লারি থেকে, বার্তিন-সাফরানবোলু-এফলানি রেখা ইলখানির সরাসরি শাসন থেকে জান্দারোগুল্লারির হাতে গেছে।", "72e44d66"]},
"OLAYLAR_EK16:1310-08-15:0":{"b": ["সেন্ট জন (হসপিটালার) নাইটদের রোডস ও দোদেকানিজ বিজয়", "67885b4b"], "d": ["টিডিভি (TDV)-র রোডস নিবন্ধ উল্লেখ করে যে দ্বীপটি 1309 সালে সেন্ট জন নাইটদের (হসপিটালার/ইসবিতারিয়ে) হাতে যায়; আদর্শ হসপিটালার ইতিহাস (দ্রষ্টব্য: J. Riley-Smith, The Knights Hospitaller) বিশদ করে যে অবরোধ 1306 সালের গ্রীষ্মে শুরু হয়, বাইজেন্টাইন সহায়তায় দীর্ঘ প্রতিরোধ করা রোডস শহর গ্র্যান্ড মাস্টার ফুলক দ্য ভিলারের বাহিনীর হাতে কেবল 15 আগস্ট 1310 তারিখে পতিত হয়। দ্বীপ এ তারিখ থেকে 1522 সালে অটোমান বিজয় পর্যন্ত নাইটদের কেন্দ্র থাকবে; আশপাশের দোদেকানিজ দ্বীপপুঞ্জও একই প্রক্রিয়ায় বাইজেন্টাইনদের থেকে হসপিটালার কর্তৃত্বে গেছে।", "c1422e2c"]},
"OLAYLAR_EK16:1313-01-01:0":{"b": ["লিভোনীয় নাইটরা লিথুয়ানিয়ার কাছ থেকে দ্যুনাবুর্গ দুর্গ ফিরিয়ে নিল", "92119516"], "d": ["লিথুয়ানীয়রা 1281 সালের কাছাকাছি সময়ে ইয়ের্সিকা দখল করে সেটি অর্ডারের দ্যুনাবুর্গ দুর্গের সঙ্গে বদল করেছিল। দুর্গটি 1313 সালে আবার লিভোনীয় নাইটদের হাতে আসে এবং অর্ডারের কমান্ডারি কেন্দ্র হিসেবে থেকে যায়।", "0cdd86e0"]},
"OLAYLAR_EK16:1315-01-01:0":{"b": ["ইস্তানকোয়ের (কস) সেন্ট জন নাইটদের দখল", "445666f7"], "d": ["টিডিভি (TDV)-র ইস্তানকোয় নিবন্ধ অনুযায়ী সেন্ট জন নাইটরা রোডসে বসতি করার পর ইস্তানকোয়ও দখল করে (1315) নতুন দুর্গ নির্মাণ করে। দ্বীপ এভাবে 1523 সাল পর্যন্ত চলা নাইট কর্তৃত্বে আসে; 1310 সালে রোডস শহরের পতনের পর কস কোন শাসনে ছিল তা টিডিভি-তে বিস্তারিত নেই।", "145d1bad"]},
"OLAYLAR_EK16:1325-01-01:0":{"b": ["মেট্রোপলিটন আসন মস্কোয় স্থানান্তরিত হলো", "d20099f8"], "d": ["রুশ অর্থোডক্স চার্চের প্রধান মেট্রোপলিটন পিওতর তাঁর ধর্মীয় কেন্দ্র মস্কোয় সরিয়ে নেন। এটি মস্কোর কেবল রাজনৈতিক নয়, ধর্মীয় কেন্দ্র হিসেবেও উত্থানের সূচনা ছিল এবং প্রিন্সিপালিটির বৈধতা জোরদার করে।", "4e31c42f"]},
"OLAYLAR_EK16:1330-01-01:0":{"b": ["লিভোনীয় অর্ডার রিগা শহরের অধিরাজ হলো", "21453047"], "d": ["লিথুয়ানিয়ার গ্র্যান্ড ডিউক ভিতেনিস ও গেদিমিনাসের সমর্থনে অর্ডারের বিরুদ্ধে লড়া রিগার আর্চবিশপ-এলাকা ও শহর 1330 সালে পরাজিত হয়; লিভোনীয় অর্ডার শহরের অধিরাজ হয়। 1452 সালের সালাসপিলস চুক্তির মাধ্যমে রিগা অর্ডার ও আর্চবিশপের যৌথ অধিরাজত্বের অধীনে যায়।", "28788282"]},
"OLAYLAR_EK16:1335-01-01:0":{"b": ["এরেতনা বেইলিকের প্রতিষ্ঠা — ইলখানি-পরবর্তী মধ্য আনাতোলিয়া", "a67bacd9"], "d": ["টিডিভি (TDV)-র এরেতনোগুল্লারি নিবন্ধ অনুযায়ী উইঘুর বংশোদ্ভূত ইলখানি কর্মকর্তা আলাউদ্দিন এরেতনা, ইলখানি শাসক আবু সাইদ বাহাদুর খানের 1335 সালে মৃত্যুর পর আনাতোলিয়ার ইলখানি নায়েবি পদকে কার্যত স্বাধীন শাসনে রূপান্তর করেন; প্রথমে মামলুক সুলতানের নায়েব পরিচয়ে দেখা দিয়ে 1340 সালে খুতবা থেকে মামলুকের নাম বাদ দেন এবং 1341 সালের কাছাকাছি পূর্ণ স্বাধীনতা ঘোষণা করেন। কেন্দ্র প্রথমে সিভাস, পরে কায়সেরি হওয়া এ বেইলিক মৃত্যু (1352) পর্যন্ত আমাসিয়া, তোকাত, চোরুম, নিগদে, আকসারায় ও এরজিনকান জুড়ে বিস্তৃত মধ্য আনাতোলীয় কর্তৃত্ব গড়ে তোলে এবং 1381 সালে কাজি বুরহানুদ্দিনের হাতে শেষ হয়।", "04978a80"]},
"OLAYLAR_EK16:1335-05-01:0":{"b": ["হ্যাবসবুর্গদের কার্নিওলা (লুব্লিয়ানা) ও কারিন্থিয়া দখল", "039918d3"], "d": ["কারিন্থিয়ার ডিউক ও টিরলের কাউন্ট ষষ্ঠ হাইনরিখ 1335 সালের 2 এপ্রিল টিরল দুর্গে উত্তরাধিকারী না রেখে মারা যান; 1330 সালের 23 নভেম্বর বাভারিয়ার লুডভিগের সঙ্গে গোপনে হওয়া চুক্তি অনুসারে হ্যাবসবুর্গ ভাই দ্বিতীয় আলব্রেখট ও চতুর্থ অটো সম্রাটের সনদের মাধ্যমে কারিন্থিয়া ডাচি এবং তার অধীন কার্নিওলা (বর্তমান লুব্লিয়ানা যে অঞ্চলের অন্তর্ভুক্ত) লাভ করেন; টিরল অবশ্য হাইনরিখের কন্যার মাধ্যমে পৃথক থেকে যায়। এটি ছিল আল্পস অঞ্চলে হ্যাবসবুর্গদের সম্প্রসারণের প্রথম বড় পদক্ষেপগুলোর একটি এবং কার্নিওলা 1918 সাল পর্যন্ত (মাঝে মাঝে ছেদসহ) হ্যাবসবুর্গ/অস্ট্রীয় হাতে থাকবে।", "4dbed85a"]},
"OLAYLAR_EK16:1340-01-01:0":{"b": ["জালায়িরি রাষ্ট্রের প্রতিষ্ঠা — ইলখানি-পরবর্তী আজারবাইজান", "a13ada90"], "d": ["টিডিভি (TDV)-র জালায়িরিলার নিবন্ধ অনুযায়ী ইলখানি আমির নোয়ানের নাতি হাসান-ই বুযুর্গ, ইলখানি শাসক আবু সাইদ বাহাদুর খানের মৃত্যুতে শুরু হওয়া সিংহাসন-দ্বন্দ্বের সুযোগ নিয়ে 1340 সালে তাব্রিজকেন্দ্রিক স্বাধীন রাষ্ট্র গড়েন। জালায়িরিরা এভাবে আজারবাইজান ও আশপাশে ইলখানি-পরবর্তী শূন্যতা পূরণকারী প্রথম বড় রাজবংশ হয়; উত্তরসূরি উয়াইসের আমলে (1356-1374) তাদের ভূমি মসুল ও দিয়ারবাকির পর্যন্ত বিস্তৃত হবে।", "224cbb81"]},
"OLAYLAR_EK16:1341-01-01:0":{"b": ["নিঝনি নভগোরদ-সুজদাল গ্র্যান্ড প্রিন্সিপালিটি প্রতিষ্ঠিত — খান কনস্তান্তিন ভাসিলিয়েভিচকে সনদ দিলেন", "c69f5198"], "d": ["গোল্ডেন হোর্ডের খান উজবেক (উজবেক/জানিবেক) সুজদালের রাজকুমার কনস্তান্তিন ভাসিলিয়েভিচকে নিঝনি নভগোরদ-গোরদেৎস প্রিন্সিপালিটি দেন; প্রিন্সিপালিটিটি মস্কোর প্রতিদ্বন্দ্বী হয় এবং 1392 সালে প্রথম ভাসিলির হাতে মস্কোর সঙ্গে যুক্ত হয়।", "fa1cfe3d"]},
"OLAYLAR_EK16:1346-01-01:0":{"b": ["ডেনমার্ক উত্তর এস্তোনিয়া (রেভাল ও নারভা) লিভোনীয় অর্ডারের কাছে বিক্রি করল", "6861ba55"], "d": ["ডেনমার্ক রাজ্য উত্তর এস্তোনিয়ার ভূমি রেভাল ও নারভাসহ লিভোনীয় অর্ডারের কাছে বিক্রি করে। অঞ্চলটি লিভোনীয় যুদ্ধ পর্যন্ত অর্ডারের হাতে ছিল।", "0723514c"]},
"OLAYLAR_EK16:1348-01-01:0":{"b": ["বোলোতোভো চুক্তি — নভগোরদ প্সকভের স্বাধীনতা স্বীকার করল", "08eca44d"], "d": ["নভগোরদ প্সকভকে 'ছোট ভাই' হিসেবে স্বীকৃতি দেয়; প্সকভ নিজস্ব ভেচে ও পসাদনিক নিয়ে স্বাধীন নগর-প্রজাতন্ত্র হিসেবে 1510 সালে মস্কোর সঙ্গে যুক্ত হওয়া পর্যন্ত টিকে ছিল।", "12f9ce2f"]},
"OLAYLAR_EK16:1392-01-01:0":{"b": ["প্রথম ভাসিলি নিঝনি নভগোরদ-সুজদাল প্রিন্সিপালিটি মস্কোর সঙ্গে যুক্ত করলেন", "5ecf441b"], "d": ["খান তোখতামিশের কাছ থেকে পাওয়া সনদে প্রথম ভাসিলি নিঝনি নভগোরদ, গোরদেৎস ও সুজদাল মস্কোর সঙ্গে যুক্ত করেন; ভলগা ও ওকা অববাহিকায় মস্কোর বিস্তার শুরু হয়।", "ac83ac55"]},
"OLAYLAR_EK16:1404-01-01:0":{"b": ["ভিতাউতাস স্মোলেনস্ক নিলেন — স্মোলেনস্ক প্রিন্সিপালিটি লিথুয়ানিয়ার সঙ্গে যুক্ত হলো", "1a68300c"], "d": ["ভিতাউতাস স্মোলেনস্ক দখল করেন; শহরটি 1514 সালে মস্কোর হাতে যাওয়া পর্যন্ত লিথুয়ানিয়ার গ্র্যান্ড ডাচিতে ছিল।", "3ed5ce14"]},
"OLAYLAR_EK16:1411-01-01:0":{"b": ["বাগদাদের কারাকোইউনলুর হাতে যাওয়া — জালায়িরি সুলতান আহমদের পরাজয়", "a42ebe92"], "d": ["টিডিভি (TDV)-র কারাকোইউনলুলার নিবন্ধ অনুযায়ী কারা ইউসুফ 28 রবিউস সানি 813 (30 আগস্ট 1410) তারিখে তাব্রিজের কাছে জালায়িরি সুলতান আহমদকে ভারী পরাজয়ে ফেলেন; সুলতান আহমদের মৃত্যুর পর 814 (1411) সালে তিনি নিজের পুত্র পির বুদাককে তাব্রিজে সুলতান ঘোষণা করেন এবং একই বছর তাঁর বড় ছেলে শাহ মেহমেদ বাগদাদ জয় করেন। এভাবে প্রায় এক শতক জালায়িরি রাজধানী থাকা বাগদাদ, আশপাশের বসরা-মসুল-কিরকুক রেখাসহ, কারাকোইউনলু কর্তৃত্বে আসে।", "30b86113"]},
"OLAYLAR_EK16:1422-01-01:0":{"b": ["এরজিনকান ও কেমাহ আকোইউনলুর হাতে গেল — কারাইউলুক ওসমান বেগ", "122460d4"], "d": ["কারা ইউসুফের মৃত্যুর পর এরজিনকানবাসীর ইচ্ছায় মুতাহহারতেনের নাতি ইয়ার আলি শহরের শাসক হয়েছিলেন। তাঁর সময়ে আকোইউনলু বেগ কারাইউলুক ওসমান এরজিনকান দখল করে আকোইউনলু ভূমির সঙ্গে যুক্ত করেন। এরপর থেকে এরজিনকান কখনো আকোইউনলু ও কারাকোইউনলুর মধ্যে, কখনো আকোইউনলু শাহজাদাদের মধ্যে হাতবদল হওয়া স্থান হয়ে ওঠে।", "83183da6"]},
"OLAYLAR_EK16:1438-01-01:0":{"b": ["কাজান খানাতের প্রতিষ্ঠা — উলুগ মুহাম্মদ খানের গোল্ডেন হোর্ড থেকে বিচ্ছেদ", "335a7408"], "d": ["টিডিভি (TDV)-র কাজান খানাত নিবন্ধ অনুযায়ী গোল্ডেন হোর্ডের রাজধানী সারায়ে সিংহাসন হারানো উলুগ মুহাম্মদ খান পরিবার ও প্রায় 3000 সৈন্য নিয়ে প্রথমে বেলেভে সরে যান, 1437-1438 সালে রুশ নেজ দ্বিতীয় ভাসিলির সঙ্গে লড়েন এবং এরপর কাজান শহরে বসতি করেন; স্থানীয় জনগণের সমর্থনে এখানে নতুন খানাতের ভিত্তি স্থাপন করেন। টিডিভি উল্লেখ করে যে প্রতিষ্ঠা-প্রক্রিয়া 1437-1445 সালের মধ্যে সম্পন্ন হয় এবং খানাত 1445 থেকে পূর্ণ স্বাধীন মর্যাদা লাভ করে — মানচিত্র এ প্রক্রিয়ার সূচনা, উলুগ মুহাম্মদের কাজানে বসতি স্থাপনের 1438 সালকে ভিত্তি ধরেছে।", "d65b36b3"]},
"OLAYLAR_EK16:1441-01-01:0":{"b": ["ক্রিমিয়ান খানাতের প্রতিষ্ঠা — হাজি গিরায়ের গোল্ডেন হোর্ড থেকে স্বাধীন হওয়া", "5728223e"], "d": ["টিডিভি (TDV)-র ক্রিম নিবন্ধ অনুযায়ী ক্রিমিয়ান খানাত চতুর্দশ শতকের দ্বিতীয়ার্ধে গোল্ডেন হোর্ডের সিংহাসন-দ্বন্দ্বে খণ্ডবিখণ্ড হওয়ার ফল হিসেবে আবির্ভূত হয়; খানাতের প্রকৃত প্রতিষ্ঠাতা হাজি গিরায়ের মুদ্রিত সবচেয়ে পুরোনো মুদ্রায় 845 (1441-42) তারিখ রয়েছে এবং এটিকে খানাতের আনুষ্ঠানিক প্রতিষ্ঠার তারিখ ধরা হয়। একই বছর হাজি গিরায় মস্কোর সঙ্গে বন্ধুত্ব গড়ে ক্রিমিয়ায় নিজের অবস্থান সুদৃঢ় করেন এবং শিরিন গোত্রসহ স্থানীয় বেগ পরিবারগুলো তাঁর পক্ষে যোগ দেয়।", "dbd052d0"]},
"OLAYLAR_EK16:1450-01-01:0":{"b": ["জাহান শাহ এরজিনকান দখল করলেন — কারাকোইউনলু কর্তৃত্ব", "0c928cc4"], "d": ["কারাকোইউনলু শাসক জাহান শাহ 854 (1450) সালে এরজিনকানে সেনা পাঠিয়ে শহরটি আকোইউনলুদের থেকে নেন। এ ক্ষতি আকোইউনলু বেগ জাহাঙ্গির মির্জা ও তাঁর ভাই হাসান বেগের (উজুন হাসান) মধ্যে বিচ্ছেদ ঘটায়।", "203c5c2e"]},
"OLAYLAR_EK16:1452-01-01:0":{"b": ["কারাকোইউনলু জাহান শাহের তৈমুরি ইরান (রে, ইসফাহান, ফারস, কিরমান) দখল", "c6fbb3f5"], "d": ["টিডিভি (TDV)-র কারাকোইউনলুলার নিবন্ধ অনুযায়ী কারাকোইউনলু শাসক জাহান শাহ, তৈমুরি শাহজাদাদের সিংহাসন-দ্বন্দ্বের সুযোগ নিয়ে 856-857 (1452-1453) সালে রে, ইসফাহান, ফারস ও কিরমান প্রদেশ নিজ শাসনে আনেন; এটি শাহরুখ মির্জার 1447 সালের মৃত্যুর পর শুরু হওয়া এবং সুলতানিয়া-কাজভিন সংযুক্তিতে সূচিত সম্প্রসারণ প্রক্রিয়ার চূড়ান্ত বিন্দু। তৈমুরিদের দক্ষিণ-মধ্য ইরানের ভূমি এভাবে কারাকোইউনলুর হাতে যায়; জাহান শাহের কর্তৃত্ব 1466 সালে আজারবাইজান, আররান, ইরাক-ই আজম, ইরাক-ই আরাব, ফারস, কিরমান ও পূর্ব আনাতোলিয়া জুড়ে বিস্তৃত হবে।", "3f6a6c37"]},
"OLAYLAR_EK16:1452-10-23:0":{"b": ["বোর্দো ইংল্যান্ড কর্তৃক পুনর্দখল — জন ট্যালবটের শেষ গাসকনি অভিযান", "01b2b7be"], "d": ["1451 সালে ফরাসিদের কাছে হারানো বোর্দো, জনগণ ফরাসি গ্যারিসনের বিরুদ্ধে বিদ্রোহ করে ফটক খুলে দিলে, বয়োবৃদ্ধ সেনাপতি জন ট্যালবটের নেতৃত্বাধীন ইংরেজ সেনার কাছে 22-23 অক্টোবর 1452 রাতে আত্মসমর্পণ করে; এটি শতবর্ষের যুদ্ধে গাসকনিতে ইংল্যান্ডের শেষ ও স্বল্পস্থায়ী বিজয় ছিল। বোর্দো এক বছর পর কাস্তিয়ঁ যুদ্ধের পর স্থায়ীভাবে ফ্রান্সে ফিরবে।", "f6945d27"]},
"OLAYLAR_EK16:1453-10-19:0":{"b": ["বোর্দোর স্থায়ীভাবে ফ্রান্সে প্রত্যাবর্তন — শত বর্ষের যুদ্ধের কার্যত সমাপ্তি", "b0a86f6c"], "d": ["1453 সালের 17 জুলাই কাস্তিয়ঁ যুদ্ধে জন ট্যালবটের মৃত্যু এবং তাঁর বাহিনীর বিলুপ্তির ফলে গ্যাসকনিতে ইংরেজ প্রতিরোধ ভেঙে পড়ে; অবরুদ্ধ বোর্দো 1453 সালের 19 অক্টোবর ফরাসি বাহিনীর কাছে আত্মসমর্পণ করে। এই আত্মসমর্পণকেই 116 বছরের শত বর্ষের যুদ্ধের কার্যত সমাপ্তির মুহূর্ত বলে গণ্য করা হয় (কোনো আনুষ্ঠানিক শান্তিচুক্তি কখনো স্বাক্ষরিত হয়নি) এবং এর ফলে ইউরোপ মহাদেশে ইংল্যান্ডের আধিপত্য ক্যালে শহর পর্যন্ত সংকুচিত হয়ে যায়।", "1c632d46"]},
"OLAYLAR_EK16:1457-01-01:0":{"b": ["উজুন হাসান এরজিনকান পুনরুদ্ধার করলেন — আবার আকোইউনলু", "550d010a"], "d": ["উজুন হাসান কারাকোইউনলুদের পরাজিত করে এরজিনকান আবার আকোইউনলু কর্তৃত্বে আনেন। শহর 1473 সালের ওতলুকবেলি যুদ্ধের পরও আকোইউনলু সীমানার মধ্যেই থাকে।", "d778fa85"]},
"OLAYLAR_EK16:1466-10-19:0":{"b": ["দ্বিতীয় থর্ন চুক্তি — দানজিগ (গদান্স্ক) ও পশ্চিম প্রুশিয়া পোল্যান্ডের অধীনে", "e2152dae"], "d": ["1454 সালে প্রুশীয় কনফেডারেশনের টিউটনিক নাইটদের শাসনের বিরুদ্ধে বিদ্রোহে শুরু হওয়া তেরো বছরের যুদ্ধ শেষ করা দ্বিতীয় থর্ন (তোরুন) চুক্তি 19 অক্টোবর 1466 তারিখে স্বাক্ষরিত হয়; নাইটরা দানজিগ (গদান্স্ক) সহ পূর্ব পোমেরানিয়া, এলবিং (এলব্লাগ) সহ ভিস্টুলা মোহনা এবং কুলম অঞ্চল পোল্যান্ড রাজ্যকে ছেড়ে দেয় — এ ভূমিগুলো ‘রয়্যাল প্রুশিয়া’ নাম পায়। পূর্ব প্রুশিয়া অবশ্য 1525 সাল পর্যন্ত নাইটদের হাতেই থাকবে।", "831685a9"]},
"OLAYLAR_EK16:1474-01-01:0":{"b": ["তৃতীয় ইভান রস্তভ প্রিন্সিপালিটির অবশিষ্ট অর্ধেক কিনে নিলেন", "5203244f"], "d": ["রস্তভের রাজকুমারদের হাতে থাকা অর্ধেক অংশ মস্কোকে হস্তান্তরিত হয়; 1332 সালে মস্কোর হাতে যাওয়া অন্য অর্ধেকের সঙ্গে রস্তভ ভূমি সম্পূর্ণরূপে মস্কোর সঙ্গে যুক্ত হয়।", "ab0eeae6"]},
"OLAYLAR_EK16:1485-09-12:0":{"b": ["তভের গ্র্যান্ড প্রিন্সিপালিটি মস্কোর সঙ্গে যুক্ত হলো — তৃতীয় ইভান শহর দখল করলেন", "fa3f924e"], "d": ["মস্কো বাহিনীর অবরোধের মুখে শেষ তভের গ্র্যান্ড প্রিন্স মিখাইল বরিসোভিচ লিথুয়ানিয়ায় পালিয়ে যান, তভের তৃতীয় ইভানের কাছে আত্মসমর্পণ করে; এভাবে মস্কোর সবচেয়ে শক্তিশালী প্রতিদ্বন্দ্বী বিলুপ্ত হয়।", "b9942526"]},
"OLAYLAR_EK16:1489-02-26:0":{"b": ["রানি কাতেরিনা কর্নারো সাইপ্রাস ভেনিসকে হস্তান্তর করলেন — ক্রুসেডার রাষ্ট্রের অবসান", "e24d3f3a"], "d": ["স্বামী রাজা দ্বিতীয় জ্যাকের 1473 সালে মৃত্যুর পর রানি-প্রতিনিধি হিসেবে সাইপ্রাস শাসন করা ভেনিসীয় কাতেরিনা কর্নারো, উত্তরাধিকারী না থাকায় ভেনিস সরকারের চাপে 26 ফেব্রুয়ারি 1489 তারিখে সিংহাসন ত্যাগ করে দ্বীপে তাঁর শাসনাধিকার ডোজ ও ভেনিস প্রজাতন্ত্রকে হস্তান্তর করেন; বিনিময়ে রানি উপাধি ধরে রাখেন এবং তেরাফেরমায় আসোলো কাউন্টি পান। এ হস্তান্তরে 1192 সাল থেকে চলা লুসিনিয়ান (লুজিনিয়ঁ) রাজবংশের কর্তৃত্ব ও শেষ ক্রুসেডার রাষ্ট্রের অবসান হয়, দ্বীপ 1570-71 সালের অটোমান বিজয় পর্যন্ত ভেনিসীয় শাসনে থাকে।", "7f769951"]},
"OLAYLAR_EK16:1492-01-02:0":{"b": ["গ্রানাডার পতন — ইবেরীয় উপদ্বীপে শেষ মুসলিম রাষ্ট্রের অবসান", "46e5201b"], "d": ["দশ বছরের ধাপে ধাপে অবরোধ ও অভ্যন্তরীণ বিভাজনে দুর্বল হওয়া গ্রানাডার নাসরি আমিরাতের শেষ শাসক আবু আবদুল্লাহ (বোয়াবদিল) নভেম্বর 1491 সালে স্বাক্ষরিত উদার আত্মসমর্পণ শর্ত (গ্রানাডা সমর্পণ চুক্তি) অনুযায়ী 2 জানুয়ারি 1492 তারিখে শহরের চাবি ক্যাথলিক রাজা ফের্নান্দো ও ইসাবেলার হাতে তুলে দেন; আলহামরা ছেড়ে যাওয়া বোয়াবদিলের পর ইবেরীয় উপদ্বীপের শেষ মুসলিম রাষ্ট্র শেষ হয় এবং রেকনকিস্তা সম্পূর্ণ হয়। একই বছর ইহুদিদের বহিষ্কার (মার্চ) ও ক্রিস্টোফার কলম্বাসের যাত্রা (আগস্ট) অনুসরণ করবে।", "5dc28ef8"]},
"OLAYLAR_EK16:1500-07-14:0":{"b": ["ভেদরোশা যুদ্ধ — মস্কো লিথুয়ানীয় বাহিনীকে পরাজিত করল; ব্রিয়ানস্ক ও সেভেরস্ক ভূমি মস্কোর হাতে থেকে গেল", "d3f61400"], "d": ["1500-1503 মস্কো-লিথুয়ানিয়া যুদ্ধে দানিল শেনিয়ার নেতৃত্বাধীন মস্কো বাহিনী দরোগোবুঝের কাছে ভেদরোশা নদীর তীরে হেটম্যান কনস্তান্তি অস্ত্রোগস্কির বাহিনীকে পরাস্ত করে এবং হেটম্যানকে বন্দী করে। একই বছরের বসন্তে দখল হওয়া ব্রিয়ানস্ক ও সেভেরস্ক শহর মস্কোর হাতেই থাকে; যুদ্ধের শেষে লিথুয়ানীয় ভূমির প্রায় এক-তৃতীয়াংশ মস্কোর কাছে চলে গিয়েছিল।", "e5879803"]},
"OLAYLAR_EK16:1507-05-24:0":{"b": ["শাইবানি খানের তৈমুরিদের থেকে হেরাত ও খোরাসান দখল", "a81d8575"], "d": ["টিডিভি (TDV)-র শাইবানি খান নিবন্ধ অনুযায়ী উজবেক শাসক শাইবানি খান 1503-1505 সালে আন্দিজান, ফারগানা, হিসার, কুন্দুজ ও বলখ নেওয়ার পর 913 (1507) সালে তৈমুরি রাজধানী হেরাতও দখল করেন; Encyclopaedia Iranica-র খোরাসান নিবন্ধ এ বিজয়ের সঠিক তারিখ দেয় — শহর 8 মুহাররম 913 (20 মে 1507) তারিখে পতিত হয়, এক সপ্তাহ পর 15 মুহাররম (27 মে) খুতবা শাইবানি খানের নামে পড়ে বিজয় আনুষ্ঠানিক হয়। মাশহাদ সহ সমগ্র খোরাসান একই বছরে তৈমুরিদের থেকে শাইবানিদের হাতে যায়; এর অর্থ তৈমুরি রাজবংশ মাওয়ারাউন্নাহারের পর ইরানে তার শেষ বড় দুর্গও হারায়।", "cb60730c"]},
"OLAYLAR_EK16:1509-05-17:0":{"b": ["ওরানের স্পেনের হাতে পতন — কার্ডিনাল সিসনেরোসের উত্তর আফ্রিকা অভিযান", "86ed8ac1"], "d": ["পশ্চিম ভূমধ্যসাগরের জলপথ নিয়ন্ত্রণকারী ও তিলিমসানের বন্দর ওয়াহরান (ওরান) 1492 সালে গ্রানাডা থেকে পালানো আন্দালুসীয় মুসলিম ও ইহুদিদের আশ্রয়ে বেড়ে উঠেছিল। ষোড়শ শতকের শুরুতে মাগরিব উপকূলের বন্দর শহরগুলো একে একে দখল করা কাস্তিল রাজ্য 17 মে 1509 তারিখে ওয়াহরান দখল করে; জনগণের বড় অংশ নিহত হয়, বাকিরা বন্দি হয় এবং শহরে মুসলিম ও ইহুদি জনসংখ্যা থাকেনি। স্পেনীয়রা প্রাচীর ও দুর্গ সম্প্রসারণ করে; ওয়াহরান 1708 সাল পর্যন্ত স্পেনের হাতে থাকে।", "be7b3b1b"]},
"OLAYLAR_EK16:1514-08-01:0":{"b": ["স্মোলেনস্ক মস্কোর কাছে আত্মসমর্পণ করল — তৃতীয় ভাসিলি শহরে প্রবেশ করলেন", "46c61446"], "d": ["1512-1522 মস্কো-লিথুয়ানিয়া যুদ্ধের তৃতীয় অবরোধে লিথুয়ানীয় গ্যারিসন 31 জুলাই আত্মসমর্পণ করে; মস্কোর বাহিনী 1 আগস্ট আনুষ্ঠানিকভাবে শহরে প্রবেশ করে এবং জনগণ তৃতীয় ভাসিলির প্রতি আনুগত্যের শপথ নেয়। স্মোলেনস্ক ভাসিলির পশ্চিমে সবচেয়ে বড় অর্জন; কয়েক সপ্তাহ পর অরশায় ঘটা পরাজয় শহরটি ফিরিয়ে দেয়নি।", "803c9255"]},
"OLAYLAR_EK16:1516-01-23:0":{"b": ["নিম্নভূমির স্পেনীয় মুকুটের অধীন হওয়া — ফের্দিনান্দের মৃত্যু, পঞ্চম চার্লসের সিংহাসনারোহণ", "fbe0dbd2"], "d": ["আরাগনের রাজা দ্বিতীয় ফের্দিনান্দের 23 জানুয়ারি 1516 তারিখে মৃত্যুতে, 1506 সাল থেকে বার্গান্ডির ডিউক হিসেবে নিম্নভূমি (বর্তমান বেলজিয়াম-নেদারল্যান্ডস-লুক্সেমবার্গ ও উত্তর ফ্রান্সের কিছু অংশ) শাসন করা তাঁর নাতি পঞ্চম চার্লস কাস্তিল ও আরাগনের সিংহাসনেরও উত্তরাধিকারী হন এবং 14 মার্চ 1516 তারিখে ব্রাসেলসে স্পেনের রাজা ঘোষিত হন। এভাবে এ ভূমিগুলো ব্যক্তিগত ঐক্যের মাধ্যমে হাবসবুর্গ রাজবংশের জার্মান/অস্ট্রীয় শাখার নয়, সরাসরি স্পেনীয় মুকুটের অধীন গণ্য হতে থাকে — 1519 সালে চার্লসের পবিত্র রোমান সম্রাট নির্বাচনে এ দুই পরিচয় (স্পেনের রাজা ও জার্মান-রোমান সম্রাট) একই ব্যক্তিতে মিলবে, অঞ্চলের স্পেনের সঙ্গে সংযুক্তি 1556 সালে চার্লসের সিংহাসন ত্যাগ করে উত্তরাধিকার পুত্র দ্বিতীয় ফিলিপকে দেওয়া পর্যন্ত চলবে।", "61f77359"]},
"OLAYLAR_EK16:1527-01-01:0":{"b": ["দেমাক সুলতানাতের মাজাপাহিত ধ্বংস ও জাভা উপকূলে কর্তৃত্ব", "7da602b5"], "d": ["টিডিভি (TDV)-র দেমাক নিবন্ধ অনুযায়ী জাভার প্রথম স্বাধীন মুসলিম রাষ্ট্র দেমাক সুলতানাত পঞ্চদশ শতকের শেষ চতুর্থাংশে রাদেন পাতাহ প্রতিষ্ঠা করেন; জাভানি উৎস অনুসারে পতনোন্মুখ হিন্দু-বৌদ্ধ মাজাপাহিত রাজ্য দেমাকের আক্রমণে বিলুপ্ত হয়। 1527 সালে দেমাক তুবান জয় করে, চীনা উৎসে যা একাদশ শতক থেকে মাজাপাহিত শাসকদের গুরুত্বপূর্ণ বন্দর হিসেবে উল্লিখিত — এটি মাজাপাহিতের শেষ অবশেষও দেমাকের অধীন হওয়ার বছর এবং জাভার বৃহৎ অংশের ইসলামিকরণ প্রক্রিয়ার মোড়।", "538d28fb"]},
"OLAYLAR_EK16:1537-01-01:0":{"b": ["নরওয়েকে ডেনমার্কের মুকুটের অধীন প্রদেশে পরিণত করা", "8e2f274e"], "d": ["ডেনমার্কের রাজা তৃতীয় ক্রিস্টিয়ান 1536 সালের রাজ্যাভিষেক সনদে (håndfæstning) ঘোষণা করেন যে নরওয়ে আর আলাদা রাজ্য গণ্য হবে না, ডেনমার্কের একটি প্রদেশ হিসেবে শাসিত হবে এবং নরওয়ের রাজ্য পরিষদ (riksråd) বিলুপ্ত; এ সিদ্ধান্ত 1537 সালে ডেনিশ চার্চ বিধি নরওয়েতেও প্রয়োগ হওয়ায় কার্যকর হয় এবং বিশপ ওলাভ এঙ্গেলব্রিক্টসনের প্রতিরোধ ভেঙে যায়। নরওয়ে বাস্তবে আরও কিছুকাল নিজের আইন ও প্রতিষ্ঠান ধরে রাখলেও তার রাজনৈতিক মর্যাদা আর স্বাধীন রাজ্য নয়, ডেনমার্কের মুকুটের অধীন প্রদেশ ছিল — এ অবস্থা 1814 পর্যন্ত চলবে।", "a8c9dee7"]},
"OLAYLAR_EK16:1558-05-01:0":{"b": ["নারভা রুশদের হাতে দখল — লিভোনীয় যুদ্ধের প্রথম বড় শহর", "c21130d7"], "d": ["চতুর্থ ইভানের বাহিনী নারভা দখল করে; রাশিয়া বাল্টিক উপকূলে পৌঁছায়। নারভা 1581 সালে সুইডেনের হাতে যাওয়া পর্যন্ত রুশ হাতে ছিল।", "8057148b"]},
"OLAYLAR_EK16:1558-07-01:0":{"b": ["দর্পাত (তার্তু) রুশদের হাতে দখল", "f941a504"], "d": ["রুশ বাহিনী 1558 সালের গ্রীষ্মকালীন অভিযানে দর্পাত (তার্তু) ও আশপাশের দুর্গ দখল করে; শহর 1582 সালের ইয়াম জাপোলস্কি যুদ্ধবিরতি পর্যন্ত রুশ শাসনে ছিল।", "35503ef9"]},
"OLAYLAR_EK16:1561-06-01:0":{"b": ["রেভাল (তালিন) সুইডেনের আশ্রয়ে গেল — উত্তর এস্তোনিয়া সুইডেনের হলো", "3c183267"], "d": ["লিভোনীয় কনফেডারেশন ভেঙে পড়ার সময় রেভাল শহর পরিষদ 1561 সালে সুইডেনের রাজা চতুর্দশ এরিকের প্রতি আনুগত্য জানায়; উত্তর এস্তোনিয়া মহান উত্তর যুদ্ধ (1721) পর্যন্ত সুইডেনের অধীনে থাকে।", "cb752659"]},
"OLAYLAR_EK16:1561-11-28:0":{"b": ["ভিলনিয়ুস চুক্তি — লিভোনীয় কনফেডারেশন বিলুপ্ত, কুরল্যান্ড ও লিভোনিয়া পোল্যান্ড-লিথুয়ানিয়ার অধীনে (রিগা শহর বাদে)", "d1ceaad5"], "d": ["লিভোনীয় যুদ্ধে রুশ চাপে ভেঙে পড়া লিভোনীয় কনফেডারেশনের শেষ গ্র্যান্ড মাস্টার গটহার্ড কেটলার 28 নভেম্বর 1561 তারিখে ভিলনিয়ুসে স্বাক্ষরিত চুক্তিতে (Pacta Subiectionis) লিথুয়ানিয়ার গ্র্যান্ড ডিউক ও পোল্যান্ডের রাজা দ্বিতীয় সিগিসমুন্ড আউগুস্টের আশ্রয়ে আসেন; রিগা শহর বাদে লিভোনিয়ার বড় অংশ পোল্যান্ড-লিথুয়ানিয়ার সঙ্গে যুক্ত হয়, কেটলার কুরল্যান্ড ডাচির প্রথম ডিউক হন। এটি লিভোনীয় নাইট সংঘের মধ্যযুগ থেকে আধুনিক যুগে উত্তরণের শেষ দৃশ্য ছিল।", "bcd4efe9"]},
"OLAYLAR_EK16:1581-01-01:0":{"b": ["সুইডেন রাশিয়ার কাছ থেকে নারভা নিল", "5a7f7a6a"], "d": ["লিভোনীয় যুদ্ধের শেষ বছরগুলোতে সুইডিশ বাহিনী 1558 সাল থেকে রুশ হাতে থাকা নারভা দখল করে; শহরটি 1704 সাল পর্যন্ত সুইডেনের অধীনে ছিল।", "5fee4227"]},
"OLAYLAR_EK16:1581-01-01:1":{"b": ["মুক্ত শহর রিগা পোল্যান্ড-লিথুয়ানিয়ার সঙ্গে যুক্ত হলো", "77dba329"], "d": ["লিভোনীয় যুদ্ধের পুরো সময় মুক্ত শহর হিসেবে থাকা রিগা 1581 সালে পোল্যান্ড-লিথুয়ানিয়া কমনওয়েলথের সঙ্গে যুক্ত হয়; শহরটি 1621 সালে সুইডেনের হাতে যাওয়া পর্যন্ত কমনওয়েলথে ছিল।", "ecdf652d"]},
"OLAYLAR_EK16:1581-07-26:0":{"b": ["পরিত্যাগ ঘোষণা (Plakkaat van Verlatinghe) — নেদারল্যান্ডসের স্পেন থেকে স্বাধীনতা ঘোষণা", "a632aaee"], "d": ["আশি বছরের যুদ্ধ চলাকালে ইউট্রেখট ইউনিয়নের অন্তর্ভুক্ত ডাচ প্রদেশগুলোর সাধারণ পরিষদ (Staten-Generaal) 26 জুলাই 1581 তারিখে গৃহীত পরিত্যাগ ঘোষণায় স্পেনের রাজা দ্বিতীয় ফিলিপকে ‘অত্যাচারী’ ঘোষণা করে তাঁর প্রতি আনুগত্য অস্বীকার করে; এ দলিল কার্যত স্বাধীন সংযুক্ত প্রদেশগুলোর (ডাচ প্রজাতন্ত্র) প্রতিষ্ঠা-ঘোষণা গণ্য হয়। স্পেনের চূড়ান্ত স্বীকৃতি 1648 সালের ওয়েস্টফালিয়া পর্যন্ত অপেক্ষা করতে হবে, কিন্তু প্রকৃত বিচ্ছেদ এ দিনেই।", "cd96ed5f"]},
"OLAYLAR_EK16:1611-06-13:0":{"b": ["স্মোলেনস্কের পোল্যান্ড-লিথুয়ানিয়ার হাতে পতন — 20 মাসের অবরোধের সমাপ্তি", "4e9678e3"], "d": ["দুর্যোগকালে (স্মুতা) পোল্যান্ডের রাজা তৃতীয় সিগিসমুন্ডের সেনা, সেপ্টেম্বর 1609 থেকে অবরুদ্ধ স্মোলেনস্কের প্রাচীরে 13 জুন 1611 তারিখে সুড়ঙ্গ বিস্ফোরণে ফাটল ধরিয়ে শহর দখল করে; 20 মাসের প্রতিরোধ শেষ হয়। স্মোলেনস্ক 1654 সাল পর্যন্ত পোল্যান্ড-লিথুয়ানিয়ায় থাকে এবং এ পতন সাত বছর পর স্বাক্ষরিত দেউলিনো যুদ্ধবিরতির (1618) ভিত্তি তৈরি করে।", "25d6488d"]},
"OLAYLAR_EK16:1611-07-16:0":{"b": ["নভগোরদ সুইডিশ বাহিনীর হাতে দখল — দুর্যোগকালে উত্তর-পশ্চিম রাশিয়া সুইডিশ নিয়ন্ত্রণে গেল", "a8ab28bb"], "d": ["ইয়াকোব দে লা গার্দির সুইডিশ বাহিনী নভগোরদ দখল করে; শহর 1617 সাল পর্যন্ত সুইডিশ আশ্রয়ে থাকা 'নভগোরদ রাষ্ট্রের' রাজধানী হয়, কার্ল ফিলিপকে জার-প্রার্থী হিসেবে দেখানো হয়।", "281592c2"]},
"OLAYLAR_EK16:1617-03-09:0":{"b": ["স্তলবোভা চুক্তি — রাশিয়া বাল্টিক উপকূল (ইংগ্রিয়া) সুইডেনের কাছে হারাল", "175dc175"], "d": ["ইংগ্রিয়ান যুদ্ধ শেষ করা স্তলবোভা চুক্তি 27 ফেব্রুয়ারি 1617 তারিখে লাদোগা হ্রদের দক্ষিণের স্তলবোভা গ্রামে স্বাক্ষরিত হয়; রাশিয়া নভগোরোদ ও উত্তরের অন্যান্য ভূমি ফিরে পেলেও সুইডেন কারেলিয়া ও ইংগ্রিয়া (এস্তোনিয়া-ফিনল্যান্ডের মাঝে, ইভাঙ্গোরোদ-ইয়াম-কোপোরিয়ে-ওরেশেক দুর্গ সহ) ধরে রাখে এবং রাশিয়ার বাল্টিকে সরাসরি উপকূল কেটে যায়। এ বিচ্ছেদ 1703 সালে মহান পিটারের একই অঞ্চলে সেন্ট পিটার্সবার্গ প্রতিষ্ঠা পর্যন্ত চলবে।", "7e70e3e6"]},
"OLAYLAR_EK16:1617-03-09:1":{"b": ["স্তলবোভো চুক্তি — রাশিয়া ইনগারম্যানল্যান্ড সুইডেনকে ছেড়ে দিল, নভগোরদ ফিরিয়ে দেওয়া হলো", "e0bcbc7a"], "d": ["রাশিয়া নেভা তীর ও কারেলিয়ার একাংশ (ইয়াম, কোপোরিয়ে, ইভানগোরদ, ওরেশেক) সুইডেনকে ছেড়ে দেয় এবং বাল্টিক উপকূল থেকে বিচ্ছিন্ন হয়; সুইডেন নভগোরদ ফিরিয়ে দেয়। এই অবস্থা প্রথম পিওতরের মহান উত্তর যুদ্ধ পর্যন্ত চলে।", "bf517525"]},
"OLAYLAR_EK16:1618-12-11:0":{"b": ["দেউলিনো যুদ্ধবিরতি — স্মোলেনস্ক, চের্নিগভ ও নভগোরোদ-সেভেরস্কি পোল্যান্ডকে ছেড়ে দেওয়া", "6880d2c1"], "d": ["1609-1618 সালের পোলিশ-রুশ যুদ্ধ শেষ করা দেউলিনো যুদ্ধবিরতি 11 ডিসেম্বর 1618 তারিখে স্বাক্ষরিত হয় এবং সাড়ে 14 বছরের যুদ্ধবিরতি নিশ্চিত করে; রাশিয়া স্মোলেনস্ক (ভিয়াজমা বাদে) এবং চের্নিগভ ও নভগোরোদ-সেভেরস্কি অঞ্চলের 29টি শহর পোল্যান্ড-লিথুয়ানিয়া ইউনিয়নকে ছেড়ে দিতে বাধ্য হয় — এটি দুর্যোগকালের (স্মুতা) সবচেয়ে ভারী ভূমিক্ষতি। অঞ্চলটি 1667 সালের আন্দ্রুসোভো যুদ্ধবিরতি পর্যন্ত পোল্যান্ডে থাকবে।", "5c52de5a"]},
"OLAYLAR_EK16:1625-01-01:0":{"b": ["সুইডেন পোল্যান্ডের কাছ থেকে তার্তু (দর্পাত) নিল — লিভোনীয় অভিযানের দ্বিতীয় পর্যায়", "46b7c86a"], "d": ["দ্বিতীয় গুস্তাফ আডলফ 1625 সালের অভিযানে দক্ষিণ এস্তোনিয়া ও উত্তর লিভোনিয়া জয় করেন; তার্তু এমন একটি সুইডিশ শহর হয় যেখানে 1632 সালে গুস্তাফ আডলফ একাডেমি প্রতিষ্ঠিত হবে।", "b58d9bd1"]},
"OLAYLAR_EK16:1654-01-18:0":{"b": ["পেরেয়াসলাভ পরিষদ — জাপোরোজীয় কসাকরা রুশ জারের প্রতি আনুগত্যের শপথ নিল", "bcd8f8ef"], "d": ["1648 সাল থেকে পোল্যান্ড-লিথুয়ানিয়ার বিরুদ্ধে বিদ্রোহী জাপোরোজীয় কসাকদের হেটম্যান বোহদান খমেলনিৎস্কি মস্কো থেকে ভাসিলি বুতুর্লিনের নেতৃত্বে আসা প্রতিনিধিদলের উপস্থিতিতে 18 জানুয়ারি 1654 (জুলিয়ান 8 জানুয়ারি) তারিখের পেরেয়াসলাভ পরিষদে জার প্রথম আলেক্সি মিখাইলোভিচের প্রতি আনুগত্যের শপথ নেন; এটি ইউক্রেনীয় কসাক হেটম্যানাতের রুশ আশ্রয়ে আসার সূচনা গণ্য হয় এবং চের্নিগভ-সেভেরস্ক অঞ্চলের কার্যত নিয়ন্ত্রণ পোল্যান্ড থেকে রাশিয়ার দিকে সরিয়ে দেয় — আনুষ্ঠানিক সীমানা অবশ্য 1667 সালের আন্দ্রুসোভো যুদ্ধবিরতিতে আঁকা হবে।", "b15d1501"]},
"OLAYLAR_EK16:1654-10-03:0":{"b": ["স্মোলেনস্ক রাশিয়া কর্তৃক পুনরুদ্ধার", "bf0eca92"], "d": ["1654 সালে শুরু হওয়া পোলিশ-রুশ যুদ্ধে রুশ সেনা জুলাই থেকে অবরুদ্ধ স্মোলেনস্ক 3 অক্টোবর 1654 তারিখে পোলিশ গ্যারিসনের আত্মসমর্পণে পুনরুদ্ধার করে; 1611 সালে পোল্যান্ডের কাছে হারানো শহর 43 বছর পর রাশিয়ায় ফেরে। এটি রাশিয়ার দুর্যোগকালের ক্ষতি পাল্টে দেওয়ার প্রক্রিয়ার সবচেয়ে গুরুত্বপূর্ণ পদক্ষেপগুলোর একটি এবং 1667 সালের আন্দ্রুসোভো যুদ্ধবিরতিতে স্থায়ী হয়।", "57ca40e6"]},
"OLAYLAR_EK16:1667-02-09:0":{"b": ["আন্দ্রুসোভো যুদ্ধবিরতি — কিয়েভ ও বাম-তীর ইউক্রেন রাশিয়ার হাতে গেল", "799be067"], "d": ["1654-1667 সালের পোলিশ-রুশ যুদ্ধ শেষ করা আন্দ্রুসোভো যুদ্ধবিরতি সাড়ে 13 বছরের যুদ্ধবিরতি নিশ্চিত করে; রাশিয়া স্মোলেনস্ক, চের্নিগভ-সেভেরস্ক অঞ্চল এবং দনিপ্রোর বাম তীরের ইউক্রেন এবং — শুরুতে দুই বছরের জন্য, বাস্তবে স্থায়ীভাবে — কিয়েভ শহর লাভ করে। এ চুক্তি দনিপ্রো বরাবর ইউক্রেনীয় ভূমির পোল্যান্ড ও রাশিয়ার মধ্যে বিভাজনের (এবং কিয়েভের রাশিয়ায় থেকে যাওয়ার) আইনি ভিত্তি স্থাপন করে।", "94445e3a"]},
"OLAYLAR_EK16:1702-10-22:0":{"b": ["রাশিয়া সুইডেনের কাছ থেকে নোটেবুর্গ (ওরেশেক) নিল — মহান উত্তর যুদ্ধের প্রথম নেভা দুর্গ", "28d180eb"], "d": ["প্রথম পিওতরের বাহিনী লাদোগার মুখের নোটেবুর্গ (রুশ ভাষায় ওরেশেক) অবরোধ করে দখল করে এবং নাম দেয় শ্লিসেলবুর্গ ('চাবি-দুর্গ'); এটি নেভায় এবং 1703 সালে সেন্ট পিটার্সবার্গ প্রতিষ্ঠার পথ খুলে দেয়।", "3017c2be"]},
"OLAYLAR_EK16:1703-05-27:0":{"b": ["সেন্ট পিটার্সবার্গের প্রতিষ্ঠা — পশ্চিমের দিকে রাশিয়ার জানালা", "ba196be0"], "d": ["মহান উত্তরের যুদ্ধ চলাকালে সুইডেন থেকে সদ্য পুনরুদ্ধার করা নেভা ব-দ্বীপের খরগোশ দ্বীপে মহান পিটার 16/27 মে 1703 তারিখে পেত্রোপাভলভস্ক দুর্গের (পিটার-পাউল দুর্গ) ভিত্তি স্থাপন করেন; এ দিনটি সেন্ট পিটার্সবার্গ শহরের প্রতিষ্ঠা-তারিখ গণ্য হয়। পিটার জলাভূমির ব-দ্বীপকে পশ্চিমের ‘জানালা’ হিসেবে কল্পনা করেন এবং শহর 1712 সালে রাশিয়ার নতুন রাজধানী হয় — অঞ্চলটি আনুষ্ঠানিকভাবে 1721 সালের নিস্টাড চুক্তিতে রাশিয়ার সঙ্গে যুক্ত হবে।", "24c24aaf"]},
"OLAYLAR_EK16:1708-09-29:0":{"b": ["ইংরেজ-ডাচ বাহিনীর হাতে মেনোর্কা দখল", "3ca66a83"], "d": ["স্পেনীয় উত্তরাধিকার যুদ্ধের সময় অস্ট্রিয়ার আর্চডিউক ষষ্ঠ কার্লের মিত্র হিসেবে কাজ করা ইংরেজ-ডাচ বাহিনী জেনারেল জেমস স্ট্যানহোপের নেতৃত্বে 1708 সালের 14 সেপ্টেম্বর দ্বীপে অবতরণ করে এবং 28-29 সেপ্টেম্বর স্পেনীয় প্রতিরক্ষা ভেঙে মেনোর্কার নিয়ন্ত্রণ নেয় (প্রধান দুর্গ ফোর্ট সেন্ট ফিলিপের আনুষ্ঠানিক আত্মসমর্পণ হয় 24 নভেম্বরে)। মেনোর্কার কৌশলগত বন্দর মাহোন পরবর্তী এক শতক ধরে ইংরেজ-ফরাসি-স্পেনীয় প্রতিদ্বন্দ্বিতার কেন্দ্রবিন্দু হয়ে থাকবে।", "9188937e"]},
"OLAYLAR_EK16:1714-03-07:0":{"b": ["রাস্টাট চুক্তি — স্পেনীয় উত্তরাধিকার যুদ্ধের অবসান, স্পেনীয় নেদারল্যান্ডস ও মিলান অস্ট্রিয়ার হাতে", "3c0e086f"], "d": ["স্পেনীয় উত্তরাধিকার যুদ্ধ ফ্রান্স ও অস্ট্রিয়ার মধ্যে শেষ করা রাস্টাট চুক্তি 7 মার্চ 1714 তারিখে স্বাক্ষরিত হয় (ইউট্রেখট 1713 সালে ইংল্যান্ড-ফ্রান্সের মধ্যে বিষয়টি মিটিয়েছিল); চুক্তিতে অস্ট্রীয় হাবসবুর্গরা স্পেনীয় নেদারল্যান্ডস (বর্তমান বেলজিয়াম) এবং ইতালির নেপলস, মিলান ও সার্ডিনিয়া লাভ করে। এটি অস্ট্রিয়ার ইতিহাসে সবচেয়ে বিস্তৃত ভূমি সম্প্রসারণ ছিল এবং মধ্য ইউরোপে হাবসবুর্গ রাজবংশের ভারের সঙ্গে পশ্চিম ও দক্ষিণ ইউরোপে নতুন একটি ফ্রন্ট যোগ করে।", "b27fb416"]},
"OLAYLAR_EK16:1721-09-10:0":{"b": ["নিস্টাড চুক্তি — মহান উত্তরের যুদ্ধের অবসান, বাল্টিক উপকূল রাশিয়ার হাতে", "068ffd06"], "d": ["21 বছর চলা মহান উত্তরের যুদ্ধ শেষ করা নিস্টাড চুক্তি 10 সেপ্টেম্বর 1721 তারিখে (জুলিয়ান 30 আগস্ট) ফিনল্যান্ডে স্বাক্ষরিত হয়; সুইডেন রাশিয়াকে এস্তোনিয়া, লিভোনিয়া (রিগা সহ), ইংগ্রিয়া এবং দক্ষিণ-পূর্ব ফিনল্যান্ডের (কারেলিয়া) একাংশ ছেড়ে দেয়, বিনিময়ে ফিনল্যান্ডের বাকি অংশ ফেরত পায় এবং ক্ষতিপূরণ দেওয়া হয়। চুক্তিটি সুইডেনের বৃহৎ শক্তির মর্যাদার অবসান এবং ইউরোপীয় সাম্রাজ্য হিসেবে রাশিয়ার উত্থানের আনুষ্ঠানিক স্বীকৃতি গণ্য হয় — প্রথম পিটার এ বিজয়ের পর ‘সম্রাট’ উপাধি নেন।", "f0c4fc4a"]},
"OLAYLAR_EK16:1793-01-23:0":{"b": ["পোল্যান্ডের দ্বিতীয় বিভাজন — রাশিয়া ও প্রুশিয়ার কাছে ভূমি হারানো", "31750484"], "d": ["1791 সালের সাংবিধানিক সংস্কার রাশিয়া ও প্রুশিয়াকে উদ্বিগ্ন করলে, দুই রাষ্ট্র 23 জানুয়ারি 1793 তারিখে সেন্ট পিটার্সবার্গে স্বাক্ষরিত চুক্তিতে পোল্যান্ড আবার ভাগ করে: রাশিয়া লিথুয়ানিয়া-বেলারুশের বড় অংশ ও পশ্চিম ইউক্রেন (কামেনেৎস, বার, মিনস্ক সহ) নেয়, প্রুশিয়া দানজিগ ও পোজনানসহ মহাপোল্যান্ড সংযুক্ত করে — মোট 307,000 বর্গকিলোমিটার। চাপের মুখে থাকা পোলিশ সেইম একই বছর চুক্তি অনুমোদন করতে বাধ্য হয়; এটি পোল্যান্ডের পূর্ণ সংযুক্তি দুই বছর পিছিয়ে দেওয়া স্বল্পস্থায়ী বিভাজন ছিল। এ দিনে (23 জানুয়ারি 1793) পোল্যান্ডের দ্বিতীয় বিভাজনে বেরদিচেভ, ফাস্তভ, জিতোমির, কানিভ, কন্সতান্তিনভ, উমান ও চেরকাসি সহ ডান-তীর ইউক্রেন রাশিয়ার হাতে যায়।", "656e71c2"]},
"OLAYLAR_EK16:1795-03-28:0":{"b": ["কুরল্যান্ড ও সেমিগালিয়া ডাচি রাশিয়ার সঙ্গে যুক্ত হলো — শেষ ডিউক পেটার ফন বিরন ক্ষমতা ছাড়লেন", "8d0e410f"], "d": ["তৃতীয় পোলিশ বিভাজনের প্রক্রিয়ায় কুরল্যান্ডের অভিজাতরা (দ্বিতীয়) ইয়েকাতেরিনার প্রতি আনুগত্য জানান, ডিউক পেটার ফন বিরন সিংহাসন ত্যাগ করেন; কুরল্যান্ড রাশিয়ার একটি গুবের্নিয়া হয় (সূত্রে 24 অক্টোবর 1795-এর কথাও পাওয়া যায়)।", "4682774b"]},
"OLAYLAR_EK16:1797-06-14:0":{"b": ["জেনোয়া প্রজাতন্ত্রের অবসান — নেপোলিয়ন লিগুরীয় প্রজাতন্ত্র গঠন করলেন", "3d3e59ee"], "d": ["ইতালি অভিযানে নেপোলিয়নের চাপে জুন 1797-এর শুরুতে অস্থায়ী প্রশাসনের হাতে দেওয়া জেনোয়া প্রজাতন্ত্রের স্থলে 14 জুন 1797 তারিখে ফরাসি আদলের সংবিধানসহ ‘লিগুরীয় প্রজাতন্ত্র’ ঘোষিত হয়; শতাব্দীপ্রাচীন জেনোয়া রাষ্ট্র কার্যত ফ্রান্সের একটি আশ্রিত রাষ্ট্রে পরিণত হয়। প্রজাতন্ত্র 1805 সালে সরাসরি ফ্রান্সের সঙ্গে সংযুক্ত হবে, 1815 সালের ভিয়েনা কংগ্রেসে সার্ডিনিয়া-পিডমন্ট রাজ্যকে দেওয়া হবে।", "38af1e4b"]},
"OLAYLAR_EK16:1797-10-17:0":{"b": ["কাম্পো ফর্মিওর চুক্তি — ভেনিসের অস্ট্রিয়া ও ফ্রান্সের মধ্যে বণ্টন", "9f29678c"], "d": ["নেপোলিয়ন বোনাপার্ট ও অস্ট্রীয় প্রতিনিধি কাউন্ট কোবেনৎসলের মধ্যে 17 অক্টোবর 1797 তারিখে স্বাক্ষরিত কাম্পো ফর্মিওর চুক্তি হাজার বছরের ভেনিস প্রজাতন্ত্রকে আনুষ্ঠানিকভাবে বিলুপ্ত করে এবং তার ভূমি ভাগ করে দেয়: আদিজে নদীর পূর্ব, ইস্ট্রিয়া ও দালমাশিয়া উপকূল (স্প্লিট, জাদার, শিবেনিক, কোতোর সহ) অস্ট্রিয়াকে দেওয়া হয়, আয়োনীয় দ্বীপপুঞ্জ (কর্ফু, কেফালোনিয়া, জাকিন্থোস, লেফকাদা, প্রেভেজা ও পার্গা সহ আলবেনিয়া-মোরা উপকূলে ভেনিসের ঘাঁটি) ফ্রান্সের হাতে যায়। অস্ট্রিয়া নিম্নভূমিতে (বর্তমান বেলজিয়াম) তার ভূমিও ফ্রান্সকে ছেড়ে দেয়।", "296ee82f"]},
"OLAYLAR_EK16:1800-09-05:0":{"b": ["মাল্টার ব্রিটেনের কাছে আত্মসমর্পণ — দুই বছরের ফরাসি অবরোধের সমাপ্তি", "fedc2867"], "d": ["1798 সালে মিসর অভিযানের পথে নেপোলিয়নের দখল করা মাল্টা অল্প সময়ে দ্বীপবাসীর বিদ্রোহে ব্রিটিশ নৌবহরের নৌ-অবরোধের আওতায় আসে; দুই বছর চলা অবরোধ ও দুর্ভিক্ষের পর ফরাসি সেনাপতি জেনারেল ভবোয়া 5 সেপ্টেম্বর 1800 তারিখে ব্রিটিশ জেনারেল পিগটের কাছে আত্মসমর্পণ করেন। মাল্টা এভাবে ফরাসি প্রজাতন্ত্র থেকে ব্রিটিশ আশ্রয়ে যায় এবং 1814 সালের প্যারিস চুক্তিতে আনুষ্ঠানিকভাবে ব্রিটিশ মুকুটের অধীন হবে — ভূমধ্যসাগরে ব্রিটেনের সবচেয়ে গুরুত্বপূর্ণ নৌঘাঁটিতে পরিণত হয়।", "6f406ae3"]},
"OLAYLAR_EK16:1802-03-25:0":{"b": ["আমিয়াঁ চুক্তি — মেনোর্কা স্পেনকে ফিরিয়ে দেওয়া", "f341e4b8"], "d": ["ফ্রান্স, স্পেন, নেদারল্যান্ডস ও ইংল্যান্ডের মধ্যে স্বাক্ষরিত আমিয়াঁ চুক্তি (25 মার্চ 1802) দ্বিতীয় কোয়ালিশন যুদ্ধ সাময়িকভাবে শেষ করে; ইংল্যান্ড যুদ্ধকালে দখল করা প্রায় সব ভূমি (সিলোন ও ত্রিনিদাদ বাদে) ফেরত দেয় — এর একটি ছিল 1798 সালে স্পেনের কাছ থেকে নেওয়া মেনোর্কা। শান্তি মাত্র এক বছর টিকে, 1803 সালের মে মাসে যুদ্ধ আবার শুরু হয়, কিন্তু মেনোর্কা এ চুক্তির পর আর কখনো ইংরেজদের হাতে যায়নি।", "7986aead"]},
"OLAYLAR_EK16:1809-09-17:0":{"b": ["ফ্রেডরিকশামন (হামিনা) চুক্তি — সুইডেনের ফিনল্যান্ড রাশিয়াকে ছেড়ে দেওয়া", "c0d407bc"], "d": ["1808-1809 সালের রুশ-সুইডিশ যুদ্ধের অবসান ঘটানো ফ্রেডরিকশামন (বর্তমান হামিনা) চুক্তি 17 সেপ্টেম্বর 1809 তারিখে স্বাক্ষরিত হয়; সুইডেন অল্যান্ড দ্বীপপুঞ্জ সহ সমগ্র ফিনল্যান্ড রাশিয়াকে ছেড়ে দেয়। ফিনল্যান্ড রুশ সাম্রাজ্যের অধীন ব্যাপক স্বায়ত্তশাসিত গ্র্যান্ড ডাচির মর্যাদা পায় এবং লুথারান বিশ্বাস ও সুইডিশ আইন ধরে রাখে। এর অর্থ ছিল বাল্টিকে সুইডেনের বৃহৎ শক্তির মর্যাদার কার্যত অবসান। এ চুক্তিতে ফিনল্যান্ডের ছয়টি প্রদেশ এবং তোর্নে নদী পর্যন্ত ভেস্টারবটেন (কোক্কোলা, ইয়োয়েনসু, সাভোনলিন্না, তর্নিও, রোভানিমি, ইনারি প্রভৃতি) রাশিয়ার অধীন ফিনল্যান্ড গ্র্যান্ড ডাচিতে যায়।", "fb46c9a1"]},
"OLAYLAR_EK16:1810-03-04:0":{"b": ["ইমেরেতি রাজ্যের সংযুক্তি — রাজা দ্বিতীয় সলোমন সিংহাসনচ্যুত", "5ad36bff"], "d": ["1804 সালে এলাজনাউরি চুক্তিতে রুশ অধীনতা মেনে নিতে বাধ্য হওয়া পশ্চিম জর্জীয় ইমেরেতি রাজ্যের শেষ রাজা দ্বিতীয় সলোমন বাড়তে থাকা রুশ চাপের বিরুদ্ধে প্রতিরোধ চালিয়ে গেলে, রুশ সেনা 20 ফেব্রুয়ারি 1810 তারিখে রাজধানী কুতাইসি দখল করে, সলোমনকে সিংহাসনচ্যুত করে এবং স্থানীয় অভিজাতদের জার প্রথম আলেকজান্দারের প্রতি আনুগত্যের শপথ নিতে বাধ্য করে; ইমেরেতি রাজ্য এভাবে কার্যত শেষ হয় এবং সরাসরি রুশ শাসনের অধীন হয়। সলোমন অটোমান ভূমিতে পালিয়ে নির্বাসনে মারা যান (1815)।", "fdccc40f"]},
"OLAYLAR_EK16:1814-01-14:0":{"b": ["কিল চুক্তি — ডেনমার্কের নরওয়ে সুইডেনকে ছেড়ে দেওয়া", "59ab1601"], "d": ["লাইপৎসিগে নেপোলিয়নের পরাজয়ের পর ডেনমার্কে দক্ষিণ থেকে আক্রমণ করা সুইডেন 14 জানুয়ারি 1814 তারিখে স্বাক্ষরিত কিল চুক্তিতে নরওয়ে (আইসল্যান্ড, ফেরো দ্বীপপুঞ্জ ও গ্রিনল্যান্ড বাদে) গ্রহণ করে — 1380 সাল থেকে চলা ডেনমার্ক-নরওয়ে ঐক্য এভাবে আনুষ্ঠানিকভাবে শেষ হয়। বিনিময়ে সুইডেন পোমেরানিয়ার ভূমি ডেনমার্ককে ছেড়ে দেয়; ডেনমার্ক হেলিগোল্যান্ডও ইংল্যান্ডকে হস্তান্তর করে। নরওয়ে চুক্তির বিরুদ্ধে অস্ত্র নিয়ে দাঁড়িয়ে নিজস্ব সংবিধান ঘোষণা করে এবং সুইডেন তা মানতে বাধ্য হয় — ফল হয় 1905 সাল পর্যন্ত চলা ব্যক্তিগত ঐক্য (real union)। সুইডেন নরওয়েকে কার্যত গ্রহণ করতে পারেনি: চুক্তি নরওয়েতে গৃহীত হয়নি এবং প্রশাসন ক্রিস্টিয়ান ফ্রেডেরিকের হাতেই থাকে; সুইডিশ সেনা নরওয়েতে কেবল 26 জুলাই 1814 তারিখে প্রবেশ করে।", "223aed9a"]},
"OLAYLAR_EK16:1815-06-09:0":{"b": ["ভিয়েনা কংগ্রেসের চূড়ান্ত দলিল — নেপোলিয়ন-পরবর্তী ইউরোপের মানচিত্র নতুন করে আঁকা", "fca1c676"], "d": ["নেপোলিয়নীয় যুদ্ধ শেষ করা বৃহৎ শক্তিগুলোর (অস্ট্রিয়া, রাশিয়া, প্রুশিয়া, ইংল্যান্ড, ফ্রান্স) মধ্যে স্বাক্ষরিত ভিয়েনা কংগ্রেসের চূড়ান্ত দলিল 9 জুন 1815 তারিখে (ওয়াটারলুর 9 দিন আগে) গৃহীত হয় এবং মহাদেশের মানচিত্র সম্মিলিতভাবে নতুন করে আঁকে: পূর্বতন স্পেনীয়/অস্ট্রীয় নেদারল্যান্ডস ও সংযুক্ত প্রদেশগুলো ‘সংযুক্ত নেদারল্যান্ডস রাজ্য’-এর অধীনে একত্র হয়, জেনোয়া প্রজাতন্ত্র সার্ডিনিয়া-পিডমন্ট রাজ্যে যুক্ত হয়, ওয়ারশ গ্র্যান্ড ডাচির বড় অংশ ‘কংগ্রেস পোল্যান্ড’ নামে রাশিয়ার অধীন হয় এবং সুইডিশ পোমেরানিয়া (স্ট্রালজুন্ড) প্রুশিয়ার হাতে যায়। এ একটি দিন যুদ্ধোত্তর ইউরোপীয় ভারসাম্যের (Concert of Europe) আনুষ্ঠানিক সূচনা গণ্য হয়। এ দলিলে উদ্‌জ, চেস্তোখোভা, কিয়েলৎসে, রাদম, লুবলিন, খেলম ও জামোশ্চ (ওয়ারশ গ্র্যান্ড ডাচি) রাশিয়ার অধীন পোল্যান্ড রাজ্যে, পোজনান (পোজেন গ্র্যান্ড ডাচি) প্রুশিয়ায়, মাস্ত্রিখ্ট ও রোয়ের্মন্ড নেদারল্যান্ডস রাজ্যে যায়।", "b0c34466"]},
"OLAYLAR_EK16:1820-01-08:0":{"b": ["সাধারণ নৌ-চুক্তি — কাওয়াসিম ও অন্যান্য উপসাগরীয় শেখাত ব্রিটেনের সঙ্গে চুক্তিবদ্ধ", "fc499e19"], "d": ["ব্রিটেন 1819 সালে রাস আল-খাইমায় গোলাবর্ষণ করে ‘জলদস্যু’ কাসিমি নৌবহর ছত্রভঙ্গ করার পর 8 জানুয়ারি 1820 থেকে শুরু হয়ে অঞ্চলের শেখাতগুলোর সঙ্গে এক এক করে স্বাক্ষরিত হয়ে মার্চের মধ্যে সম্পূর্ণ হওয়া সাধারণ নৌ-চুক্তি চাপিয়ে দেয়; চুক্তি জলদস্যুতা ও দাসত্ব নিষিদ্ধ করে এবং জাহাজগুলোকে ব্রিটিশ পতাকার অনুরূপ লাল-সাদা পতাকা বহন বাধ্যতামূলক করে। এ চুক্তিতে ‘জলদস্যু উপকূল’ ক্রমে ‘যুদ্ধবিরতি উপকূল’-এ (ট্রুসিয়াল কোস্ট) রূপ নেয়; 1853 সালের স্থায়ী নৌ-যুদ্ধবিরতি ও 1892 সালের একচেটিয়া চুক্তিগুলোতে গভীর হওয়া ব্রিটিশ আধিপত্য ছিল 1971 সাল পর্যন্ত চলা সম্পর্কের সূচনা।", "0b50923a"]},
"OLAYLAR_EK16:1861-02-13:0":{"b": ["গায়েতা অবরোধের সমাপ্তি — দুই সিসিলি রাজ্যের পতন", "121ae580"], "d": ["1860 সালের মে মাসে গারিবাল্দির সিসিলিতে অবতরণে শুরু হওয়া পতনের পর নেপলস থেকে পালানো বুরবন রাজা দ্বিতীয় ফ্রানচেস্কো তাঁর শেষ দুর্গ গায়েতায় 3 নভেম্বর 1860 থেকে অবরুদ্ধ হন; 1861 সালের জানুয়ারিতে ফরাসি নৌবহর অঞ্চল ছেড়ে গেলে ইতালীয় নৌ-অবরোধ কঠোর হয় এবং 13 ফেব্রুয়ারি 1861 তারিখে গায়েতা আত্মসমর্পণ করে। দ্বিতীয় ফ্রানচেস্কো সিংহাসন ত্যাগ করে নির্বাসনে যান; দুই সিসিলি রাজ্যের শেষ প্রতিরোধ বিন্দু চিভিতেল্লা দেল ত্রন্তো কেবল 20 মার্চ 1861 তারিখে পতিত হবে। রাজ্যের পতনে সিসিলির (পালের্মো, মেসিনা, সিরাকুসা, ত্রাপানি, মিসিলমেরি) ও কাম্পানিয়ার (নোলা সহ) ভূমি আর বুরবন শাসনে ছিল না।", "bb89dfd9"]},
"OLAYLAR_EK16:1861-03-17:0":{"b": ["ইতালি রাজ্যের ঘোষণা — সার্ডিনিয়া, তুসকানি ও দক্ষিণ ইতালির একত্রীকরণ", "12e52f70"], "d": ["ইতালীয় পার্লামেন্টের তুরিনে প্রথম অধিবেশনে 17 মার্চ 1861 তারিখে ইতালি রাজ্য আনুষ্ঠানিকভাবে ঘোষিত হয় এবং সার্ডিনিয়া-পিডমন্টের রাজা দ্বিতীয় ভিত্তোরিও এমানুয়েলে ঐক্যবদ্ধ ইতালির প্রথম রাজা হন। নতুন রাজ্য আগের বছর গণভোটে যুক্ত হওয়া তুসকানি, এমিলিয়া-রোমাঞ্ঞা, নেপলস ও সিসিলির (দুই সিসিলি) ভূমি সার্ডিনিয়া রাজ্যের সঙ্গে একত্র করে; রোম (পোপীয় রাষ্ট্র) ও ভেনিস (অস্ট্রিয়া) তখনও বাইরে ছিল — তারা যথাক্রমে 1870 ও 1866 সালে যুক্ত হবে।", "d044a9c0"]},
"OLAYLAR_EK16:1866-10-18:0":{"b": ["জিজ্জাখের (Jizzakh) রাশিয়ার হাতে পতন — বুখারা আমিরাতের সির দরিয়া সীমান্তরেখার শেষ দুর্গ", "21205a6e"], "d": ["মধ্য এশিয়ায় রাশিয়ার অগ্রযাত্রার সময় জেনারেল চের্নিয়ায়েভের 1866 সালের ফেব্রুয়ারির ব্যর্থ প্রচেষ্টার পর, তাঁর স্থলাভিষিক্ত জেনারেল দিমিত্রি রোমানভস্কির নেতৃত্বাধীন রুশ বাহিনী 1866 সালের অক্টোবরে সাত দিনের অবরোধ ও তীব্র আক্রমণের মাধ্যমে বুখারা আমিরাতের সির দরিয়া উপত্যকার শেষ বড় দুর্গ জিজ্জাখ দখল করে; এই পতন অঞ্চলে বুখারার প্রতিরোধ কার্যত শেষ করে দেয় এবং সমরকন্দের পথে রুশ সেনাবাহিনীর যাত্রা সুগম করে।", "b95ba993"]},
"OLAYLAR_EK16:1868-05-14:0":{"b": ["রুশ বাহিনী সমরকন্দ দখল করল — শহর বুখারা আমিরাত থেকে তুর্কিস্তান গভর্নর-জেনারেলের অধীনে গেল", "321473be"], "d": ["রুশ বাহিনী বুখারা আমিরাতের হাতে থাকা সমরকন্দ দখল করে এবং শহরটিকে তুর্কিস্তান সাধারণ প্রশাসনিক অঞ্চলের সঙ্গে যুক্ত করে। সমরকন্দ উজবেক খানদের আমলে বুখারার ছায়ায় থাকা একটি শহর ছিল; রুশ শাসনে এটি মধ্য এশিয়ায় রুশ অগ্রযাত্রার একটি নতুন ঘাঁটি হয়ে ওঠে।", "3bc56bbe"]},
"OLAYLAR_EK16:1870-09-28:0":{"b": ["স্ট্রাসবুর্গের আত্মসমর্পণ: জার্মান বাহিনী শহর দখল করল", "ef3281f3"], "d": ["ছয় সপ্তাহের অবরোধ ও গোলাবর্ষণের পর জেনারেল উরিক রাতে কোনিগসহোফেনে আত্মসমর্পণ চুক্তিতে স্বাক্ষর করেন; সকালে ফটক ও দুর্গ প্রুশীয় ও বাডেন বাহিনীর হাতে সমর্পিত হয়। শহর ফ্রাঙ্কফুর্ট চুক্তি (10 মে 1871) পর্যন্ত সামরিক দখলে ছিল।", "38c8361d"]},
"OLAYLAR_EK16:1870-10-29:0":{"b": ["মেৎসের আত্মসমর্পণ: বাজেনের বাহিনী অস্ত্র ত্যাগ করল, জার্মান বাহিনী দুর্গ নিল", "8dd66f58"], "d": ["অবরুদ্ধ রাইন বাহিনীর আত্মসমর্পণ প্রোটোকল 27 অক্টোবর সন্ধ্যায় স্বাক্ষরিত হয়; 29 অক্টোবর সকালে প্রুশীয় পতাকা দুর্গপ্রাকারে উত্তোলিত হয় এবং ফরাসি বাহিনী দুর্গ ত্যাগ করে। মেৎস ফ্রাঙ্কফুর্ট চুক্তি (10 মে 1871) পর্যন্ত সামরিক দখলে ছিল।", "112e1a60"]},
"OLAYLAR_EK16:1882-03-10:0":{"b": ["আসসাবের ইতালীয় রাষ্ট্রীয় মালিকানায় হস্তান্তর — ইতালির প্রথম উপনিবেশের ভিত্তি", "15ab8732"], "d": ["লোহিত সাগরের তীরের আসসাব বন্দর 1869 সালে একটি বেসরকারি ইতালীয় জাহাজ কোম্পানি (রুবাত্তিনো) স্থানীয় আফার নেতাদের কাছ থেকে কিনে নিয়েছিল; ইংল্যান্ডের সম্মতিতে ইতালীয় সরকার 1882 সালের 10 মার্চ বন্দরের সরাসরি রাষ্ট্রীয় মালিকানা গ্রহণ করে এবং জুলাই মাসে জারি করা আইনে আসসাবকে আনুষ্ঠানিকভাবে ইতালির প্রথম উপনিবেশ ঘোষণা করে। এটি ছিল ইতালির লোহিত সাগর উপকূলে সম্প্রসারণের সূচনাবিন্দু, যা পরে এরিত্রিয়া উপনিবেশে (1890) রূপ নেয়।", "ba606490"]},
"OLAYLAR_EK16:1884-02-08:0":{"b": ["সিনকাত গ্যারিসনের বিনাশ — সিনকাত মাহদী বাহিনীর হাতে গেল", "e175a94e"], "d": ["মাসের পর মাস ওসমান দিগনার বাহিনীর অবরোধে থাকা এবং রসদ ফুরিয়ে যাওয়া সিনকাত গ্যারিসন তাদের অধিনায়ক তাওফিক বেকের সঙ্গে অবরোধ ভেঙে সুয়াকিনে পৌঁছানোর চেষ্টা করে; 1884 সালের 8 ফেব্রুয়ারি দুর্গের বাইরে তারা বিনষ্ট হয় এবং সিনকাত মাহদী বাহিনীর হাতে চলে যায়। খবর 12 ফেব্রুয়ারি সুয়াকিনে পৌঁছায়।", "abf8611c"]},
"OLAYLAR_EK16:1884-02-09:0":{"b": ["সুয়াকিনে সামরিক আইন — শহর ইংরেজ কমান্ডের অধীনে গেল", "801f6a81"], "d": ["বেকারের তোকার ত্রাণ বাহিনী 4 ফেব্রুয়ারি এল-তেবে পরাজিত হওয়ার পর অ্যাডমিরাল হিউইট 6 ফেব্রুয়ারি সুয়াকিনে নৌসেনা নামান। 1884 সালের 9 ফেব্রুয়ারি শহরে সামরিক আইন জারি হয় এবং ইংরেজ কর্মকর্তাদের শহরের ওপর সামরিক ও বেসামরিক পূর্ণ ক্ষমতা দেওয়া হয়; পরদিন শহরের দায়িত্ব আনুষ্ঠানিকভাবে বেকারের কাছ থেকে হিউইটের হাতে হস্তান্তরিত হয়।", "92798eb8"]},
"OLAYLAR_EK16:1884-02-20:0":{"b": ["মাহদী বাহিনীর কাছে তোকারের আত্মসমর্পণ", "0e21fd24"], "d": ["অবরুদ্ধ তোকার গ্যারিসন 1884 সালের 19 ফেব্রুয়ারি মাহদী বাহিনীর সঙ্গে আলোচনায় বসে এবং পরদিন, 20 ফেব্রুয়ারি শহর সমর্পণ করে। খবর 24 ফেব্রুয়ারি ত্রিনকিতাতে ইংরেজ বাহিনীর কাছে পৌঁছায়; গ্রাহামের ত্রাণ অভিযান দেরি করে ফেলেছিল।", "0ebad590"]},
"OLAYLAR_EK16:1884-07-14:0":{"b": ["উত্তর সোমালি উপকূলে ব্রিটেনের আশ্রিত শাসন প্রতিষ্ঠা — সোমালিল্যান্ডের সূচনা", "f301ea94"], "d": ["টিডিভি (TDV)-র সোমালি নিবন্ধ অনুযায়ী জেইলা, বেরবেরা ও তাজুরা 1884 সালে ইংরেজদের দ্বারা সোমালিল্যান্ড নামে উপনিবেশ হয়; আদর্শ একাডেমিক উৎস অনুযায়ী এ প্রক্রিয়া বেরবেরায় 21 রমজান 1301 (14 জুলাই 1884) তারিখে হাবার আওয়াল গোত্রের সঙ্গে স্বাক্ষরিত চুক্তিতে শুরু হয় এবং 1884-1886 সালে গাদাবুরসি, হাবার তোলজা’লা, হাবার গের্হাজিস, ইসা ও ওয়ারসাঙ্গেলি গোত্রের সঙ্গে অনুরূপ চুক্তি স্বাক্ষরে বিস্তৃত হয়; ব্রিটেন বিনিময়ে সামরিক সুরক্ষার প্রতিশ্রুতি দেয়। এ চুক্তি-শৃঙ্খল 1887 সালে আনুষ্ঠানিক ব্রিটিশ সোমালিল্যান্ড আশ্রিত রাজ্য ঘোষণার ভিত্তি তৈরি করে।", "1bce7d3e"]},
"OLAYLAR_EK16:1891-01-01:0":{"b": ["মুলাইদা যুদ্ধ — দ্বিতীয় সউদি রাষ্ট্রের অবসান, নজদ রাশিদিদের হাতে", "1cd3b213"], "d": ["যাকাত বিরোধ ও এক রাশিদি দূতের গ্রেপ্তারে বিগড়ে যাওয়া সম্পর্কের পরিণামে জাবাল শাম্মারের আমির মুহাম্মদ ইবনে রাশিদের সেনা 21 জানুয়ারি 1891 তারিখে কাসিম অঞ্চলের মুলাইদায় আবদুর রহমান ইবনে ফয়সালের নেতৃত্বাধীন সউদি বাহিনী ও তাদের মিত্রদের ভারী পরাজয়ে ফেলে; এটি দ্বিতীয় সউদি রাষ্ট্রের কার্যত অবসান ছিল, আল সউদ পরিবার কুয়েতে নির্বাসনে যায় এবং সমগ্র নজদ রাশিদি কর্তৃত্বে আসে; দক্ষিণের দিলাম (হারজ), হাউতা (হাউতাত বনি তামিম) ও লাইলা (আফলাজ) এলাকাও এর অন্তর্ভুক্ত ছিল। কর্তৃত্ব 1902 সালে তরুণ আবদুল আজিজ ইবনে সউদের রিয়াদ পুনরুদ্ধার (রিয়াদ অভিযান, 16 জানুয়ারি 1902) পর্যন্ত চলবে।", "b77d8161"]},
"OLAYLAR_EK16:1891-02-19:0":{"b": ["ইংরেজ-মিশরীয় বাহিনীর হাতে তোকারের পুনরুদ্ধার — ওসমান দিগনার পশ্চাদপসরণ", "80a2c26a"], "d": ["1884 সাল থেকে মাহদী আন্দোলনের স্থানীয় অধিনায়ক ওসমান দিগনার হাতে থাকা লোহিত সাগর উপকূলের তোকার 1891 সালের ফেব্রুয়ারিতে ইংরেজ-মিশরীয় বাহিনীর অভিযানে পুনরুদ্ধার হয়; ওসমান দিগনা পাহাড়ে পিছু হটতে বাধ্য হন। এটি লোহিত সাগর উপকূলে মাহদী রাষ্ট্রের উপস্থিতিতে বড় আঘাত হয় এবং অঞ্চলটি ইংরেজ-মিশরীয় যৌথ শাসনের অধীনে আসে।", "07bd31cf"]},
"OLAYLAR_EK16:1891-03-03:0":{"b": ["গ্রেনফেল বাহিনীর সিনকাত অতিক্রম — সিনকাত মাহদী শাসন থেকে বেরিয়ে ইংরেজ-মিশরীয় শাসনে ফিরল", "b7539a44"], "d": ["1891 সালের ফেব্রুয়ারিতে তোকার পুনর্দখলের পর গ্রেনফেলের নেতৃত্বাধীন ইংরেজ-মিশরীয় বাহিনী 1891 সালের 3 মার্চ আফাফিত থেকে সিনকাত হয়ে যাত্রা করে এবং 7 মার্চ সুয়াকিনে পৌঁছায়; বাহিনী 1884 সাল থেকে প্রবেশের অযোগ্য থাকা অঞ্চলটি শত্রুমুক্ত অবস্থায় পায়। 8 মার্চ সুয়াকিনে সমবেত শেখদের খেদিভের নামে সাধারণ ক্ষমা ঘোষণা করা হয় এবং সিনকাত পুনরায় ইংরেজ-মিশরীয় শাসনের অধীনে আসে।", "5e77e2d3"]},
"OLAYLAR_EK16:1905-01-01:0":{"b": ["ইতালীয় সোমালিল্যান্ডের সরাসরি রাষ্ট্রীয় শাসনে যাওয়া — বেনাদির কোম্পানির বিলুপ্তি", "8c7d085b"], "d": ["টিডিভি (TDV)-র সোমালি নিবন্ধ অনুযায়ী ইতালি দক্ষিণ সোমালি উপকূলে (বেনাদির) কর্তৃত্ব 1889-1891 সালে জাঞ্জিবার সুলতানাত ও ইংল্যান্ডের সঙ্গে চুক্তির মাধ্যমে স্থাপন করেছিল, প্রশাসন শুরুতে একটি সুবিধাপ্রাপ্ত বাণিজ্য কোম্পানির (বেনাদির কোম্পানি) হাতে ছেড়েছিল; আদর্শ একাডেমিক উৎস অনুযায়ী এ কোম্পানির সনদ 24 জানুয়ারি 1905 তারিখে শেষ হয় এবং ইতালীয় রাষ্ট্র বেনাদির উপকূলের (মোগাদিশু, মের্কা, বারাওয়ে সহ) সরাসরি সার্বভৌমত্ব কিনে নিয়ে আনুষ্ঠানিক উপনিবেশ শাসন স্থাপন করে। উপনিবেশের অভ্যন্তরের দিকে (বারদেরা, বাইদোয়া) কার্যত সম্প্রসারণ 1908 সালের প্রতিষ্ঠা-ফরমান ও পরবর্তী বছরগুলোতে সম্পন্ন হবে।", "3ebbbdd3"]},
"OLAYLAR_EK16:1905-06-07:0":{"b": ["নরওয়ে-সুইডেন ঐক্যের বিলুপ্তি — স্টোর্টিংয়ের একতরফা স্বাধীনতা ঘোষণা", "aaba2935"], "d": ["নরওয়ে সরকারের আলাদা কনসুলেট স্থাপনের দাবি রাজা দ্বিতীয় অস্কার ভেটো দিলে এবং নতুন সরকার গঠন করতে পারবেন না বলে জানালে, নরওয়ের স্টোর্টিং (পার্লামেন্ট) 7 জুন 1905 তারিখে সর্বসম্মতিক্রমে সিদ্ধান্ত নেয় যে রাজা আর কার্যত নরওয়ের রাজা হিসেবে দায়িত্ব পালন করছেন না এবং 1814 সালের কিল চুক্তি থেকে চলা ঐক্য বিলুপ্ত। 13 আগস্ট 1905 তারিখের গণভোটে ভোটারদের প্রায় সবাই (371,000-এর বিপরীতে 184 ভোট) বিলুপ্তি অনুমোদন করে; সুইডেন কার্লস্টাড আলোচনার পর 26 অক্টোবর 1905 তারিখে স্বাধীনতা আনুষ্ঠানিকভাবে স্বীকৃতি দেয়।", "94eda38c"]},
"OLAYLAR_EK16:1915-05-08:0":{"b": ["লিবাউ (লিয়েপাইয়া) জার্মান বাহিনীর হাতে দখল — কুরল্যান্ড দখল শুরু", "fdb10548"], "d": ["জার্মান 1915 সালের গ্রীষ্মকালীন আক্রমণে কুরল্যান্ডে প্রবেশ করে; লিবাউ বাল্টিক উপকূলের রুশ নৌঘাঁটি ছিল। কুরল্যান্ডের বেশিরভাগ ওবার অস্ট কমান্ডের অধীনে যায় (1918 সালের শেষ পর্যন্ত)।", "98e7ef58"]},
"OLAYLAR_EK16:1915-08-01:0":{"b": ["মিতাউ (ইয়েলগাভা) জার্মান বাহিনীর হাতে দখল", "eb491281"], "d": ["কুরল্যান্ডের প্রাক্তন ডাচি-রাজধানী মিতাউ জার্মান নিয়ন্ত্রণে আসে; রিগা ফ্রন্ট দাউগাভা রেখায় স্থির হয়ে 1917 সাল পর্যন্ত অচল থাকে।", "05882415"]},
"OLAYLAR_EK16:1915-08-18:0":{"b": ["কোভনো (কাউনাস) দুর্গ জার্মানদের হাতে দখল — লিথুয়ানিয়া দখলদারির অধীনে গেল", "9849405b"], "d": ["জার্মান 10ম বাহিনী নেমান নদীর ওপর রাশিয়ার সবচেয়ে বড় দুর্গ দখল করে; লিথুয়ানিয়া অঞ্চল ওবার অস্ট প্রশাসনের অধীনে যায় এবং 1918 সালে তারিবা এই দখলের অধীনেই স্বাধীনতা ঘোষণা করে।", "1f9a43bc"]},
"OLAYLAR_EK16:1915-09-18:0":{"b": ["ভিলনা (ভিলনিউস) জার্মান বাহিনীর হাতে দখল", "2781858b"], "d": ["মহা পশ্চাদপসরণের সময় ভিলনা জার্মান বাহিনীর হাতে যায় এবং ওবার অস্টের লিথুয়ানিয়া অঞ্চলের সঙ্গে যুক্ত হয়; শহর 1919 সাল পর্যন্ত জার্মান, সোভিয়েত ও পোলিশ বাহিনীর মধ্যে হাত বদল হয়।", "d9dddcbb"]},
"OLAYLAR_EK16:1916-11-03:0":{"b": ["ইংরেজ-কাতার চুক্তি — কাতার ব্রিটিশ আশ্রিত রাজ্যে পরিণত হলো", "f61c4e49"], "d": ["প্রথম বিশ্বযুদ্ধ চলাকালে পারস্য উপসাগরে ব্রিটিশ রাজনৈতিক প্রতিনিধি মেজর পার্সি কক্স এবং কাতারের শেখ আবদুল্লাহ বিন কাসিম আল থানির মধ্যে 1916 সালের 3 নভেম্বর স্বাক্ষরিত চুক্তির মাধ্যমে কাতার তার পররাষ্ট্র সম্পর্ক ইংল্যান্ডের অনুমোদনের অধীনে রাখতে সম্মত হয় এবং বিনিময়ে সামুদ্রিক আক্রমণের বিরুদ্ধে ব্রিটিশ সুরক্ষার নিশ্চয়তা পায়; এই চুক্তি 1971 সাল পর্যন্ত চলা কাতারের ব্রিটিশ আশ্রিত সম্পর্কের আইনি ভিত্তি গড়ে তোলে এবং আনুষ্ঠানিকভাবে 1918 সালে অনুমোদিত হয়।", "abf30185"]},
"OLAYLAR_EK16:1917-09-03:0":{"b": ["রিগা জার্মান 8ম বাহিনীর হাতে দখল", "df95df19"], "d": ["জার্মান বাহিনী দাউগাভা অতিক্রম করে রিগা দখল করে; শহর 1918 সালের নভেম্বর পর্যন্ত জার্মান নিয়ন্ত্রণে ছিল, লাটভিয়ার স্বাধীনতা এই দখলের অধীনেই ঘোষিত হয় (18 নভেম্বর 1918)।", "e0339705"]},
"OLAYLAR_EK16:1918-11-18:0":{"b": ["লাটভিয়ার গণপরিষদ স্বাধীনতা ঘোষণা করল", "fc72a7f7"], "d": ["রিগার জাতীয় থিয়েটারে সমবেত লাটভিয়ার গণপরিষদ রুশ সাম্রাজ্য থেকে স্বাধীন লাটভিয়া প্রজাতন্ত্র ঘোষণা করে; কার্লিস উলমানিসের নেতৃত্বে অস্থায়ী সরকার গঠিত হয়। কয়েক সপ্তাহ পর (ডিসেম্বর 1918) সোভিয়েত রাশিয়া আক্রমণ করে এবং স্বাধীনতা যুদ্ধ শুরু হয়। এই ঘোষণায় রিগা, ইয়েলগাভা, লিয়েপাইয়া, ভেন্তস্পিলস, চেসিস, দাউগাভপিলস ও রেজেকনে লাটভিয়া প্রজাতন্ত্রের ভূখণ্ড বলে গণ্য হয়।", "615adeb0"]},
"OLAYLAR_EK16:1919-01-05:0":{"b": ["লালফৌজ ভিলনিউসে প্রবেশ করল — লিথুয়ানীয় সরকার শহর খালি করল", "889a97b3"], "d": ["লালফৌজ এগিয়ে আসার সময় লিথুয়ানীয় সরকার ভিলনিউস খালি করে; সোভিয়েত বাহিনী শহরে প্রবেশ করে এবং 1919 সালের ফেব্রুয়ারিতে এখান থেকেই লিথুয়ানিয়া-বেলারুশ সোভিয়েত প্রজাতন্ত্র (লিটবেল) ঘোষিত হয়। শহরটি 1919 সালের এপ্রিলে পোলিশ বাহিনীর হাতে যাবে।", "c3a0c216"]},
"OLAYLAR_EK16:1919-04-21:0":{"b": ["পোলিশ বাহিনী সোভিয়েতদের কাছ থেকে ভিলনিউস (ভিলনো) নিল", "32d36c4a"], "d": ["ইউজেফ পিউসুদস্কির বাহিনী 1919 সালের এপ্রিলে লালফৌজের কাছ থেকে ভিলনো দখল করে; লিথুয়ানিয়া শহরটির দাবি চালিয়ে যায় এবং ভিলনিউস সমস্যা দুই বিশ্বযুদ্ধের মধ্যবর্তী লিথুয়ানিয়া-পোল্যান্ড সম্পর্ককে বিষাক্ত করে তোলে।", "85e7c434"]},
"OLAYLAR_EK16:1922-02-28:0":{"b": ["ইংল্যান্ড মিশরের ওপর আশ্রিত রাজ্যের মর্যাদা তুলে নিয়ে মিশরকে স্বাধীন ঘোষণা করল", "f8faab66"], "d": ["ইংল্যান্ড 1922 সালের 28 ফেব্রুয়ারির ঘোষণায় 1914 সাল থেকে চলা আশ্রিত রাজ্যের মর্যাদা একতরফাভাবে শেষ করে এবং মিশরকে স্বাধীন রাষ্ট্র ঘোষণা করে; প্রতিরক্ষা, যোগাযোগপথ ও সুদানের মতো বিষয় ইংল্যান্ডের জন্য সংরক্ষিত থাকে। ঘোষণার দুই সপ্তাহ পর (15 মার্চ 1922) সুলতান আহমদ ফুয়াদ রাজার উপাধি নেন। মানচিত্রে মিশরের শহরগুলোর ইংরেজ দখলের স্তর এই দিনে শেষ হয়।", "8cde4005"]},
"OLAYLAR_EK16:1939-03-22:0":{"b": ["লিথুয়ানিয়া জার্মান চরমপত্র মেনে নিল — মেমেল অঞ্চল জার্মানিকে হস্তান্তরিত হলো", "149fb0b2"], "d": ["রিবেনট্রপের চরমপত্রের ফলে লিথুয়ানিয়া ক্লাইপেদা (মেমেল) অঞ্চল জার্মানিকে ছেড়ে দেয়; হিটলার 23 মার্চ মেমেলে প্রবেশ করেন। অঞ্চলটি 1945 সালের 28 জানুয়ারি লালফৌজের হাতে দখল হয়।", "75afd979"]},
"OLAYLAR_EK16:1941-06-23:0":{"b": ["জার্মানি গ্রোদনো দখল করল", "4e67dc87"], "d": ["পূর্ব ফ্রন্ট: 1941 বারবারোসা ও 1944 বাগ্রাতিওন।", "b96f18f2"]},
"OLAYLAR_EK16:1941-06-23:1":{"b": ["জার্মানি ব্রেস্ট-লিতভস্ক দখল করল", "25898c65"], "d": ["পূর্ব ফ্রন্ট: 1941 বারবারোসা ও 1944 বাগ্রাতিওন।", "b96f18f2"]},
"OLAYLAR_EK16:1941-07-09:0":{"b": ["প্সকভ জার্মান সেনাবাহিনীর হাতে দখল — রুশ ভূমির দখল শুরু", "d9822e30"], "d": ["বারবারোসার তৃতীয় সপ্তাহে ভেরমাখট প্সকভে প্রবেশ করে; শহরটি 1944 সালের 23 জুলাই পর্যন্ত জার্মান সামরিক প্রশাসনের অধীনে থাকে। সূত্র: প্সকভ শহরের কালপঞ্জি, memorialmuseums.org «Memorials in Pskov» (তথ্যটি অনুসন্ধান-সারাংশ থেকে নেওয়া)।", "d9e40fca"]},
"OLAYLAR_EK16:1941-07-11:0":{"b": ["ভিতেবস্ক জার্মান সেনাবাহিনীর হাতে দখল", "e1e4d7d0"], "d": ["আর্মি গ্রুপ সেন্টার বারবারোসার প্রথম সপ্তাহগুলোতে ভিতেবস্ক দখল করে; শহর 1944 সালের জুন পর্যন্ত জার্মান সামরিক প্রশাসনের অধীনে থাকে, তার জনসংখ্যার বড় অংশ বিলুপ্ত হয়।", "aeb95ab0"]},
"OLAYLAR_EK16:1941-07-16:0":{"b": ["স্মোলেনস্ক জার্মান সেনাবাহিনীর হাতে দখল", "5a7f4e2a"], "d": ["আর্মি গ্রুপ সেন্টার স্মোলেনস্ক দখল করে; মস্কোর পথের এই শহর 1943 সালের 25 সেপ্টেম্বর পর্যন্ত 26 মাস দখলে থাকে এবং ব্যাপক ধ্বংসের শিকার হয়।", "1cff2f04"]},
"OLAYLAR_EK16:1941-07-26:0":{"b": ["মোগিলিওভ জার্মান সেনাবাহিনীর হাতে দখল", "4362b7a1"], "d": ["23 দিন স্থায়ী প্রতিরক্ষার পর মোগিলিওভ ভেরমাখটের হাতে যায়; শহর 1944 সালের 28 জুন পর্যন্ত দখলে ছিল।", "082ca73b"]},
"OLAYLAR_EK16:1941-07-28:0":{"b": ["রাইখসকমিসারিয়াট অস্টল্যান্ড গঠিত — বাল্টিক দেশগুলো ও বেলারুশ জার্মান বেসামরিক প্রশাসনের অধীনে গেল", "052d4c08"], "d": ["হিটলারের 1941 সালের 17 জুলাইয়ের সিদ্ধান্তে পূর্বের দখলকৃত ভূমি বেসামরিক প্রশাসনের হাতে দেওয়া হয়; হিনরিখ লোজের নেতৃত্বাধীন অস্টল্যান্ড এস্তোনিয়া, লাটভিয়া, লিথুয়ানিয়া ও বেলারুশকে অন্তর্ভুক্ত করে (কেন্দ্র রিগা)। এস্তোনিয়ায় বেসামরিক প্রশাসন শুরু হয় 1941 সালের 5 ডিসেম্বরে; বেলারুশের পূর্বাংশ সামরিক প্রশাসনের অধীনে থাকে।", "83f60be8"]},
"OLAYLAR_EK16:1941-08-17:0":{"b": ["নারভা জার্মান-এস্তোনীয় বাহিনীর হাতে দখল", "60fc2b6a"], "d": ["গ্রীষ্মযুদ্ধে এস্তোনীয় স্বেচ্ছাসেবক ও ভেরমাখট নারভা দখল করে; শহর অস্টল্যান্ডের অন্তর্ভুক্ত হয় এবং 1944 সালের 26 জুলাই পর্যন্ত জার্মান শাসনে থাকে।", "0f32445c"]},
"OLAYLAR_EK16:1941-08-19:0":{"b": ["নভগোরদ জার্মান সেনাবাহিনীর হাতে দখল", "4f599b62"], "d": ["আর্মি গ্রুপ নর্থ নভগোরদ দখল করে; রাশিয়ার প্রাচীনতম শহরগুলোর একটি 1944 সালের জানুয়ারি পর্যন্ত দখলে থাকে এবং বহুলাংশে ধ্বংস হয়।", "ac0d4ff0"]},
"OLAYLAR_EK16:1941-08-19:1":{"b": ["গোমেল জার্মান সেনাবাহিনীর হাতে দখল", "9d78eb92"], "d": ["ভেরমাখটের গোমেল আক্রমণের তিন দিন পর লালফৌজ শহর থেকে সম্পূর্ণ সরে যায়; শহর 1943 সালের 26 নভেম্বর পর্যন্ত দখলে ছিল।", "56a11e36"]},
"OLAYLAR_EK16:1941-08-28:0":{"b": ["তালিন জার্মান 18তম বাহিনীর হাতে দখল", "a855ad0d"], "d": ["সোভিয়েত বাল্টিক নৌবহরের ক্রনস্টাডটে রক্তক্ষয়ী প্রত্যাহারের মধ্য দিয়ে তালিনের পতন ঘটে; এস্তোনিয়া অস্টল্যান্ডের মধ্যে Generalbezirk Estland হয় (1941 সালের 5 ডিসেম্বর বেসামরিক প্রশাসন)।", "859cfaf1"]},
"OLAYLAR_EK16:1941-10-03:0":{"b": ["ওরেল জার্মান সেনাবাহিনীর হাতে দখল", "3127f454"], "d": ["ব্রিয়ানস্ক-ভিয়াজমা অভিযানে জার্মান দ্বিতীয় পান্ৎসার বাহিনী ওরেল দখল করে; শহরটি 1943 সালের 5 আগস্ট পর্যন্ত দখলে ছিল।", "f5465227"]},
"OLAYLAR_EK16:1941-10-06:0":{"b": ["ব্রিয়ানস্ক জার্মান সেনাবাহিনীর হাতে দখল", "20fa93f8"], "d": ["ব্রিয়ানস্ক যুদ্ধের শেষে জার্মান বাহিনী শহরে প্রবেশ করে; শহরটি 1943 সালের 17 সেপ্টেম্বর পর্যন্ত দখলে ছিল।", "f4a24f91"]},
"OLAYLAR_EK16:1941-11-03:0":{"b": ["কুরস্ক জার্মান সেনাবাহিনীর হাতে দখল", "a723a00a"], "d": ["সোভিয়েত কমান্ডের নির্দেশে কুরস্ক খালি করা হয়, জার্মান দ্বিতীয় বাহিনী শহরে প্রবেশ করে; শহর 1943 সালের 8 ফেব্রুয়ারি পর্যন্ত দখলে ছিল।", "0d07184e"]},
"OLAYLAR_EK16:1943-02-08:0":{"b": ["কুরস্ক লালফৌজের হাতে মুক্ত হলো", "1ac03fba"], "d": ["সোভিয়েত শীতকালীন আক্রমণের (ভরোনেজ-কাস্তর্নোয়ে অভিযানের পর কুরস্ক-খারকভ দিক) শেষে কুরস্ক পুনরুদ্ধার হয়; একই বছরের জুলাইয়ে শহরের নাম কুরস্কের যুদ্ধকে দেওয়া হয়।", "68d51be4"]},
"OLAYLAR_EK16:1943-08-05:0":{"b": ["ওরেল লালফৌজের হাতে পুনরুদ্ধার — কুরস্কের পর প্রথম সোভিয়েত অভিবাদন", "80bfc68d"], "d": ["ওরেল স্যালিয়েন্ট (সম্মুখরেখার অভিক্ষিপ্ত অংশ) দখল করা হলো এবং বেলগোরোদের সঙ্গে একত্রে মস্কোয় প্রথম কামান অভিবাদন দেওয়া হলো।", "54b3efd5"]},
"OLAYLAR_EK16:1943-09-17:0":{"b": ["ব্রিয়ানস্ক লালফৌজের হাতে পুনরুদ্ধার", "d0f2a35f"], "d": ["ব্রিয়ানস্ক অভিযানে শহর 1943 সালের 17 সেপ্টেম্বর পুনরুদ্ধার হয়।", "e6b7799d"]},
"OLAYLAR_EK16:1943-09-25:0":{"b": ["স্মোলেনস্ক লালফৌজের হাতে মুক্ত হলো", "6516d85a"], "d": ["1943 সালের 7 আগস্ট-2 অক্টোবরের স্মোলেনস্ক অভিযানের চূড়ান্ত পর্যায়ে শহর পুনরুদ্ধার হয়; স্মোলেনস্ক 1985 সালে 'বীর শহর' উপাধি পায়।", "e355d898"]},
"OLAYLAR_EK16:1943-11-26:0":{"b": ["গোমেল লালফৌজের হাতে মুক্ত হলো", "280268c2"], "d": ["বেলারুশীয় ফ্রন্ট গোমেল-রেচিৎসা অভিযানে শহর পুনরুদ্ধার করে; এটি বেলারুশের প্রথম বড় শহর মুক্তিগুলোর একটি।", "3402c1b4"]},
"OLAYLAR_EK16:1944-01-20:0":{"b": ["নভগোরদ লালফৌজের হাতে মুক্ত হলো", "52962012"], "d": ["লেনিনগ্রাদ-নভগোরদ অভিযানের সময় ভেলিকি নভগোরদ 1944 সালের 20 জানুয়ারি পুনরুদ্ধার হয়।", "75ea1a61"]},
"OLAYLAR_EK16:1944-06-26:0":{"b": ["ভিতেবস্ক লালফৌজের হাতে মুক্ত হলো — অপারেশন বাগ্রাতিওন", "b06be69c"], "d": ["প্রথম বাল্টিক ও তৃতীয় বেলারুশীয় ফ্রন্ট ভিতেবস্ক ঘিরে দখল করে; এটি অপারেশন বাগ্রাতিওনের প্রথম বড় শহর মুক্তি ছিল।", "9b4d6042"]},
"OLAYLAR_EK16:1944-06-28:0":{"b": ["মোগিলিওভ লালফৌজের হাতে মুক্ত হলো — অপারেশন বাগ্রাতিওন", "52fa985d"], "d": ["দ্বিতীয় বেলারুশীয় ফ্রন্ট মোগিলিওভ দখল করে এবং নিপার রেখা অতিক্রম করে।", "22c05c20"]},
"OLAYLAR_EK16:1944-07-03:0":{"b": ["লালফৌজ মিনস্ক পুনরুদ্ধার করল — অপারেশন বাগ্রাতিওন", "87dc1fb5"], "d": ["22 জুনে শুরু হওয়া অপারেশন বাগ্রাতিওনে বেলারুশীয় ফ্রন্টগুলো আর্মি গ্রুপ সেন্টার ভেদ করে মিনস্ক ঘিরে ফেলে; শহর 3 জুলাই পুনরুদ্ধার হয় এবং পূর্বে প্রায় 50 হাজার জার্মান সৈন্য ঘেরাওয়ে আটকা পড়ে। বেলারুশের জার্মান বেসামরিক প্রশাসন (Generalbezirk Weißruthenien) ভেঙে পড়ে।", "1c35549f"]},
"OLAYLAR_EK16:1944-07-13:0":{"b": ["লালফৌজ ভিলনিউস দখল করল", "0172450e"], "d": ["5-13 জুলাইয়ের ভিলনিউস অভিযানে তৃতীয় বেলারুশীয় ফ্রন্ট জার্মান গ্যারিসনকে ঘিরে শহর দখল করে (পোলিশ হোম আর্মির «অস্ত্রা ব্রামা» অভিযান একই সময়ে চলছিল)। ভিলনিউস লিথুয়ানীয় সোভিয়েত সমাজতান্ত্রিক প্রজাতন্ত্রের রাজধানী হয়।", "aaf124b7"]},
"OLAYLAR_EK16:1944-07-16:0":{"b": ["লালফৌজ গ্রোদনোকে জার্মান দখল থেকে মুক্ত করল", "1d134151"], "d": ["পূর্ব ফ্রন্ট: 1941 বারবারোসা ও 1944 বাগ্রাতিওন।", "b96f18f2"]},
"OLAYLAR_EK16:1944-07-23:0":{"b": ["প্সকভ লালফৌজের হাতে পুনরুদ্ধার", "f18103aa"], "d": ["তিন বছরেরও বেশি জার্মান দখলের পর প্সকভ লালফৌজের হাতে পুনরুদ্ধার হয়।", "b6fb3c84"]},
"OLAYLAR_EK16:1944-07-26:0":{"b": ["লালফৌজ নারভা দখল করল", "64854ae3"], "d": ["1944 সালের ফেব্রুয়ারি থেকে সম্মুখরেখায় ধ্বংসস্তূপ হয়ে থাকা নারভা 1944 সালের জুলাইয়ের নারভা অভিযানে সোভিয়েত বাহিনীর হাতে আসে; এস্তোনিয়ার উত্তর-পূর্বাংশ জার্মান বেসামরিক প্রশাসনের (Generalbezirk Estland) হাত থেকে বেরিয়ে যায়।", "74009a05"]},
"OLAYLAR_EK16:1944-07-27:0":{"b": ["রেজেকনে লালফৌজের হাতে দখল — লাটভিয়ার পূর্বাংশ মুক্ত হলো", "e9efd12d"], "d": ["দ্বিতীয় বাল্টিক ফ্রন্ট রেজেকনে দখল করে; লাটভিয়ার লাতগালে অঞ্চল জার্মান শাসন থেকে বেরিয়ে যায়।", "eac95aa6"]},
"OLAYLAR_EK16:1944-07-27:1":{"b": ["দাউগাভপিলস লালফৌজের হাতে মুক্ত হলো", "b4ee6622"], "d": ["দ্বিতীয় বাল্টিক ফ্রন্টের 360তম পদাতিক ডিভিশন দাউগাভপিলস (দ্যুনাবুর্গ) দখল করে; লাতগালের দ্বিতীয় বড় শহর জার্মান শাসন থেকে বেরিয়ে যায়।", "b8a7bd0d"]},
"OLAYLAR_EK16:1944-07-27:2":{"b": ["শিয়াউলিয়াই লালফৌজের হাতে দখল — শিয়াউলিয়াই অভিযান", "ccb20729"], "d": ["প্রথম বাল্টিক ফ্রন্ট লিথুয়ানিয়ার উত্তরের রেলওয়ে সংযোগস্থল শিয়াউলিয়াই দখল করে; অভিযান 5 জুলাই-29 আগস্ট 1944 চলে এবং রিগা উপসাগরে পৌঁছানো হয়।", "444f3101"]},
"OLAYLAR_EK16:1944-07-28:0":{"b": ["লালফৌজ ব্রেস্ট-লিতভস্ককে জার্মান দখল থেকে মুক্ত করল", "6d5a837a"], "d": ["পূর্ব ফ্রন্ট: 1941 বারবারোসা ও 1944 বাগ্রাতিওন।", "b96f18f2"]},
"OLAYLAR_EK16:1944-08-01:0":{"b": ["কাউনাস লালফৌজের হাতে দখল — লিথুয়ানিয়ার অস্থায়ী রাজধানী জার্মান শাসন থেকে বেরিয়ে এল", "5c2b2c16"], "d": ["তৃতীয় বেলারুশীয় ফ্রন্ট কাউনাস দখল করে; স্তালিনের 1 আগস্টের দৈনিক আদেশে দখলের ঘোষণা দেওয়া হয়। শহরটি 1919-1939 সময়কালে লিথুয়ানিয়ার অস্থায়ী রাজধানী ছিল।", "795fab27"]},
"OLAYLAR_EK16:1944-08-25:0":{"b": ["তার্তু লালফৌজের হাতে দখল — তার্তু অভিযান", "cc8069ab"], "d": ["তৃতীয় বাল্টিক ফ্রন্ট জার্মান 18তম বাহিনীর প্রতিরক্ষা ভেঙে তার্তু দখল করে; শহর কয়েক সপ্তাহ সম্মুখরেখায় ছিল এবং তার্তু অভিযান 1944 সালের 6 সেপ্টেম্বর শেষ হয়।", "3e9ef2ba"]},
"OLAYLAR_EK16:1944-09-22:0":{"b": ["লালফৌজ তালিনে প্রবেশ করল — জার্মান বাহিনী শহর ত্যাগ করল", "41ae1ec5"], "d": ["তালিন অভিযানের সময় জার্মানরা শহর ত্যাগ করে; 18 সেপ্টেম্বর সরকারি ভবনগুলো দখল করা এস্তোনীয় জাতীয় কমিটির সরকার লালফৌজ প্রবেশ করার সময় প্রশাসন ধরে রাখতে পারেনি। এস্তোনিয়া আবার সোভিয়েত শাসনের অধীনে যায়।", "a229e09c"]},
"OLAYLAR_EK16:1945-01-28:0":{"b": ["লালফৌজ মেমেল (ক্লাইপেদা) দখল করল", "d01ad3dc"], "d": ["পূর্ব প্রুশিয়া ও বাল্টিক উপকূলের দিকে সোভিয়েত অভিযানে মেমেল (ক্লাইপেদা) বন্দর জার্মানির হাত থেকে নিয়ে লিথুয়ানীয় সোভিয়েত সমাজতান্ত্রিক প্রজাতন্ত্রের সঙ্গে যুক্ত করা হয়। 1939 সালে জার্মানিকে হস্তান্তরিত অঞ্চলটি এভাবে জার্মান শাসন থেকে বেরিয়ে আসে।", "65cf6a00"]},
"OLAYLAR_EK16:1945-05-08:0":{"b": ["কুরল্যান্ড পকেট আত্মসমর্পণ করল — কুরল্যান্ড আর্মি গ্রুপ গোভোরভের কাছে আত্মসমর্পণ স্বাক্ষর করল", "cf7798b9"], "d": ["1944 সালের অক্টোবর থেকে লিয়েপাইয়া-ভেন্তস্পিলস অঞ্চলে অবরুদ্ধ জার্মান কুরল্যান্ড আর্মি গ্রুপ আত্মসমর্পণ করে; লাটভিয়ার পশ্চিমাংশ সোভিয়েত নিয়ন্ত্রণে যায়।", "a7bfcc52"]},
"OLAYLAR_EK16:1955-12-01:0":{"b": ["ওমানের সুলতানের বাহিনী অভ্যন্তরীণ ওমানের প্রধান কেন্দ্রগুলোতে প্রবেশ করল; ইবাদি ইমামত কার্যত শেষ হলো", "9a9962a5"], "d": ["1955 সালের ডিসেম্বরে ওমানের সুলতান কর্তৃত্ব পুনঃপ্রতিষ্ঠার জন্য অভিযান শুরু করেন এবং তাঁর বাহিনী অভ্যন্তরীণ ওমানের প্রধান বসতিকেন্দ্রগুলোতে (বাহলা, ইযকি, নিযওয়া) প্রবেশ করে; অভ্যন্তরীণ ওমানের ওপর ইবাদি ইমামতের শাসন কার্যত শেষ হয়। সূত্র কেবল মাসটি দেয়; মানচিত্রে 1 ডিসেম্বর 1955 দেখানো হয়।", "31f8761e"]},
"OLAYLAR_EK16:1961-06-19:0":{"b": ["কুয়েত ব্রিটিশ আশ্রয় থেকে বেরিয়ে পূর্ণ স্বাধীনতা লাভ করল", "e9a86d04"], "d": ["কুয়েত ও যুক্তরাজ্যের মধ্যে 1961 সালের 19 জুন বিনিময় হওয়া নোটের মাধ্যমে 1899 সালের চুক্তি থেকে চলা ব্রিটিশ আশ্রয় শেষ হয় এবং কুয়েত পূর্ণ স্বাধীন হয়। মানচিত্রে কুয়েতের ব্রিটিশ স্তর এই দিনে শেষ হয়।", "eb64fb65"]},
"OLAYLAR_EK16:1971-09-03:0":{"b": ["ইংল্যান্ডের সঙ্গে চুক্তি শেষ হওয়ায় কাতার স্বাধীনতা ঘোষণা করল", "8f288cc6"], "d": ["গ্রেট ব্রিটেনের সঙ্গে আশ্রয়চুক্তিগুলো শেষ হওয়ার তারিখের পর কাতার 1971 সালের 3 সেপ্টেম্বর স্বাধীনতা ঘোষণা করে। মানচিত্রে দোহার ব্রিটিশ স্তর এই দিনে শেষ হয়।", "997a4b35"]},
"OLAYLAR_EK17:1369-01-01:0":{"b": ["ইস্তিরানজা দুর্গসমূহ: পিনারহিসার, কিরকিলিসে (কিরক্লারেলি) ও ভিজের বিজয়", "c6b1a9c1"], "d": ["1369 সালের শীত এডির্ন প্রাসাদে কাটানো প্রথম মুরাদ বসন্তে বাইজেন্টাইনদের বিরুদ্ধে আবার অভিযানে নামেন এবং ইস্তিরানজা পর্বতের পাদদেশের পিনারহিসার, কিরকিলিসে ও ভিজে দুর্গ দখল করেন। এই বিজয়গুলো কনস্টান্টিনোপলে আতঙ্ক ছড়ায় এবং সম্রাট পঞ্চম ইওয়ানেস সাহায্য চাইতে পোপের কাছে যাওয়ার সিদ্ধান্ত নেন।", "61aac0e3"]},
"OLAYLAR_EK17:1485-01-01:0":{"b": ["তাশখন্দ মোগলিস্তানের খান ইউনুস খানের শাসনে গেল", "a37ee010"], "d": ["তিমুরি শাহজাদাদের মধ্যে সিংহাসনের লড়াইয়ের সময় তাশখন্দ ও তার আশপাশ পূর্ব চাগতাই (মোগলিস্তান) খান ইউনুস খানের হাতে যায়। দুই বছর পর ইউনুস খান মারা গেলে তাঁর ছেলে মাহমুদ খান স্থলাভিষিক্ত হন; 1503 সালে শেইবানি খানের উজবেকরা দখল করা পর্যন্ত শহর মোগল খানদের হাতেই ছিল।", "07459832"]},
"OLAYLAR_EK17:1504-01-01:0":{"b": ["বাবর ফারগানা উজবেকদের ছেড়ে কাবুলে গেলেন", "69df593c"], "d": ["ওমর শেখ মির্জার ছেলে তিমুরি বাবর 1494 সাল থেকে শাসন করা ফারগানা মুহাম্মদ শেইবানি খানের সঙ্গে যুদ্ধের পর উজবেকদের ছেড়ে দেন এবং হিন্দুকুশ পেরিয়ে কাবুলে বসতি স্থাপন করেন।", "21d1ed8c"]},
"OLAYLAR_EK17:1513-01-01:0":{"b": ["পিরি রাইস বর্তমান পর্যন্ত টিকে থাকা সবচেয়ে প্রাচীন বিশ্বমানচিত্র আঁকলেন", "6ef941f5"], "d": ["পিরি রাইস গেলিবোলুতে 919 হিজরি (1513) তারিখের বিশ্বমানচিত্র আঁকেন; টিডিভি ইসলাম বিশ্বকোষ অনুসারে মানচিত্রের উৎসের মধ্যে 'প্রাচ্য ও পাশ্চাত্য বিশ্ব থেকে তাঁর কাছে আসা প্রাচীন মানচিত্র এবং ক্রিস্টোফার কলম্বাসের মানচিত্রও' আছে — অর্থাৎ এটি কলম্বাসের তৎকালে হারিয়ে গেছে বলে ধরা মূল নৌমানচিত্রের চিহ্ন বহন করে বলে মনে করা হয়। মানচিত্রটি তিনি 923 হিজরিতে (1517) কায়রোতে সুলতান প্রথম সেলিমকে উপহার দেন। বর্তমান পর্যন্ত কেবল এর একটি অংশ টিকে আছে, যাতে শুধু পশ্চিম/আটলান্টিক উপকূল (স্পেন, পর্তুগাল, পশ্চিম আফ্রিকা, দক্ষিণ আমেরিকার পূর্ব উপকূল) দেখানো; এই অংশ 1929 সালে তোপকাপি প্রাসাদে পুনরাবিষ্কৃত হয় এবং ইউনেস্কো স্মৃতি-বিশ্ব তালিকাভুক্ত।", "78561b0b"]},
"OLAYLAR_EK17:1534-06-01:0":{"b": ["কার্স অঞ্চলের একীভবন: শুরেগেল, আরপাচায় ও দিগোরের অটোমান শাসনে আসা", "10f16b5c"], "d": ["ইরাকেইন অভিযানের সময় পাসিন, শুরেগেল ও ওলতু দুর্গ অটোমানদের হাতে আসে; কার্স দুর্গও এ সময়েই অন্তর্ভুক্ত হয়েছিল বলে প্রবল সম্ভাবনা আছে। কার্সের উত্তর ও পূর্বের আরপাচায় ও দিগোর অঞ্চল একই অভিযানে অটোমান নিয়ন্ত্রণে আসে।", "f8a4288a"]},
"OLAYLAR_EK17:1538-10-01:0":{"b": ["শিরভানশাহদের অবসান: আলকাস মির্জা শাহরুখকে বন্দি করলেন, শিরভান সাফাভি প্রদেশ হল", "e6d64114"], "d": ["শাহ তাহমাস্পের পাঠানো আলকাস মির্জা শিরভান লুট করে বাইকুর্দ দুর্গ দখল করেন এবং পনেরো বছর বয়সী শিরভানশাহ শাহরুখকে বন্দি করে তাবরিজে নিয়ে যান। অঞ্চলে দীর্ঘ সময় কর্তৃত্ব চালানো শিরভানশাহদের শাসন এভাবে শেষ হয়; শিরভান সাফাভি রাষ্ট্রের একটি প্রদেশে পরিণত হয়।", "47532c27"]},
"OLAYLAR_EK17:1552-01-01:0":{"b": ["আলজিয়ার ওজাকের সাহারার দিকে বিস্তার — তুগ্গুর্ত-ওয়ারগলা করদ হল, তিলিমসান চূড়ান্তভাবে বিজিত", "705ec920"], "d": ["টিডিভির তিলিমসান নিবন্ধ অনুযায়ী 960 (1553) সালে আলজিয়ার থেকে পাঠানো এক বিশাল বাহিনী সালিহ রেইসের নেতৃত্বে শহরটি চূড়ান্তভাবে দখল করে এবং তিন শতকের জেয়ানি রাজবংশের অবসান ঘটায়। একই সময়ে (1552) সালিহ রেইস স্বাধীন সুলতানি তুগ্গুর্ত ও ওয়ারগলার বিরুদ্ধে অভিযান চালান; অটোমান বাহিনী তুগ্গুর্ত দখল করে ওয়ারগলার দিকে এগোয়, দুটি সুলতানিই করদ হয়; পথে বিসক্রায় স্থায়ী অটোমান সেনানিবাস রাখা হয়। এভাবে আলজিয়ার ওজাকের সীমানা প্রথমবার টেল আটলাসের পর্বতমালা পেরিয়ে সাহারার প্রান্তে পৌঁছায়। মুস্তাগানিমের সামনের বড় যুদ্ধ অবশ্য এই বছরে নয়, 1558 সালে হয়েছিল: হাসান পাশা সেখানে স্পেনীয় কাউন্ট আলকাউদেতেকে পরাজিত করে উত্তর আফ্রিকায় স্পেনীয় আক্রমণের অবসান ঘটান।", "da55aa7d"]},
"OLAYLAR_EK17:1557-01-01:0":{"b": ["হাবেশ প্রদেশের প্রতিষ্ঠা — লোহিত সাগরের উপকূল অটোমান শাসনে এল", "7dd470ec"], "d": ["পর্তুগালের আবিসিনিয়া হয়ে লোহিত সাগরে অনুপ্রবেশ ঠেকাতে গঠিত এই প্রদেশ টিডিভির হাবেশ প্রদেশ নিবন্ধ অনুযায়ী 15 শাবান 962 (5 জুলাই 1555) আনুষ্ঠানিকভাবে প্রতিষ্ঠিত হয়, সানজাক কেন্দ্র হয় সুয়াকিন। ওজদেমির পাশা 1555 সালের শরতে অভিযান শুরু করেন; মাসাওয়া বন্দর নিয়ন্ত্রণকারী দাহলাক দ্বীপপুঞ্জ দখল করেন এবং 2 এপ্রিল 1557 তারিখে মাসাওয়া শহর, তারপর আরকিকো অধিকার করেন। বিজয়ের ধারা চলে 1558 সালে তিগ্রে প্রদেশ এবং 1559 সালে দেবারওয়া অটোমান কর্তৃত্বে আসার মধ্য দিয়ে।", "7bb5b28b"]},
"OLAYLAR_EK17:1606-10-11:0":{"b": ["সেদেফকার মেহমেদ আগা প্রধান স্থপতি পদে নিযুক্ত হলেন — সুলতানাহমেদ মসজিদের স্থপতি", "27b66fce"], "d": ["আলবেনিয়ার ইলবাসান শহর থেকে 1562-63 সালে দেভশিরমে হিসেবে প্রাসাদে আনা মেহমেদ আগা স্থপতি সিনানের সান্নিধ্যে প্রশিক্ষিত হয়ে 1606 সালের 11 অক্টোবর অটোমান প্রধান স্থপতি পদে নিযুক্ত হন। টিডিভি ইসলাম বিশ্বকোষ একটি সমসাময়িক সূত্র থেকে উদ্ধৃত করে যে তিনি 'কোমল স্বভাব, বিনয়ী, কথার খেলাপ না করা, ধার্মিক ও বুদ্ধিমান' ছিলেন। তিন বছর পর প্রথম আহমেদের আদেশে সুলতানাহমেদ মসজিদের নির্মাণ শুরু করবেন এমন মেহমেদ আগা কাবার সংস্কার থেকে ইস্তানবুল ও এডির্নের বহু ঝরনা ও মসজিদ পর্যন্ত বিস্তৃত কীর্তির স্বাক্ষর রাখেন। ছয় মিনার নিয়ে মক্কার কাবার সঙ্গে 'সমতা' বিতর্ক একটি প্রচলিত লোককথা; বিশ্বকোষীয় সূত্র তা নিশ্চিত করে না, বিন্যাসটিকে কেবল 'তখন পর্যন্ত পরীক্ষিত নয়' বলে বর্ণনা করে।", "a4c538fd"]},
"OLAYLAR_EK17:1617-11-22:0":{"b": ["নতুন সুলতান প্রথম মুস্তাফা: ফ্যাকাসে মুখ ও উদাস দৃষ্টির এক 'কাফেস' বন্দী সিংহাসনে", "c487b0d1"], "d": ["প্রথম আহমেদের মৃত্যুতে সিংহাসনে বসা প্রথম মুস্তাফা, ভাইয়ের জীবিত রেখে যাওয়া প্রথম শাহজাদা হিসেবে বছরের পর বছর কঠোর নজরদারিতে প্রাসাদে আবদ্ধ জীবন কাটিয়েছিলেন; টিডিভি ইসলাম বিশ্বকোষ তাঁকে 'ফ্যাকাসে মুখ, বিরল দাড়ি, বড় কালো চোখ ও নিষ্প্রভ দৃষ্টির' বলে বর্ণনা করে এবং এই দীর্ঘ বন্দিত্ব তাঁর মানসিক অবস্থাকে আরও খারাপ করেছিল বলে উল্লেখ করে। ছিয়ানব্বই দিনের এই প্রথম সালতানাতে তিনি রাষ্ট্রীয় কাজ চালাতে পারেননি; বিপরীতে তিনি প্রায়ই শিকারে যেতেন, জাহাজঘাঁটি ঘুরে দেখতেন, এমনকি পানিতে সোনা ফেলে মাছ দেখতেন বলে জনশ্রুতি আছে। ওজাক-জ্যানিসারি ও উলেমা তাঁকে শাসনের অযোগ্য মনে করায় 1618 সালের 26 ফেব্রুয়ারি তাঁকে সিংহাসনচ্যুত করে চৌদ্দ বছর বয়সী ভাইপো দ্বিতীয় ওসমানকে বসায়।", "f2d36b20"]},
"OLAYLAR_EK17:1630-08-19:0":{"b": ["এভলিয়া চেলেবির ভ্রমণ-স্বপ্ন — 'শাফাআত' বলতে গিয়ে 'সিয়াহাত' বলে ফেলা", "2d863e22"], "d": ["টিডিভি ইসলাম বিশ্বকোষ অনুসারে এভলিয়া চেলেবি চল্লিশ বছর স্থায়ী ভ্রমণজীবনের সূচনাকে 1040 হিজরির মুহররমের আশুরার রাতে (19 আগস্ট 1630) দেখা এক স্বপ্নের সঙ্গে যুক্ত করেন: স্বপ্নে ইস্তানবুলের আহি চেলেবি মসজিদে বিশাল জামাতের সঙ্গে তিনি নবী মুহাম্মদকে (সা.) দেখেন এবং উত্তেজনায় 'শাফাআত ইয়া রাসুলাল্লাহ' বলার জায়গায় 'সিয়াহাত ইয়া রাসুলাল্লাহ' বলে ফেলেন। জনশ্রুতি অনুসারে নবী এই জিহ্বার পিছলানিতে হেসে তাঁকে শাফাআত, ভ্রমণ ও জিয়ারত তিনটিরই সুসংবাদ দেন। তিনি কখনো বিয়ে করেননি, জীবন এই 'সিয়াহাত' প্রতিশ্রুতিতে উৎসর্গ করেছিলেন।", "ede1feb4"]},
"OLAYLAR_EK17:1632-01-01:0":{"b": ["চতুর্থ মুরাদের বৈপরীত্য: মদে আসক্ত সুলতানের মদ নিষেধাজ্ঞা, কুস্তিগিরের বাহু, সুরকারের কান", "3d2ea5e0"], "d": ["এগারো বছর বয়সে সিংহাসনে বসা চতুর্থ মুরাদের প্রথম বছরগুলোতে মা কোসেম সুলতানের প্রভাব নির্ধারক ছিল; টিডিভি ইসলাম বিশ্বকোষ বর্ণনা করে, কোসেম ছেলের ক্ষমতার প্রবণতায় শঙ্কিত হয়ে তাঁকে 'আমোদে প্ররোচিত করেন, উপহার ও উৎসবে ভুলিয়ে রাখেন'। প্রায় কুড়ি বছর বয়সে কার্যত শাসন হাতে নিলে তিনি দীর্ঘদেহী, চওড়া কাঁধের, রাশভারী শাসক ছিলেন — একজন শক্তিশালী মানুষকে কোমর ধরে তুলে হাস রুমে কয়েকবার ঘুরিয়েছিলেন বলে জনশ্রুতি আছে। টিডিভির নথিভুক্ত বিস্ময়কর বৈপরীত্যটি এই: তামাক ও আফিমকে ঘৃণা করতেন বলে কথিত সুলতান মদে অত্যধিক আসক্ত ছিলেন, তবু অভিযানের আগে কফি, তামাক এবং পরে মদও নিষিদ্ধ করেন; একই সঙ্গে তিনি মাকাম ঐতিহ্য অনুযায়ী সুর রচনা করার মতো সংগীতজ্ঞান রাখতেন।", "f2aba572"]},
"OLAYLAR_EK17:1632-01-01:1":{"b": ["লাগারি হাসান চেলেবির রকেটে উড্ডয়ন — কেবল এভলিয়া চেলেবি যার সূত্র সেই জনশ্রুতি", "1f02e3f2"], "d": ["এভলিয়া চেলেবির সিয়াহাতনামা অনুসারে লাগারি হাসান চেলেবি চতুর্থ মুরাদের সামনে সারায়বুরনুতে পঞ্চাশ ওকা বারুদে সাত শাখাযুক্ত একটি আতশবাজি-যন্ত্র তৈরি করেন এবং 'সুলতান, আপনাকে আল্লাহর হাতে সঁপে দিলাম, ঈসা নবীর সঙ্গে কথা বলতে যাচ্ছি' বলে তাতে চড়েন। জনশ্রুতি অনুযায়ী প্রায় 250 মিটার উপরে ওঠা হাসান চেলেবি শিকারি বাজের ডানার মতো যন্ত্র দিয়ে সমুদ্রে ভেসে নেমে সাঁতরে সুলতানের কাছে ফেরেন এবং বিনিময়ে দৈনিক সত্তর আকচে বেতনের সিপাহি পদ লাভ করেন।", "ef620ef6"]},
"OLAYLAR_EK17:1638-12-24:0":{"b": ["কেমানকেশ কারা মুস্তাফা পাশা প্রধান উজির হলেন — আর্থিক সংস্কারের যুগ শুরু", "583846a4"], "d": ["বাগদাদ অভিযানে তাইয়ার মেহমেদ পাশার শহিদ হওয়ার পর 17 শাবান 1048 (24 ডিসেম্বর 1638) তারিখে প্রধান উজির হওয়া কেমানকেশ কারা মুস্তাফা পাশা সুলতান ইব্রাহিমের আমলে কঠোর আর্থিক শৃঙ্খলা প্রয়োগ করেন: জ্যানিসারি ও সিপাহির সংখ্যা এক-তৃতীয়াংশে নামিয়ে আনেন, মুদ্রার মান ঠিক করেন, নির্ধারিত মূল্যব্যবস্থা (নার্খ) কঠোর করেন। টিডিভির দেওয়া অঙ্ক অনুযায়ী এই সাশ্রয় বছরে 6000 থলিতে পৌঁছায় — কিন্তু এই কড়া নিয়ন্ত্রণ প্রাসাদ মহলে তাঁর শত্রু বাড়িয়ে তোলে।", "2de299c2"]},
"OLAYLAR_EK17:1639-01-20:0":{"b": ["প্রথম মুস্তাফা পনেরো বছরের বিস্মৃতির পর মারা গেলেন", "b4c872cd"], "d": ["1623 সালের 10 সেপ্টেম্বর দ্বিতীয়বার সিংহাসনচ্যুত হওয়া প্রথম মুস্তাফা মৃত্যু পর্যন্ত পনেরো বছর একটি বন্ধ কক্ষে বন্দী অবস্থায় বাস করেন; এই বছরগুলো সম্পর্কে সূত্রে কোনো তথ্য নেই। তিনি 1048 হিজরির 15 রমযানে (20 জানুয়ারি 1639) ইন্তিকাল করেন — সূত্রের একাংশ একে স্বাভাবিক মৃত্যু গণ্য করে, আরেকাংশ এতে চতুর্থ মুরাদের হাত ছিল বলে দাবি করে।", "f153eced"]},
"OLAYLAR_EK17:1644-01-01:0":{"b": ["'পাগল ইব্রাহিম' নাকি ওঠানামা করা এক অসুস্থতা?", "2abc230f"], "d": ["টিডিভি ইসলাম বিশ্বকোষ (TDV İslâm Ansiklopedisi) বিংশ শতকে প্রচলিত হওয়া 'পাগল ইব্রাহিম' (Deli İbrahim) অভিধাটি স্পষ্টভাবে প্রত্যাখ্যান করে; সুলতানের নিজের চিঠিপত্রে ব্যথা, ক্ষুধামান্দ্য, পায়ের দুর্বলতা, মাথায় কুয়াশার অনুভূতি, বুকে চাপ ও অজ্ঞান হওয়ার উপসর্গের অভিযোগ থাকার কথা সেখানে উল্লেখ আছে। অন্যদিকে পদচ্যুতির সময়ে তাঁর সংগত ও যুক্তিসম্মত উত্তরগুলো ধারাবাহিক ভারসাম্যহীনতার দাবির সঙ্গে সাংঘর্ষিক; বিশ্বকোষ এই সিদ্ধান্তে পৌঁছায় যে তাঁর অবস্থা 'স্থির ছিল না, তীব্রতা বদলাত'। এই সময়ে কোসেম সুলতানের দায়িত্ব ক্রমশ বাড়ে এবং প্রাসাদে ডেকে আনা চিনজি হোজা (Cinci Hoca) 'কার্যকর দোয়ার' মাধ্যমে সুলতানকে আধ্যাত্মিক সান্ত্বনা দিলে রাজনীতিতে কোসেমের হস্তক্ষেপের ক্ষমতা বৃদ্ধি পায়।", "f3705d31"]},
"OLAYLAR_EK17:1647-01-01:0":{"b": ["সামুর ঘটনা — প্রধান উজির আহমেদ পাশার পশম কর ইব্রাহিমের পতন ডেকে আনল", "a2a47d62"], "d": ["সুলতান ইব্রাহিমের সামুর পশম ও আম্বরের নেশা প্রাসাদে ক্রমশ বাড়তে থাকলে প্রধান উজির আহমেদ পাশা 1647-1648 সালের দিকে রাষ্ট্রের উচ্চপদস্থদের কাছ থেকে জোর করে সামুর পশমের মূল্য আদায়ের প্রথা চালু করেন; টিডিভি ইসলাম বিশ্বকোষ উল্লেখ করে যে কর্মকর্তারা একে স্পষ্ট 'হারাজ' (জবরদস্তি কর) হিসেবে দেখতেন। জ্যানিসারি অফিসাররা সম্মিলিতভাবে অর্থ দিতে অস্বীকার করলে এই প্রতিরোধ সুলতানের পদচ্যুতির দিকে এগোনো প্রক্রিয়ার সরাসরি সূচনা হয়ে দাঁড়ায় — 7 আগস্ট 1648 সকালে সমবেত কর্মকর্তারা প্রথমে আহমেদ পাশাকে হত্যা করেন এবং পরদিন ইব্রাহিমকে সিংহাসনচ্যুত করেন।", "596c6d08"]},
"OLAYLAR_EK17:1648-05-01:0":{"b": ["'রাষ্ট্র চালাচ্ছে নারীরা' — ভারভার আলি পাশার সিভাস থেকে বিদ্রোহ", "5b027357"], "d": ["সিভাসের বেলারবে ভারভার আলি পাশা ইস্তানবুলের 'বায়রামিয়ে' নামে দাবি করা 30.000 কুরুশ দিতে অস্বীকার করেন এই বলে যে 'সিভাসের বার্ষিক আয় এই অঙ্ক পূরণ করে না'; টিডিভি ইসলাম বিশ্বকোষ অনুসারে তাঁর বিদ্রোহের কারণ ছিল সুলতানের অসুস্থতার ফলে রাষ্ট্রের কাজ নারীদের হাতে চলে যাওয়া এবং ঘন ঘন গভর্নর বদলের ফলে সৃষ্ট অস্থিরতা। 1648 সালের মে মাসে প্রথমে সামরিক সাফল্য পেলেও তিনি ইপশির মুস্তাফা পাশার কাছে পরাজিত হন; 20 মে 1648 তাঁকে মৃত্যুদণ্ড দেওয়া হয় এবং তাঁর মাথা ইস্তানবুলে পাঠানো হয়।", "e45166db"]},
"OLAYLAR_EK17:1686-08-30:0":{"b": ["আনাবোলু (নাউপলিয়ন) ভেনিসের হাতে হারানো — মোরিয়া যুদ্ধের মোড় ঘোরানো ঘটনা", "9d400557"], "d": ["টিডিভির আনাবোলু নিবন্ধ অনুযায়ী অবরোধের সময় শহরের মুসলিম বাসিন্দাদের যারা বেঁচে ছিল তারা আশপাশের দ্বীপ ও আনাতোলিয়ায় পালিয়ে যায় (1686)। প্রামাণ্য একাডেমিক সূত্র (Setton, Venice, Austria, and the Turks in the Seventeenth Century) অনুসারে কনিগসমার্কের বাহিনী দুই সপ্তাহ ধরে অটোমান ত্রাণবাহিনীর আক্রমণ প্রতিহত করে; 29 আগস্ট ইসমাইল পাশার আক্রমণ ভারী পরাজয়ে শেষ হলে দুর্গ কয়েক দিনের মধ্যে আত্মসমর্পণ করে। আনাবোলু 1540 সালে চুক্তির মাধ্যমে অটোমানদের হাতে আসা ভূমি ছিল; এটি হারানোর ফলে মোরিয়া উপদ্বীপ ভেনিসের হাতে যাওয়া ত্বরান্বিত হয়।", "592908a0"]},
"OLAYLAR_EK17:1687-08-01:0":{"b": ["চতুর্থ মেহমেদ শিকার ছাড়লেন — পদচ্যুতির প্রাক্কালে শেষ প্রয়াস", "7daa904b"], "d": ["মোহাচ পরাজয়ের (আগস্ট 1687) পর বেতন না পাওয়া সেনাবাহিনী বিদ্রোহ করে ইস্তানবুলের দিকে অভিযান চালায়। চতুর্থ মেহমেদ প্রধান উজিরের সিলমোহর নিয়ে পালানো সুলেমান পাশাকে হত্যা করিয়ে তাঁর মাথা সৈন্যদের দেখান এবং শিকারের সরঞ্জাম ও শিকারি কুকুর বিলিয়ে দিয়ে তওবার ঘোষণা দেন — কিন্তু এই ভঙ্গি সিংহাসন বাঁচাতে যথেষ্ট হয়নি; কয়েক মাস পরে তিনি পদচ্যুত হন।", "3f079bcd"]},
"OLAYLAR_EK17:1688-01-17:0":{"b": ["মুনকাচ (মুকাচেভে) দুর্গের তিন বছরের অবরোধের পর অস্ট্রিয়ার কাছে আত্মসমর্পণ", "ca2efc3d"], "d": ["সাম্রাজ্যিক বাহিনীর হাতে 1685 সালের শেষে অবরুদ্ধ মুনকাচ দুর্গ থকলি ইমরের স্ত্রী ইলোনা জ্রিনির নেতৃত্বে তিন বছর প্রতিরোধ করে; বহু প্রকাশিত তথ্যসূত্র অনুযায়ী দুর্গটি 17 জানুয়ারি 1688 তারিখে জেনারেল আন্তোনিও কারাফার কাছে আত্মসমর্পণ করে। এটি অটোমান-হাবসবুর্গ রণাঙ্গনে হাঙ্গেরিতে অটোমানপন্থী প্রতিরোধের শেষ বড় দুর্গগুলোর একটির পতন ছিল।", "d72ac109"]},
"OLAYLAR_EK17:1711-07-21:0":{"b": ["বালতাজি মেহমেদ পাশা ও জারিনা কাতেরিনার কাহিনি", "c1b739f1"], "d": ["প্রুতে অবরুদ্ধ রুশ সেনাবাহিনীর মুক্তিকে প্রথম কাতেরিনার বালতাজি মেহমেদ পাশার কাছে পাঠানো উপহার ও ঘুষের ফল বলে ব্যাখ্যা করা জনপ্রিয় বর্ণনা কয়েক শতক ধরে পুনরাবৃত্ত হয়েছে।", "f28badd1"]},
"OLAYLAR_EK17:1711-07-21:1":{"b": ["প্রুতে 'হারানো সুযোগ' বিতর্ক — দুটি মত", "61ee699c"], "d": ["অটোমান সেনাবাহিনী রুশ সেনাবাহিনীকে পুরোপুরি ঘিরে ফেলার পরও শান্তিতে সন্তুষ্ট হওয়া চুক্তির পরপরই ইতিহাসবিদদের মধ্যে বিতর্কের বিষয় হয়ে ওঠে — টিডিভির নিজস্ব ভাষায় 'একটি বড় সুযোগ হারানো হয়েছে এই বোধ জন্মেছিল এবং বিপরীত মতের লোকেরা এই বক্তব্য জোরালোভাবে তুলে ধরেছেন।' সমালোচকদের মতে জারকে বন্দি করা এবং রুশ সেনাবাহিনীর অস্ত্র হস্তগত করা সম্ভব ছিল; সমর্থকদের মতে উত্তর ইউরোপে সুইডেনের শক্তিবৃদ্ধি ঠেকাতে রাশিয়াকে সীমিতভাবে দুর্বল করাই ছিল 'বুদ্ধিমানের নীতি'। টিডিভি দুটি মতই উল্লেখ করে, কোনো পক্ষ নেয় না।", "d9f3213c"]},
"OLAYLAR_EK17:1725-01-01:0":{"b": ["বত্রিশ সদস্যের জ্ঞান ও অনুবাদ পরিষদ গঠিত হল", "0e3a713c"], "d": ["দামাদ ইব্রাহিম পাশার প্রধান উজিরত্বকালে ইস্তানবুলে টিডিভির ভাষায় 'যুগের একাডেমি বলা চলে' এমন বত্রিশ সদস্যের একটি আলিম-লেখক পরিষদ গঠিত হয়। পরিষদ আরবি, ফার্সি, গ্রিক ও লাতিন থেকে ইতিহাস, দর্শন ও ভূগোলের গ্রন্থ তুর্কিতে অনুবাদ করে — ইয়ানিয়ালি এসাদ এফেন্দির পঁচিশ জনের দল নিয়ে অ্যারিস্টটলের পদার্থবিদ্যা (Fizik) অনুবাদ এবং কবি নেদিমের একটি ইতিহাস-অনুবাদ পরিষদের নেতৃত্ব দেওয়া এর মধ্যে ছিল। দিন টিডিভিতে উল্লেখ নেই; শুধু বছর জানা যায়।", "980d9986"]},
"OLAYLAR_EK17:1730-11-25:0":{"b": ["প্রথম মাহমুদ পাত্রোনা হালিলকে প্রাসাদে ডেকে ফাঁদে ফেললেন", "6147059f"], "d": ["সিংহাসনে বসার সাত সপ্তাহ পর প্রথম মাহমুদ বিশ্বস্ত লোকদের — প্রাসাদে হাজি বেশির আগা, বাইরে ক্রিমিয়ার খান প্রথম কাপলান গিরায় — মাধ্যমে সামরিক নেতাদের নিজের পক্ষে টেনে পাত্রোনা হালিলের প্রভাব ভেঙে দেন। 25 নভেম্বর 1730 তারিখে তোপকাপি প্রাসাদের সুন্নত কক্ষের এক সভায় আমন্ত্রিত পাত্রোনা হালিল, মুসলু বেশে ও কেল মেহমেদ আগাকে ভেতরে নেওয়া হয়; প্রধান উজির সিলাহদার মেহমেদ পাশার ইশারায় আগে থেকে লুকিয়ে রাখা বত্রিশ জন সশস্ত্র লোক বেরিয়ে এসে তিনজনকেই হত্যা করে। প্রথম মাহমুদ এভাবে বিদ্রোহের নিয়ন্ত্রণ সম্পূর্ণ নিজের হাতে নেন।", "e3d9bb3d"]},
"OLAYLAR_EK17:1731-01-01:0":{"b": ["হুমবারাজি আহমেদ পাশা (বনেভাল) হুমবারাজি ওজাকের প্রধান হলেন", "27b0b1d7"], "d": ["আসল নাম ক্লোদ-আলেক্সান্দ্র কঁত দ্য বনেভাল (Claude-Alexandre Comte de Bonneval) এই ফরাসি বংশোদ্ভূত অফিসার প্রথমে ফ্রান্স ও অস্ট্রিয়ার সেনাবাহিনীতে কাজ করেন, পরে সারাজেভোতে ইসলাম গ্রহণ করে আহমেদ নাম নেন এবং 1729 সালে অটোমান রাষ্ট্রে আশ্রয় নেন। প্রথম মাহমুদের আমলে 1731 সালে হুমবারাজি ওজাকের প্রধান হওয়া আহমেদ পাশা উস্কুদার আয়াজমায় নির্মিত ব্যারাকে বসনিয়া থেকে আনা প্রায় 300 সৈন্যকে প্রশিক্ষণ দেন; তাদের সংখ্যা শীঘ্রই 600 ছাড়িয়ে যায় এবং তিনি নিজে গণিতের ক্লাসও নিতেন। ফ্রান্সের পক্ষে হাঙ্গেরিতে রাকোৎসির সঙ্গে বিদ্রোহের চেষ্টা তাঁর প্রভাব নড়বড়ে করে দেয় এবং 1738 সালে তাঁকে কাস্তামোনুতে নির্বাসিত করা হয়। 23 মে 1747 তারিখে ইস্তানবুলে তাঁর মৃত্যু হয়; তাঁর সমাধি গালাতা মেভলেভিখানার কবরস্থানে।", "5bfbc961"]},
"OLAYLAR_EK17:1738-08-01:0":{"b": ["সেমেন্দিরে হাবসবুর্গদের (হাঙ্গেরি রাজমুকুট) হাত থেকে পুনরুদ্ধার — 1737-39 যুদ্ধ", "63dcf604"], "d": ["টিডিভির সেমেন্দিরে নিবন্ধ অনুযায়ী 1717 সালে পাসারোভিৎস চুক্তিতে অস্ট্রিয়াকে ছেড়ে দেওয়া দুর্গটি 1737 সালে শুরু হওয়া অটোমান-অস্ট্রীয় যুদ্ধের দানিউব-সাভা রণাঙ্গনে অটোমান অগ্রগতির ফলে পুনরুদ্ধার হয়; হাবসবুর্গ (হাঙ্গেরি রাজমুকুট) বাহিনী অঞ্চলে আগস্ট 1738 পর্যন্ত টিকে থাকতে পেরেছিল, এই তারিখের পর সেমেন্দিরে আবার অটোমান শাসনে আসে। এক বছর পরে স্বাক্ষরিত বেলগ্রেড চুক্তি (18 সেপ্টেম্বর 1739) এই লাভকে — বেলগ্রেড ও উত্তর সার্বিয়ার সঙ্গে — স্বীকৃতি দেবে।", "d5f482ce"]},
"OLAYLAR_EK17:1738-08-01:1":{"b": ["মোরাভা উপত্যকার অটোমান শাসনে ফেরা — ইয়াগোদিনা, ক্রাগুয়েভাৎস ও চাচাক", "b219d3c9"], "d": ["আগস্ট 1738-এ সেমেন্দিরে পুনরুদ্ধারের ফলে সেমেন্দিরে ও অটোমান মূল ভূখণ্ডের মাঝে থাকা মোরাভা উপত্যকাও অটোমান শাসনে ফিরে আসে: ইয়াগোদিনা, ক্রাগুয়েভাৎস ও চাচাক এই তারিখ থেকে অটোমান বলে গণ্য। সূত্রগুলো এই তিন স্থানের প্রত্যাবর্তনের দিন আলাদাভাবে উল্লেখ করে না; মানচিত্রে সেমেন্দিরের দিনকে ভিত্তি ধরা হয়েছে। বেলগ্রেড চুক্তি (18 সেপ্টেম্বর 1739) এই অবস্থাকে স্বীকৃতি দেয়।", "560fe2bc"]},
"OLAYLAR_EK17:1789-04-07:0":{"b": ["প্রথম আবদুলহামিদ ওজির পতনের খবর পড়তে গিয়ে স্ট্রোকে মারা গেলেন", "6ac60365"], "d": ["টিডিভি ইসলাম বিশ্বকোষের abdulhamid-i নিবন্ধ অনুযায়ী, রুশ-অস্ট্রিয়ান যুদ্ধের কঠিন গতিতে স্বাস্থ্য ভেঙে পড়া প্রথম আবদুলহামিদ ওজি দুর্গ রুশদের দখলে যাওয়ার খবর দেওয়া প্রধান উজিরের প্রতিবেদন পড়ার সময় হঠাৎ স্ট্রোকে মারা যান (11 রজব 1203 / 7 এপ্রিল 1789)। তাঁর দেহ ইস্তানবুলের বাহচেকাপিতে নিজের নির্মিত সমাধিতে দাফন করা হয়। একই দিনে তাঁর ভাতিজা তৃতীয় সেলিম সিংহাসনে বসেন।", "f50d2d88"]},
"OLAYLAR_EK17:1799-01-03:0":{"b": ["অটোমান-রুশ প্রতিরক্ষা জোট — ফ্রান্সের বিরুদ্ধে যৌথ প্রতিরক্ষা", "c87079d1"], "d": ["নেপোলিয়নের মিসর দখলের প্রেক্ষিতে তৃতীয় সেলিম ও রুশ জার প্রথম পাভেল চৌদ্দ ধারার আট বছরের একটি প্রতিরক্ষা জোট গঠন করেন। পক্ষগুলো অভিন্ন বন্ধু ও শত্রু গ্রহণ, পারস্পরিক সহায়তা এবং আলাদা শান্তি না করার অঙ্গীকার করে।", "41183e81"]},
"OLAYLAR_EK17:1799-01-21:0":{"b": ["অটোমান-দুই সিসিলি (নেপলস) প্রতিরক্ষা জোট — ফ্রান্সের বিরুদ্ধে অভিন্ন লক্ষ্য", "1d2be816"], "d": ["ফ্রান্সের ইতালি, মাল্টা ও মিসর দখলের মুখে অটোমান রাষ্ট্র ও দুই সিসিলি রাজ্য নয় ধারার একটি প্রতিরক্ষা জোট করে। পক্ষগুলো যৌথভাবে যুদ্ধ চালানো, আলাদা শান্তি না করা এবং একে অপরকে স্থল ও নৌ সহায়তা দেওয়ার অঙ্গীকার করে।", "5a755b31"]},
"OLAYLAR_EK17:1800-04-02:0":{"b": ["সপ্ত দ্বীপ প্রজাতন্ত্র প্রতিষ্ঠিত — রুশ-অটোমান আশ্রয়ে আয়োনীয় দ্বীপপুঞ্জ", "08839694"], "d": ["1799 সালে রুশ-অটোমান যৌথ নৌবহর ফরাসিদের আয়োনীয় দ্বীপপুঞ্জ থেকে তাড়িয়ে দেয় (কর্ফু দুর্গের পতন 5 মার্চ 1799); 21 মার্চ 1800 তারিখের বারো ধারার চুক্তির মাধ্যমে দ্বীপগুলো অভ্যন্তরীণ বিষয়ে স্বায়ত্তশাসিত এবং পররাষ্ট্রে অটোমানদের অধীন 'সেজাইর-ই সাবআ-ই মুতেসিমা' প্রজাতন্ত্র (সপ্ত দ্বীপ প্রজাতন্ত্র) হিসেবে গঠিত হয়। 5 মার্চ 1799 থেকে এই দিন পর্যন্ত সময় যৌথ দখলের কাল।", "004ebb95"]},
"OLAYLAR_EK17:1807-07-07:0":{"b": ["তিলজিট — সপ্ত দ্বীপ প্রজাতন্ত্রের উপর রুশ অধিকার ফ্রান্সকে হস্তান্তর", "98a78beb"], "d": ["তিলজিটে রাশিয়া ও ফ্রান্সের মধ্যে হওয়া চুক্তির মাধ্যমে রাশিয়া সপ্ত দ্বীপের উপর নিজের অধিকার ফ্রান্সকে ছেড়ে দেয়; ফরাসি সেনারা 1807 সালের গ্রীষ্মে দ্বীপগুলোতে অবস্থান নেয় এবং সপ্ত দ্বীপ প্রজাতন্ত্রের অবসান ঘটে।", "4561dfb9"]},
"OLAYLAR_EK17:1815-11-05:0":{"b": ["আয়া মাভরা ও আয়োনীয় দ্বীপপুঞ্জের ব্রিটিশ আশ্রয়ে যাওয়া — নেপোলিয়ন-পরবর্তী ব্যবস্থা", "0af821dc"], "d": ["1797 সালে ফ্রান্সের হাতে যাওয়া আয়া মাভরা ও অন্যান্য আয়োনীয় দ্বীপ নেপোলিয়নের চূড়ান্ত পরাজয়ের পর 5 নভেম্বর 1815 তারিখে প্যারিসে ব্রিটেন, রাশিয়া, অস্ট্রিয়া ও প্রুশিয়ার মধ্যে স্বাক্ষরিত বিশেষ চুক্তির মাধ্যমে 'সপ্ত দ্বীপের যুক্তরাষ্ট্র' নামে ব্রিটিশ আশ্রয়ে ছেড়ে দেওয়া হয় — এটি 20 নভেম্বর 1815-র সাধারণ প্যারিস চুক্তি থেকে আলাদা একটি দলিল। এই আশ্রয় 1864 পর্যন্ত চলবে, তারপর দ্বীপগুলো গ্রিসকে হস্তান্তর করা হবে।", "b76e9e11"]},
"OLAYLAR_EK18:1455-06-20:0":{"b": ["প্রিজরেন বিজয় — কসোভোয় অটোমান সানজাক কেন্দ্র", "f84c220f"], "d": ["4 রজব 859 (20 জুন 1455) তারিখে বিজেতা সুলতান মেহমেদের নেতৃত্বাধীন অটোমান সেনাবাহিনী সার্বীয় ডেসপট জুরাজ ব্রানকোভিচ — অটোমান সূত্রে ভুলকোগলু — এর সঙ্গে যুদ্ধের পর প্রিজরেন দখল করে। ত্রয়োদশ শতকের মাঝামাঝি শহরটি বাইজেন্টাইনদের কাছ থেকে সার্বীয় রাজ্যে যায় এবং রাজা মিলুটিন, জার দুশান ও রাজা উরোশের আমলে রাজকীয় আবাস ছিল; দুশানের মৃত্যুর পর এর গুরুত্ব কমে। বিজয়ের পর একে সানজাকের কেন্দ্র করা হয় এবং 1912 সাল পর্যন্ত সাড়ে চার শতক এই মর্যাদা বজায় ছিল। যুগোস্লাভিয়া ভাঙার আগে প্রিজরেন ছিল বলকানের তিন ভাষা — আলবেনীয়, তুর্কি ও সার্বীয় — একসঙ্গে বলা হওয়া একমাত্র শহর।", "82ab4141"]},
"OLAYLAR_EK19:1789-07-14:0":{"b": ["বাস্তিলের পতন — ফরাসি বিপ্লবের সূচনা", "96e931f1"], "d": ["রাজা ষোড়শ লুইয়ের অর্থমন্ত্রী নেকারকে বরখাস্ত (11 জুলাই 1789) করায় সৃষ্ট ক্ষোভ ও অর্থনৈতিক সংকটের মাঝে প্যারিসের জনগণ অস্ত্র ও বারুদের দাবিতে বাস্তিল দুর্গের দিকে অভিযান চালায়। বিকেলে শুরু হওয়া সংঘর্ষে তিন হাজারের বেশি বিদ্রোহীর বিপরীতে মাত্র একশোর মতো রক্ষী থাকা দুর্গটি বিকাল 17:00 নাগাদ আত্মসমর্পণ করে; দুর্গের অধিনায়ক বের্নার-রেনে দ্য লোনেসহ কয়েকজন কর্মকর্তা নিহত হন, সাতজন বন্দি মুক্তি পায়। প্রায় খালি এবং আগে থেকেই ভাঙার পরিকল্পনা থাকা দুর্গটি ছিল রাজকীয় স্বৈরাচারের প্রতীক — এর পতনের খবর ষোড়শ লুইকে জানানো হলে 'না প্রভু, এটি বিদ্রোহ নয়, বিপ্লব' বলা হয় বলে বর্ণিত। 14 জুলাই আজ ফ্রান্সের জাতীয় দিবস এবং ঘটনাটি দ্রুত সারা দেশে ছড়িয়ে পড়া গণআন্দোলনের ও ফরাসি বিপ্লবের (1789-1799) প্রতীকী সূচনা বলে গণ্য — বিপ্লব পরবর্তী দশ বছরে চরম রাজতন্ত্র ভেঙে ইউরোপের রাজনৈতিক মানচিত্র এবং অটোমানসহ আন্তর্জাতিক ভারসাম্য স্থায়ীভাবে বদলে দেবে।", "ecc8db63"]},
"OLAYLAR_EK20:1315-04-28:0":{"b": ["মামলুক বাহিনী মালাত্যায় ঢুকল — শহর ইলখানিদের হাত থেকে মামলুক শাসনে গেল", "2540363d"], "d": ["মামলুকরা দামেস্কের নায়েব সাইফুদ্দিন তেঙ্গিজের নেতৃত্বে একটি সেনাবাহিনী মালাত্যার দিকে পাঠায়; বাহিনী 22 মুহাররম 715 (28 এপ্রিল 1315) তারিখে শহরে প্রবেশ করে। মালাত্যা সেই দিন পর্যন্ত ইলখানি কর্তৃত্বে ছিল এবং ইউফ্রেটিসের পশ্চিমে ইলখানি ও মামলুক প্রভাব-এলাকা যেখানে মিলেছে সেই রেখার মূল কেন্দ্র ছিল। শহরের হাত বদল দুই রাষ্ট্রের দীর্ঘ প্রতিদ্বন্দ্বিতায় মামলুকদের উচ্চ ইউফ্রেটিসের দিকে অগ্রগতি দেখায়। মালাত্যা এই তারিখের পর কিছুকাল এরেতনাওগ্লুদের শাসনে যাবে, 1338 থেকে আবার মামলুক কর্তৃত্বে ফিরবে।", "e762cf2c"]},
"OLAYLAR_EK20:1326-10-09:0":{"b": ["এশরেফোগ্লু বেইলিকের অবসান — বেইশেহির ও সেইদিশেহির হামিদোগ্লুদের হাতে গেল", "e4e70846"], "d": ["ইলখানি রাষ্ট্রের আনাতোলিয়া প্রধান গভর্নর আমির চোবানের ছেলে দেমিরতাশ স্বাধীনতা ঘোষণা করা তুর্কমেন বেইলিকগুলোর বিরুদ্ধে অভিযানে নামেন এবং বেইশেহিরে ঢুকে একসময় তাঁর বিরুদ্ধে অভিযোগকারী এশরেফোগ্লু সুলেমান শাহকে হত্যা করান (9 অক্টোবর 1326)। ত্রয়োদশ শতকের শেষে বেইশেহির ও সেইদিশেহির অঞ্চলে প্রতিষ্ঠিত এশরেফোগ্লু বেইলিক এভাবে শেষ হয়। টিডিভির হামিদোগ্লুলারি নিবন্ধ পরবর্তী ঘটনা দেয়: দেমিরতাশ যে এশরেফোগ্লুদের সরিয়েছিলেন তাদের বেইশেহির, সেইদিশেহির, আকশেহির ও দোয়ানহিসার হামিদ বেইলিকের সীমানায় যুক্ত হয়। একই বছর হামিদোগ্লু দুন্দার বেগকেও দেমিরতাশের হাতে সমর্পণ করে হত্যা করা হয়। এই ভূমি 1381 সালে প্রথম মুরাদের কাছে 80.000 স্বর্ণমুদ্রায় বিক্রি হয়ে অটোমান শাসনে যাবে।", "af867ff8"]},
"OLAYLAR_EK20:1338-01-01:0":{"b": ["মালাত্যা আবার মামলুক কর্তৃত্বে এল — এরেতনাওগ্লু শাসনের অবসান", "08b80aa2"], "d": ["1315 সালে মামলুক শাসনে আসা মালাত্যা ইলখানি রাষ্ট্রের ভাঙনের বছরগুলোতে কিছুকাল এরেতনাওগ্লুদের হাতে গিয়েছিল। টিডিভির মালাত্যা নিবন্ধ প্রত্যাবর্তনটি এক বাক্যে দেয়: 1338 থেকে শহরে আবার মামলুকরা কর্তৃত্ব করে। এটি আনাতোলিয়ার দক্ষিণ-পূর্বে ইলখানি-পরবর্তী শূন্যতা মামলুক ও এরেতনার মধ্যে ভাগ হওয়া বছরগুলোর একটি খণ্ডচিত্র।", "fdd56a26"]},
"OLAYLAR_EK20:1344-10-28:0":{"b": ["ইজমির বন্দর ক্রুসেডার নৌবহরের হাতে হারানো — আয়দিনোগ্লুদের নৌশক্তি ভাঙল", "775c65fe"], "d": ["পোপ ষষ্ঠ ক্লেমেন্টের উৎসাহে ভেনিস, জেনোয়া, সাইপ্রাস রাজ্য, রোডসের নাইট ও নাক্সোসের ডিউকের জাহাজে গঠিত ক্রুসেডার নৌবহর ইজমির বন্দর আয়দিনোগ্লুদের হাত থেকে ছিনিয়ে নেয় (28 অক্টোবর 1344)। বন্দরটি উমুর বেগের পিতা মেহমেদ বেগ 1328-1329 সালে জেনোয়ার মার্তিনো জাকারিয়ার কাছ থেকে নিয়েছিলেন এবং এটি ছিল এজিয়ানে আয়দিনোগ্লুদের নৌশক্তির ঘাঁটি। 1334 সালের সেপ্টেম্বরে একই উদ্দেশ্যে আসা একটি ক্রুসেডার নৌবহরকে ফিরে যেতে হয়েছিল; এই দ্বিতীয় অভিযান সফল হয়। উমুর বেগ প্রতিরোধ চালিয়ে যান এবং অন্য তুর্কি বেইলিকদের সঙ্গে মিলে 17 জানুয়ারি 1345 তারিখে ক্রুসেডার নৌবহরকে পরাজিত করলেও বন্দর পুনরুদ্ধার করা যায়নি।", "de5df043"]},
"OLAYLAR_EK20:1366-01-01:0":{"b": ["কারামানোগ্লু আলাউদ্দিন বেগ কোনিয়া, আকসারায় ও নিগদেকে কারামান ভূমিতে যুক্ত করলেন", "2b8b0f70"], "d": ["মামলুক সালতানাত আর্মেনীয় রাজ্যের অবসান ঘটিয়ে পুরো চুকুরোভা নিজেদের ভূমিতে যুক্ত করার পর এবং মধ্য আনাতোলিয়ায় এরেতনা রাষ্ট্রে সৃষ্ট বিশৃঙ্খলার সুযোগ নিতে চাওয়া কারামানোগ্লু আলাউদ্দিন বেগ কোনিয়াসহ (1366-1367) নিগদে কারাহিসার (ইয়েশিলহিসার), আকসারায়, আকশেহির, ইলগিন, ইসহাকলি ও কায়সেরি কারামান ভূমিতে যুক্ত করেন। সেলজুক রাজধানী হিসেবে কোনিয়ার যে ওজন ছিল তার কারণে কারামানোগ্লুদের কাছে এটি কেবল একটি শহর নয়, বৈধতার দাবি ছিল।", "986c1d2e"]},
"OLAYLAR_EK20:1467-01-01:0":{"b": ["উজুন হাসান কারাকোয়ুনলু রাষ্ট্রের অবসান ঘটালেন — ভান হ্রদ অববাহিকা আকোয়ুনলুদের হাতে গেল", "d8d6c2e8"], "d": ["আকোয়ুনলু শাসক উজুন হাসান 1467 সালে তাঁর বিরুদ্ধে অভিযানে আসা চিরশত্রু কারাকোয়ুনলু শাসক জাহান শাহকে অতর্কিতে আক্রমণ করে কারাকোয়ুনলু রাষ্ট্রের অবসান ঘটান। 1438 সাল থেকে শাসন করা জাহান শাহ সরে যাওয়ায় ভান হ্রদ অববাহিকা — ভান, বিতলিস, বারগিরি (মুরাদিয়ে), হোশাপ ও কোতুর — কারাকোয়ুনলুদের হাত থেকে আকোয়ুনলু শাসনে যায়। এই জয় আকোয়ুনলু রাষ্ট্রকে পূর্ব আনাতোলিয়া ও ইরানে একমাত্র বড় শক্তিতে পরিণত করে এবং এক প্রজন্ম পরে উজুন হাসানকে অটোমানদের মুখোমুখি করার পথে নামায়।", "4d0ea428"]},
"OLAYLAR_EK20:1489-03-04:0":{"b": ["জেম সুলতানকে রোমে আনা হল — জিম্মি কূটনীতি ও বার্ষিক 40.000 দুকাত", "1c6715a8"], "d": ["পোপ অষ্টম ইনোসেন্ট রোডসের নাইটদের প্রধান পিয়ের দ্যুবুসোঁর সঙ্গে চুক্তি করে জেম সুলতানকে রোমে আনান (4 মার্চ 1489)। জেম 29 জুলাই 1482 তারিখে রোডসে আশ্রয় নিয়েছিলেন, সেখান থেকে সাভয় ভূখণ্ডে, শেষে পোপের তত্ত্বাবধানে যান। দ্বিতীয় বায়েজিদ ভাইকে আটকে রাখার বিনিময়ে নাইটদের বার্ষিক 40.000 দুকাত দিতে এবং তাদের অটোমান ভূমিতে অবাধ বাণিজ্যের অধিকার দিতে সম্মত হয়েছিলেন। এই অর্থ করের মতো নয়, সিংহাসনের বৈধ প্রতিদ্বন্দ্বীকে ইউরোপে নিষ্ক্রিয় রাখার মূল্য: জেম মুক্ত হলে আনাতোলিয়ায় সেনা জড়ো করতে পারতেন, এমনকি ক্রুসেডের বৈধতার উৎসও হতে পারতেন। এভাবে একটি রাজবংশীয় সমস্যা ত্রিশ বছর ধরে অটোমান পররাষ্ট্রনীতির প্রধান সীমাবদ্ধতা হয়ে দাঁড়ায় — পশ্চিমে বায়েজিদের সতর্ক আচরণের কারণ এটাই। 1495 সালে জেমের মৃত্যুতে এই বাধা সরে যায়।", "60ca67f8"]},
"OLAYLAR_EK20:1490-01-01:0":{"b": ["জর্জিয়া রাজ্য তিন ভাগে ভাগ হল — কার্তলি, কাখেতি ও কুতাইসি কেন্দ্রিক ইমেরেতি", "f9c5f798"], "d": ["বাগরাতিদ রাজবংশ শাসিত ঐক্যবদ্ধ জর্জিয়া রাজ্য দীর্ঘ অভ্যন্তরীণ সংঘাতের পর আনুষ্ঠানিকভাবে তিন রাজ্যে ভাগ হয়: পূর্বে তিফলিস কেন্দ্রিক কার্তলি, উত্তর-পূর্বে কাখেতি এবং পশ্চিমে কুতাইসি কেন্দ্রিক ইমেরেতি। টিডিভির জর্জিয়া নিবন্ধ বিভাজন সমর্থন করে — 'জর্জিয়া তিন রাজ্যে (কার্তলিয়া, কাখেতিয়া, ইমেরেতিয়া) এবং পাঁচ বেইলিকে ভাগ হল'। এই বিভাজন পরবর্তী শতকের অটোমান-সাফাভি প্রতিদ্বন্দ্বিতায় নির্ধারক হয়: 1555 সালের আমাস্যা চুক্তি অনুযায়ী ইমেরেতি, দাদিয়ান, গুরিয়া ও দাভেলি অটোমানদের এবং কার্তলি, কাখেতি ও মোসখ সাফাভিদের ছেড়ে দেওয়া হয়। অর্থাৎ মানচিত্রে পশ্চিম ও পূর্ব জর্জিয়াকে ভিন্ন প্রভুর অধীন দেখা যাওয়া এই বিভাজন থেকেই আসে। সুলতান প্রথম সেলিম ট্রাবজোনের গভর্নর থাকাকালেই 1508 সালে ইমেরেতি (আচিকবাশ) রাজ্যকে আনুগত্য ও করের অধীন করেছিলেন।", "2473d866"]},
"OLAYLAR_EK20:1510-07-25:0":{"b": ["ত্রিপোলি স্পেনীয়দের দখলে — হাফসি কর্তৃত্বের অবসান", "de319d23"], "d": ["আম্মারোগ্লুদের পর ত্রিপোলিতে হাফসিদের কর্তৃত্ব 1510 সাল পর্যন্ত চলে। সেই বছর ওলিভেতোর কাউন্ট দন পেদ্রো নাভারোর নেতৃত্বে স্পেনীয়রা শহর দখল করে; গণহত্যা থেকে বেঁচে যাওয়া মুসলমানরা শহর ছেড়ে চলে যায়। এই দখল ছিল মেলিয়া থেকে ত্রিপোলি পর্যন্ত উত্তর আফ্রিকা উপকূলে স্পেনের দুর্গশৃঙ্খলের পূর্ব প্রান্ত। ত্রিপোলির জনগণ 925 (1519) সালে ইস্তানবুলে প্রতিনিধিদল পাঠিয়ে স্পেনীয় আগ্রাসনের বিরুদ্ধে অটোমানদের সাহায্য চাইবে; শহর 1551 সালে তুরগুত রেইস ও সিনান পাশা দখল করে অটোমান শাসনে আসবে।", "f65b0ba2"]},
"OLAYLAR_EK20:1530-03-24:0":{"b": ["মাল্টা ও ত্রিপোলি সেন্ট জন নাইটদের দেওয়া হল — রোডস থেকে বিতাড়িত সংঘের নতুন ঘাঁটি", "2595729e"], "d": ["কানুনি সুলতান সুলায়মানের হাতে 928 (1522) সালে রোডস থেকে বিতাড়িত সেন্ট জন (হসপিটালার) নাইটরা আট বছর ঠিকানাহীন থাকার পর স্পেন-জার্মানির রাজা পঞ্চম কার্লোস কর্তৃক মাল্টায় বসতি পায়; একই অনুদানে ত্রিপোলির প্রতিরক্ষাও সংঘকে দেওয়া হয়। আদর্শ বন্দরের কারণে মাল্টা সমুদ্রে প্রভাবশালী নাইটদের জন্য উপযুক্ত ঘাঁটি হয়ে ওঠে: তারা প্রথমে বিরগুতে বসতি করে, সেন্ট অ্যাঞ্জেলো দুর্গ সুরক্ষিত করে এবং সেঙ্গলেয়া প্রান্তে সেন্ট মিশেল দুর্গ নির্মাণ করে। এই বসতি ভূমধ্যসাগরের মাঝখানে অটোমান সমুদ্রপথ বিচ্ছিন্ন করা স্থায়ী শত্রু ঘাঁটির জন্ম দেয়; 947 (1540) সালে তুরগুত রেইসের গোজোতে হামলা দিয়ে শুরু হওয়া সংঘাত 1565 সালের মাল্টা অবরোধ পর্যন্ত চলবে।", "3992bdbc"]},
"OLAYLAR_EK20:1648-10-24:0":{"b": ["ওয়েস্টফালিয়ার শান্তি — ত্রিশ বছরের যুদ্ধ শেষ, পবিত্র রোমের ঐক্য ভাঙল", "d7719f05"], "d": ["ত্রিশ বছরের যুদ্ধ (1618-1648) শেষ করা চুক্তিগুলো মুনস্টার ও অসনাব্রুকে একই দিনে স্বাক্ষরিত হয় (24 অক্টোবর 1648)। পবিত্র রোমান সাম্রাজ্যের তিনশোর মতো রাজ্য নিজস্ব পররাষ্ট্রনীতি চালানোর অধিকার পায়; সাম্রাজ্য রাষ্ট্র থেকে একটি ছাতায় পরিণত হয়। সুইডেন পশ্চিম পোমেরানিয়া ও স্টেটিন পায়, ব্র্যান্ডেনবুর্গ পূর্ব পোমেরানিয়া এবং ম্যাগডেবুর্গ আর্চবিশপরিকের প্রত্যাশা পায় — 1701 সালে রাজ্যের পথে হাঁটা হোহেনৎসোলার্নের ভূমি সঞ্চয় এখান থেকে শুরু। অটোমানদের জন্য এর গুরুত্ব পরোক্ষ কিন্তু বড়: হাবসবুর্গরা পশ্চিম রণাঙ্গন থেকে সরে এলে মধ্য ইউরোপে আবার পূর্বমুখী হতে পারা একটি শক্তি জন্ম নেয়।", "21478661"]},
"OLAYLAR_EK20:1701-01-18:0":{"b": ["প্রুশিয়া রাজ্য ঘোষিত — প্রথম ফ্রিডরিখ কনিগসবার্গে মুকুট পরলেন", "337a9f74"], "d": ["ব্র্যান্ডেনবুর্গের নির্বাচক তৃতীয় ফ্রিডরিখ সম্রাট প্রথম লিওপোল্ডের অনুমোদনে কনিগসবার্গে মুকুট পরে «প্রুশিয়ার রাজা» উপাধি নেন (18 জানুয়ারি 1701)। উপাধিটি পূর্ব প্রুশিয়া থেকে নেওয়া হয়, কারণ সেটি পবিত্র রোমান সাম্রাজ্যের বাইরে ছিল এবং সম্রাটের অধীন নির্বাচক কেবল সাম্রাজ্যের সীমার বাইরেই রাজা হতে পারতেন। হোহেনৎসোলার্ন রাজবংশের বিক্ষিপ্ত ভূমি এই তারিখের পর একটি রাষ্ট্রনামে পরিচিত হতে শুরু করে।", "203ac1b3"]}
});
